// Content for Decoded (node g36, ages 15–18, Chapter 5) — NEW v2 build to GDD 36 (mechanic-embodying), the
// media-literacy FINALE and summit of the 3–18 journey (Thread G · Values, Rights & Media). "The feed is
// engineered to use you — but you can learn to read it, and use it instead." 84 researched, India-grounded,
// non-explicit scenarios across decode-the-algorithm → decode-the-influence → decode-pornography → decode-yourself
// → the-decoder → grow-the-journey, each encoded as one of the shared v2 play actions (branch / strike-rewrite /
// reflect / sort / spot / match / role-play) — no binary "tap the right card". Lead: strike-rewrite (bust the
// myth), branch (your move), spot (catch the manipulation). Decode the MACHINE (algorithms, attention economy,
// filter bubbles), the INFLUENCE (misinformation, AI fakes/deepfakes, propaganda, scams, dark patterns),
// PORNOGRAPHY (gated, non-explicit, deeper than g28: staged performance, not real, not sex-ed, unrealistic, no
// shame; critical thinking; contrast with healthy info), YOURSELF (digital wellbeing, balance not abstinence),
// then synthesise into one "decode anything" habit, and GROW (Unlearn-Relearn-Grow; a digital-life charter
// carried for life). Critical, not cynical; agency over paranoia. A game about manipulation that uses NO dark
// patterns. India: viral forwards, deepfakes, scams, DPDP Act, cybercrime 1930 / cybercrime.gov.in. Non-explicit
// throughout; routes distress to help. Builds on g28 (Reality Check) & g12/g17; closes the journey before the c5
// capstone. gameId "decoded".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"dc-001","cat":"decode-the-algorithm","type":"strike-rewrite","hook":"\"My feed just shows me what's popular and true.\"","myth":{"un":"My feed shows me what's popular and true.","re":"It's engineered to maximise your engagement, not to inform you.","why":"What keeps you scrolling is selected for you, not what's most true."},"relearn":"Your feed is engineered to keep you scrolling, not to inform you.","persona":"any","source":"attention economy"},
  {"id":"dc-002","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"recommendation systems","relearn":"You see posts that drive engagement, not the most important or most accurate ones.","hook":"Spot the 2 real reasons the feed picked this post for you.","scene":[{"id":"a","text":"It provoked a strong reaction in others","trick":true},{"id":"b","text":"It's objectively the most important news today","trick":false},{"id":"c","text":"The algorithm predicts it'll keep you scrolling","trick":true},{"id":"d","text":"An editor judged it the most accurate report","trick":false},{"id":"e","text":"It was carefully fact-checked before reaching you","trick":false}],"why":"The feed picks for reaction and watch-time, not for what's most important or accurate."},
  {"id":"dc-003","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"reading the system","relearn":"Reading the whole system, not just spotting one fake, is the leap to digital wisdom.","hook":"Spot the 2 moves that keep you a passive target, not a decoder.","scene":[{"id":"a","text":"Reading how the whole feed system works","trick":false},{"id":"b","text":"Only ever chasing one fake at a time","trick":true},{"id":"c","text":"Asking why you were shown this at all","trick":false},{"id":"d","text":"Assuming the feed is just neutral and random","trick":true},{"id":"e","text":"Noticing which feeling a post is built to trigger","trick":false}],"why":"Chasing single fakes and calling the feed 'neutral' keep you reacting; reading the system is the wise leap."},
  {"id":"dc-004","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"how feeds work","relearn":"Feeds maximise engagement and create filter bubbles; they aren't neutral, universal or 'just the truth'.","hook":"Sort: how the feed actually works, or a comforting myth?","items":[{"id":"a","text":"It maximises your engagement"},{"id":"b","text":"\"It's a neutral window on the world\""},{"id":"c","text":"It creates filter bubbles"},{"id":"d","text":"\"Everyone sees the same feed\""},{"id":"e","text":"It picks what's likely to keep you watching"},{"id":"f","text":"\"It just shows the plain truth, ranked\""}],"bins":[{"id":"real","label":"How it works","valence":"pos"},{"id":"myth","label":"Comforting myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"}},
  {"id":"dc-005","cat":"decode-the-algorithm","type":"strike-rewrite","hook":"\"A filter bubble doesn't really affect what I think.\"","myth":{"un":"A filter bubble doesn't affect what I think.","re":"Seeing mostly one kind of view quietly narrows and hardens your sense of the world.","why":"You can't weigh views you're never shown."},"relearn":"Filter bubbles quietly narrow your view of the world.","persona":"any","source":"filter bubbles"},
  {"id":"dc-006","cat":"decode-the-algorithm","type":"branch","hook":"You notice your feed only shows one side of everything.","options":[{"text":"Deliberately seek other views and sources","consequence":"You pop the bubble and see more clearly.","outcome":"open","best":true},{"text":"Assume your feed is the whole picture","consequence":"Deliberately seek other views; your feed isn't the whole picture."}],"debrief":"Stepping outside the bubble on purpose is how you keep a clear view.","relearn":"Deliberately seek other views to escape the filter bubble.","persona":"any","source":"popping the bubble"},
  {"id":"dc-007","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"attention design","relearn":"Infinite scroll and auto-play are attention-capture design, not accidents.","hook":"Spot the 2 features designed to capture your attention, not serve you.","scene":[{"id":"a","text":"Infinite scroll with no natural stopping point","trick":true},{"id":"b","text":"A clear article with an end and a back button","trick":false},{"id":"c","text":"Auto-play yanking you to the next video","trick":true},{"id":"d","text":"A search you typed in yourself","trick":false},{"id":"e","text":"A bookmark you set to return to later","trick":false}],"why":"Infinite scroll and auto-play are built to hold your attention; the others leave you in charge."},
  {"id":"dc-008","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"agency","relearn":"Knowing the feed is designed lets you use it instead of being used by it.","hook":"Spot the 2 ways the feed grabs the wheel from you.","scene":[{"id":"a","text":"You choosing what to open on purpose","trick":false},{"id":"b","text":"Auto-play deciding your next hour for you","trick":true},{"id":"c","text":"You knowing why you were shown a post","trick":false},{"id":"d","text":"Endless scroll quietly setting your bedtime","trick":true},{"id":"e","text":"You closing the app once you got what you came for","trick":false}],"why":"Auto-play and endless scroll quietly drive; knowing the design lets you take the wheel back."},
  {"id":"dc-009","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"power","relearn":"Choosing on purpose and knowing the why is your power; auto-play and endless scroll is theirs.","hook":"Sort: gives the platform power over you, or gives you the power?","items":[{"id":"a","text":"Letting auto-play decide your time"},{"id":"b","text":"Choosing what to open on purpose"},{"id":"c","text":"Following the endless scroll"},{"id":"d","text":"Knowing why you see what you see"},{"id":"e","text":"Reacting to whatever the feed throws up"},{"id":"f","text":"Setting a limit and leaving when it's hit"}],"bins":[{"id":"them","label":"Their power","valence":"neg"},{"id":"you","label":"Your power","valence":"pos"}],"key":{"a":"them","b":"you","c":"them","d":"you","e":"them","f":"you"}},
  {"id":"dc-010","cat":"decode-the-algorithm","type":"strike-rewrite","hook":"\"If something's trending, it must be important and true.\"","myth":{"un":"If it's trending, it's important and true.","re":"Trending means it's spreading, often because it's emotional or engineered, not because it's true.","why":"Virality measures spread, not accuracy."},"relearn":"Trending measures spread, not truth or importance.","persona":"any","source":"virality"},
  {"id":"dc-011","cat":"decode-the-algorithm","type":"match","persona":"any","source":"attention economy","relearn":"Your attention is the platform's currency; scroll with eyes open, not in fear.","hook":"Match the attention-economy fact to what it means for you.","pairs":[{"left":"You're the product","right":"Your attention is what's sold"},{"left":"Engagement is the goal","right":"Not your wellbeing or the truth"},{"left":"Scroll with eyes open","right":"Self-respect, not paranoia"},{"left":"Free app, paid with you","right":"Your data and time fund it"},{"left":"Ranked, not chronological","right":"Order chosen to hold you"}]},
  {"id":"dc-012","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"engineered feeds","relearn":"Outrage-on-top and content tuned to your weak spots are engineered; time-order and your own search are more neutral.","hook":"Sort: a sign of an engineered feed, or more neutral?","items":[{"id":"a","text":"Outrage keeps rising to the top"},{"id":"b","text":"A simple time-ordered list"},{"id":"c","text":"Content tuned to your weak spots"},{"id":"d","text":"A plain result you searched for"},{"id":"e","text":"Posts ranked to maximise your watch-time"},{"id":"f","text":"A friend's profile you opened directly"}],"bins":[{"id":"engineered","label":"Engineered","valence":"uhoh"},{"id":"neutral","label":"More neutral","valence":"neutral"}],"key":{"a":"engineered","b":"neutral","c":"engineered","d":"neutral","e":"engineered","f":"neutral"}},
  {"id":"dc-013","cat":"decode-the-algorithm","type":"branch","hook":"You catch yourself scrolling far longer than you meant to.","options":[{"text":"Recognise the design, and reclaim the choice to stop","consequence":"You take your attention back.","outcome":"reclaim","best":true},{"text":"Blame yourself for 'no willpower'","consequence":"It's engineered to hold you; recognise the design and reclaim the stop, no self-blame."}],"debrief":"Long scrolls are by design; reclaiming the stop is reading the machine.","relearn":"Recognise the design and reclaim the choice to stop; it's not just 'willpower'.","persona":"any","source":"design vs willpower"},
  {"id":"dc-014","cat":"decode-the-algorithm","type":"reflect","hook":"Lensy: which 'read the machine' insight will change how you use your feed?","prompt":"Pick one.","options":["It's engineered for engagement","Filter bubbles are real","Trending isn't true","I can use it on purpose"],"affirm":"Carry that insight, and the feed works for you instead of on you.","relearn":"Engineered feeds, filter bubbles, trending-isn't-true: read the machine.","persona":"any","source":"consolidation"},
  {"id":"dc-015","cat":"decode-the-influence","type":"strike-rewrite","hook":"\"I'm too smart to be manipulated online.\"","myth":{"un":"I'm too smart to be manipulated.","re":"Everyone is targeted; manipulations work precisely while they stay invisible.","why":"Overconfidence is exactly what manipulators count on."},"relearn":"Everyone's targeted; manipulation works while it's invisible, not on the 'dumb'.","persona":"Veer","source":"manipulation / humility"},
  {"id":"dc-016","type":"sort","persona":"any","source":"disinformation / astroturfing","hook":"Sort the influence technique to its family.","items":[{"id":"a","text":"A false story spread on purpose"},{"id":"b","text":"An honest mistake shared widely"},{"id":"c","text":"Fake 'grassroots' accounts pushing a line"},{"id":"d","text":"A genuine personal opinion"},{"id":"e","text":"Paid bots flooding one hashtag"},{"id":"f","text":"A friend's honest first-hand account"}],"bins":[{"id":"manip","label":"Deliberate manipulation","valence":"neg"},{"id":"not","label":"Not manipulation","valence":"pos"}],"key":{"a":"manip","b":"not","c":"manip","d":"not","e":"manip","f":"not"},"relearn":"Deliberate false stories, fake 'grassroots' and paid bots are manipulation; honest mistakes and real views aren't.","cat":"decode-the-influence"},
  {"id":"dc-017","cat":"decode-the-influence","type":"strike-rewrite","hook":"\"If a video looks real, it's real.\"","myth":{"un":"If a video looks real, it's real.","re":"AI can make convincing fakes; verify the source, don't trust the look.","why":"'Looks real' stopped being proof."},"relearn":"'Looks real' isn't proof; verify the source against fakes.","persona":"any","source":"deepfakes (verify source)"},
  {"id":"dc-018","cat":"decode-the-influence","type":"branch","hook":"A shocking clip is racing across your group chats.","options":[{"text":"Verify the source before believing or forwarding","consequence":"You catch a likely fake and don't spread it.","outcome":"verify","best":true},{"text":"Forward it because it's shocking","consequence":"Verify the source first; shock value is exactly what fakes exploit."}],"debrief":"Source-checking, not eyeballing, is the defense against modern fakes.","relearn":"Verify the source before believing or forwarding a shocking clip.","persona":"Arjun","source":"verify / India forwards"},
  {"id":"dc-019","type":"spot","persona":"any","source":"dark patterns","hook":"Spot the two dark patterns on this screen.","scene":[{"id":"a","text":"A pre-ticked box signing you up for extras","trick":true},{"id":"b","text":"A fake countdown to rush your choice","trick":true},{"id":"c","text":"A clear 'no thanks' button","trick":false},{"id":"d","text":"A plainly shown total price","trick":false},{"id":"e","text":"An easy way to cancel later","trick":false}],"why":"Pre-ticked boxes and fake countdowns are dark patterns nudging you into choices you didn't mean.","relearn":"Pre-ticked boxes and fake countdowns are dark patterns; clear choices and prices aren't.","cat":"decode-the-influence"},
  {"id":"dc-020","cat":"decode-the-influence","type":"strike-rewrite","hook":"\"Dark patterns and scams only fool careless people.\"","myth":{"un":"Dark patterns and scams only fool careless people.","re":"They're engineered to fool everyone; knowing the technique is the defense.","why":"They exploit normal human reflexes, not stupidity."},"relearn":"Dark patterns and scams fool everyone; knowing the technique defends you.","persona":"any","source":"dark patterns / scams"},
  {"id":"dc-021","type":"sort","persona":"any","source":"tells","hook":"Sort: a manipulation tell, or a reliable signal?","items":[{"id":"a","text":"Manufactured urgency"},{"id":"b","text":"A named, checkable source"},{"id":"c","text":"Engineered outrage"},{"id":"d","text":"Several reliable outlets agreeing"},{"id":"e","text":"\"They don't want you to know\""},{"id":"f","text":"A link to the original report"}],"bins":[{"id":"tell","label":"Manipulation tell","valence":"neg"},{"id":"reliable","label":"Reliable signal","valence":"pos"}],"key":{"a":"tell","b":"reliable","c":"tell","d":"reliable","e":"tell","f":"reliable"},"relearn":"Urgency, engineered outrage and secrecy framing are tells; named sources, corroboration and links are reliable.","cat":"decode-the-influence"},
  {"id":"dc-022","type":"spot","persona":"any","source":"propaganda","hook":"Spot the two propaganda techniques here.","scene":[{"id":"a","text":"Repeating a simple slogan endlessly","trick":true},{"id":"b","text":"Painting one group as the enemy","trick":true},{"id":"c","text":"Presenting evidence you can check","trick":false},{"id":"d","text":"Naming who made the claim","trick":false},{"id":"e","text":"Admitting a point against its side","trick":false}],"why":"Endless slogans and 'enemy' framing are propaganda; checkable evidence and fairness aren't.","relearn":"Endless slogans and 'enemy' framing are propaganda techniques; sourced, fair posts show neither.","cat":"decode-the-influence"},
  {"id":"dc-023","cat":"decode-the-influence","type":"branch","hook":"A 'too good to be true' offer wants your details urgently.","options":[{"text":"Treat it as a scam; don't click, verify independently","consequence":"You dodge the trap.","outcome":"safe","best":true},{"text":"Act fast before it 'expires'","consequence":"Urgent 'too good to be true' offers are scams; don't click, verify."}],"debrief":"Urgency plus 'too good to be true' is the scam signature.","relearn":"'Too good to be true' plus urgency is a scam; don't click, verify.","persona":"any","source":"scams"},
  {"id":"dc-024","cat":"decode-the-influence","type":"role-play","hook":"A friend is about to forward something you can tell is fake.","setup":"Stop it kindly. Say:","yourLine":[{"text":"\"Hang on, I think that's fake, let's check the source before sharing.\"","best":true},{"text":"Let them forward it"}],"relearn":"Kindly suggest checking the source before a friend forwards a fake.","persona":"any","source":"intervene"},
  {"id":"dc-025","cat":"decode-the-influence","type":"strike-rewrite","hook":"\"Once you've seen a few fakes, you can always tell.\"","myth":{"un":"Once experienced, you can always spot a fake.","re":"Fakes keep improving, so the durable skill is verifying the source, not trusting your eye.","why":"It's an arms race your eye can't win alone."},"relearn":"You can't always 'tell'; verify the source as fakes keep improving.","persona":"any","source":"deepfakes arms race"},
  {"id":"dc-026","type":"sort","persona":"any","source":"resistance","hook":"Sort: helps you resist manipulation, or leaves you open?","items":[{"id":"a","text":"Knowing the techniques"},{"id":"b","text":"Assuming you're immune"},{"id":"c","text":"Slowing down before reacting"},{"id":"d","text":"Sharing on impulse"},{"id":"e","text":"Asking who benefits"},{"id":"f","text":"Believing it because it's shocking"}],"bins":[{"id":"resist","label":"Helps resist","valence":"pos"},{"id":"open","label":"Leaves you open","valence":"neg"}],"key":{"a":"resist","b":"open","c":"resist","d":"open","e":"resist","f":"open"},"relearn":"Knowing the techniques, slowing down and asking who benefits resist; immunity-belief and impulse don't.","cat":"decode-the-influence"},
  {"id":"dc-027","type":"match","persona":"any","source":"empowerment","hook":"Match the manipulation truth to why it matters.","pairs":[{"left":"It works while invisible","right":"Seeing it defuses it"},{"left":"Everyone is targeted","right":"It's not about being smart"},{"left":"Know the technique","right":"You see it coming"},{"left":"Urgency is a tactic","right":"Slowing down protects you"},{"left":"Spread isn't proof","right":"Ask who benefits first"}],"relearn":"Manipulation works while invisible and targets everyone; knowing the technique lets you see it coming.","cat":"decode-the-influence"},
  {"id":"dc-028","cat":"decode-the-influence","type":"branch","hook":"You realise something you believed and shared was disinformation.","options":[{"text":"Correct it openly and learn the tell for next time","consequence":"You limit the harm and get sharper.","outcome":"growth","best":true},{"text":"Quietly ignore that you spread it","consequence":"Correcting it openly limits harm; everyone gets caught sometimes, learn the tell."}],"debrief":"Being fooled once is human; correcting and learning is the decoder's move.","relearn":"If you spread disinformation, correct it openly and learn the tell.","persona":"any","source":"accountability"},
  {"id":"dc-029","type":"match","persona":"any","source":"tells","hook":"Match the influence type to its tell.","pairs":[{"left":"Disinformation","right":"Deliberately false, no real source"},{"left":"Deepfake","right":"Looks real, source can't be verified"},{"left":"Dark pattern","right":"Nudges a choice you didn't mean"},{"left":"Phishing","right":"A look-alike link asking for your PIN"},{"left":"Propaganda","right":"Endless slogans and 'enemy' framing"}],"relearn":"Each influence type has a tell you can learn: false sources, unverifiable fakes, sneaky nudges, look-alike links.","cat":"decode-the-influence"},
  {"id":"dc-030","cat":"decode-the-influence","type":"reflect","hook":"Lensy: knowing the whole arsenal, do you feel like a decoder now, not a target?","prompt":"What do you think?","options":["Yes","A decoder","Not a target"],"affirm":"Knowing the techniques turns you from a target into a decoder, exactly the goal.","relearn":"Knowing the manipulation arsenal makes you a decoder, not a target.","persona":"any","source":"identity"},
  {"id":"dc-031","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Pornography shows what real sex and real bodies are like.\"","myth":{"un":"Pornography shows what real sex and bodies are like.","re":"It's staged performance by actors with edited, unrealistic bodies and acts, not real life.","why":"It's scripted, filmed and edited for views, like any other media."},"relearn":"Pornography is staged, edited performance, not real sex or real bodies.","persona":"any","source":"porn literacy (non-explicit)"},
  {"id":"dc-032","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Porn is a fine way to learn about sex and relationships.\"","myth":{"un":"Porn is a fine way to learn about sex and relationships.","re":"It isn't sex education; it often shows no real consent, communication or care.","why":"Accurate, trusted sources are how you actually learn."},"relearn":"Pornography is not sex education; it usually shows no real consent or care.","persona":"Vijay","source":"porn literacy"},
  {"id":"dc-033","cat":"decode-pornography","type":"strike-rewrite","hook":"\"The bodies and standards in porn are what you should expect or look like.\"","myth":{"un":"Porn's bodies and standards are what to expect or look like.","re":"They're selected, filtered and edited; real bodies vary hugely, and that's normal.","why":"It sets unrealistic standards, not a measure of you."},"relearn":"Porn's bodies and standards are unrealistic; real bodies vary and that's normal.","persona":"Sneha","source":"porn literacy / body image (links g21)"},
  {"id":"dc-034","cat":"decode-pornography","type":"strike-rewrite","hook":"\"What porn shows about how to treat a partner is just how it is.\"","myth":{"un":"How porn shows people treating each other is just how it is.","re":"It often lacks real consent and care and can normalise disrespect or aggression; real intimacy is mutual and respectful.","why":"Treating a performance as a model harms real relationships."},"relearn":"Porn can normalise disrespect; real intimacy is mutual, consensual and caring.","persona":"any","source":"porn literacy / consent (links g31)"},
  {"id":"dc-035","cat":"decode-pornography","type":"sort","hook":"Sort: what pornography is, vs what it isn't.","items":[{"id":"a","text":"Edited performance for views"},{"id":"b","text":"A model for real relationships"},{"id":"c","text":"Unrealistic bodies and acts"},{"id":"d","text":"Reliable sex education"},{"id":"e","text":"Scripted and filmed for an audience"},{"id":"f","text":"A picture of real consent and care"}],"bins":[{"id":"is","label":"What it is","valence":"tell"},{"id":"isnt","label":"What it isn't","valence":"neg"}],"key":{"a":"is","b":"isnt","c":"is","d":"isnt","e":"is","f":"isnt"},"relearn":"Porn is edited, scripted, unrealistic performance, not a relationship model, sex-ed, or real consent.","persona":"any","source":"porn literacy"},
  {"id":"dc-036","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If you've watched it, something's wrong with you.\"","myth":{"un":"If you've come across it, something's wrong with you.","re":"Curiosity is normal and many teens encounter it; what matters is thinking critically about it.","why":"Shame helps no one; understanding does."},"relearn":"Curiosity is normal; no shame, what matters is decoding it critically.","persona":"Counsellor","source":"porn literacy / no shame"},
  {"id":"dc-037","cat":"decode-pornography","hook":"A friend treats porn as a guide to what real sex should be.","relearn":"Remind a friend porn is a performance, not a how-to for real intimacy.","persona":"Vijay","source":"porn literacy / critical thinking","type":"role-play","setup":"Decode it for them, no shame. Say:","yourLine":[{"text":"\"That's a performance, not a how-to, real intimacy is about consent and talking.\"","best":true},{"text":"\"Yeah, that's how it's meant to go.\""}]},
  {"id":"dc-038","cat":"decode-pornography","type":"sort","hook":"Sort: a realistic idea of intimacy, or a porn-shaped distortion?","items":[{"id":"a","text":"Partners talk about what they want"},{"id":"b","text":"It's always instant and flawless"},{"id":"c","text":"Respect and consent come first"},{"id":"d","text":"Everyone matches an edited 'ideal'"},{"id":"e","text":"Either person can pause anytime"},{"id":"f","text":"One partner just performs for the other"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"distortion","label":"Distortion","valence":"neg"}],"key":{"a":"real","b":"distortion","c":"real","d":"distortion","e":"real","f":"distortion"},"relearn":"Real intimacy is talk, respect, consent and pausing; instant, flawless, 'ideal', one-sided is a distortion.","persona":"any","source":"porn literacy"},
  {"id":"dc-039","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Everyone watches it, so it must be harmless and accurate.\"","myth":{"un":"Everyone watches it, so it's harmless and accurate.","re":"Common doesn't mean accurate; relying on it can distort what you expect of yourself and others.","why":"Popularity isn't a reality check."},"relearn":"Common doesn't mean accurate; popularity isn't a reality check.","persona":"any","source":"porn literacy"},
  {"id":"dc-040","cat":"decode-pornography","type":"reflect","hook":"Lensy: it's fine to feel curious, and fine to close something that makes you uncomfortable. Okay?","prompt":"What do you think?","options":["Yes","Good to know","That helps"],"affirm":"Curiosity is human, and you're always allowed to look away, no shame either way.","relearn":"Curiosity is normal and you can always close what feels uncomfortable.","persona":"any","source":"agency / no shame"},
  {"id":"dc-041","cat":"decode-pornography","type":"branch","hook":"You want to actually understand sex and relationships, not from porn.","options":[{"text":"Go to trusted, accurate sources and people","consequence":"You learn the real, healthy picture.","outcome":"informed","best":true},{"text":"Treat porn as your teacher","consequence":"Porn isn't sex-ed; learn from trusted, accurate sources instead."}],"debrief":"For the real picture, trusted sources beat a performance every time.","relearn":"Learn about sex and relationships from trusted, accurate sources, not porn.","persona":"any","source":"finding accurate info"},
  {"id":"dc-042","cat":"decode-pornography","type":"role-play","hook":"A friend is confused or anxious from comparing themselves to porn.","setup":"Reassure them, no shame. Say:","yourLine":[{"text":"\"That's a performance, not real, and it's not a measure of you. No shame.\"","best":true},{"text":"\"Yeah, you should look like that.\""}],"relearn":"Remind a friend porn is performance, not a measure of them, no shame.","persona":"Sneha","source":"support / body image"},
  {"id":"dc-043","cat":"decode-pornography","type":"sort","hook":"Sort: a healthy, critical response, or an unhealthy one?","items":[{"id":"a","text":"Knowing it's not real and not sex-ed"},{"id":"b","text":"Treating it as a relationship guide"},{"id":"c","text":"No shame, just critical thinking"},{"id":"d","text":"Comparing your body to it"},{"id":"e","text":"Closing what feels uncomfortable"},{"id":"f","text":"Expecting a partner to copy it"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"unhealthy","label":"Unhealthy","valence":"neg"}],"key":{"a":"healthy","b":"unhealthy","c":"healthy","d":"unhealthy","e":"healthy","f":"unhealthy"},"relearn":"Knowing it's not real, no shame, closing what's off is healthy; a guide, comparison or copying isn't.","persona":"any","source":"porn literacy"},
  {"id":"dc-044","cat":"decode-pornography","hook":"Match the porn-literacy truth to the relief it brings.","relearn":"Knowing it's a performance frees real intimacy from an impossible standard.","persona":"any","source":"wellbeing","type":"match","pairs":[{"left":"It's a performance","right":"Not a standard for you"},{"left":"It's not real","right":"Real intimacy is unpressured"},{"left":"It's not sex-ed","right":"Learn from trusted sources"},{"left":"Bodies are edited","right":"Real bodies vary, yours is fine"},{"left":"Curiosity is normal","right":"No shame in being curious"}]},
  {"id":"dc-045","cat":"decode-yourself","type":"branch","hook":"Notifications keep pulling you out of everything you do.","options":[{"text":"Turn off non-essential notifications and use tech on purpose","consequence":"You get your attention and focus back.","outcome":"intentional","best":true},{"text":"Stay reachable by every ping always","consequence":"Turning off non-essential pings and using tech on purpose protects your focus."}],"debrief":"Designing your notifications is part of using tech intentionally.","relearn":"Turn off non-essential notifications; use tech on purpose.","persona":"any","source":"digital wellbeing"},
  {"id":"dc-046","cat":"decode-yourself","type":"strike-rewrite","hook":"\"Comparing myself to people's feeds is just me being realistic.\"","myth":{"un":"Comparing myself to feeds is being realistic.","re":"You're comparing your real life to others' curated highlight reels, that's not realistic.","why":"Feeds hide the ordinary and hard parts you judge yourself against."},"relearn":"Comparing your life to curated feeds isn't realistic; it's unfair to you.","persona":"Sneha","source":"comparison (links g21/g28)"},
  {"id":"dc-047","cat":"decode-yourself","type":"sort","hook":"Sort: intentional digital habit, or being used by tech?","items":[{"id":"a","text":"Choosing when and why you go online"},{"id":"b","text":"Endless doomscrolling"},{"id":"c","text":"Protecting your privacy settings"},{"id":"d","text":"Oversharing without thinking"},{"id":"e","text":"Setting a limit before you scroll"},{"id":"f","text":"Letting autoplay decide your evening"}],"bins":[{"id":"intentional","label":"Intentional","valence":"pos"},{"id":"used","label":"Being used","valence":"neg"}],"key":{"a":"intentional","b":"used","c":"intentional","d":"used","e":"intentional","f":"used"},"relearn":"Choosing your use and guarding privacy is intentional; doomscrolling and oversharing is being used.","persona":"any","source":"intentional use"},
  {"id":"dc-048","cat":"decode-yourself","type":"reflect","hook":"Lensy: balance, not quitting, the digital world has real connection and joy too. Agree?","prompt":"What do you think?","options":["Yes","Balance","Use it well"],"affirm":"The goal isn't to quit, it's to use the good and guard against the rest.","relearn":"The aim is balance, not abstinence; use the good, guard against the rest.","persona":"any","source":"balance"},
  {"id":"dc-049","cat":"decode-yourself","type":"branch","hook":"You're posting something that'll be part of your lasting digital footprint.","options":[{"text":"Post as if future-you and others might see it","consequence":"Your footprint stays something you're glad of.","outcome":"footprint","best":true},{"text":"Post anything; the internet forgets","consequence":"Posts can resurface; post with future-you in mind."}],"debrief":"Your footprint lasts; a moment's post can outlive the moment.","relearn":"Post with future-you in mind; your digital footprint lasts.","persona":"any","source":"footprint"},
  {"id":"dc-050","cat":"decode-yourself","type":"branch","hook":"Scrolling is leaving you low and anxious lately.","options":[{"text":"Adjust your use and, if it persists, reach for support","consequence":"You protect your mental health.","outcome":"wellbeing","best":true},{"text":"Keep scrolling through the low feeling","consequence":"Adjust your use; if low feelings persist, reach for support (a trusted adult, Tele-MANAS 14416)."}],"debrief":"Tending your mental health is part of a healthy digital life.","relearn":"If scrolling lowers your mood, adjust use and reach for support if it persists.","persona":"Counsellor","source":"digital wellbeing / help"},
  {"id":"dc-051","cat":"decode-yourself","hook":"Spot the two habits where the phone is using you, not the other way round.","relearn":"Use technology on purpose, rather than being used by it.","persona":"any","source":"intentional use","type":"spot","scene":[{"id":"a","text":"Opening an app for a reason, then closing it","trick":false},{"id":"b","text":"Picking up the phone on reflex, again","trick":true},{"id":"c","text":"Deciding your screen time, not the app","trick":false},{"id":"d","text":"Scrolling with no idea why you started","trick":true},{"id":"e","text":"Muting pings so you can focus","trick":false}],"why":"Reflex-grabbing and scrolling for no reason are the phone using you; the rest is using it on purpose."},
  {"id":"dc-052","cat":"decode-yourself","type":"sort","hook":"Sort: protects your wellbeing online, or erodes it?","items":[{"id":"a","text":"Scroll breaks and sleep"},{"id":"b","text":"Comparing yourself constantly"},{"id":"c","text":"Curating who you follow"},{"id":"d","text":"Chasing every notification"},{"id":"e","text":"Keeping the phone out of bed"},{"id":"f","text":"Doomscrolling bad news at night"}],"bins":[{"id":"protects","label":"Protects it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"protects","b":"erodes","c":"protects","d":"erodes","e":"protects","f":"erodes"},"relearn":"Breaks, sleep and curating your feed protect wellbeing; comparison and chasing pings erode it.","persona":"any","source":"wellbeing"},
  {"id":"dc-053","cat":"decode-yourself","type":"branch","hook":"An app keeps asking for data and permissions it doesn't need.","options":[{"text":"Guard your privacy; only share what's necessary","consequence":"You protect your data and footprint.","outcome":"private","best":true},{"text":"Just tap 'allow all'","consequence":"Guard your privacy; share only what an app actually needs."}],"debrief":"Privacy is a habit; share the minimum, especially under the DPDP Act.","relearn":"Guard your privacy; only grant the data and permissions truly needed.","persona":"any","source":"privacy / DPDP"},
  {"id":"dc-054","cat":"decode-yourself","type":"reflect","hook":"Lensy: which digital-wellbeing habit do you most want to build?","prompt":"Pick one.","options":["Protect my attention","Resist comparison","Guard my privacy","Use it on purpose"],"affirm":"Building that habit makes your whole digital life healthier and more yours.","relearn":"Protecting attention, resisting comparison, privacy and intent are wellbeing habits.","persona":"any","source":"habits"},
  {"id":"dc-055","cat":"decode-yourself","type":"role-play","hook":"A friend is stuck in a comparison spiral over social media.","setup":"Reframe it for them. Say:","yourLine":[{"text":"\"That's their highlight reel, not their life, don't measure yourself against an edit.\"","best":true},{"text":"\"Yeah, their life is just better.\""}],"relearn":"Help a friend see feeds as highlight reels, not a measuring stick.","persona":"Sneha","source":"comparison / support"},
  {"id":"dc-056","cat":"decode-yourself","type":"strike-rewrite","hook":"\"Logging off or setting limits means you're missing out.\"","myth":{"un":"Setting limits means you're missing out.","re":"Intentional limits give you back time, focus and calm, that's gaining, not missing out.","why":"FOMO is itself an engineered feeling."},"relearn":"Setting limits is gaining time and calm, not missing out.","persona":"any","source":"FOMO"},
  {"id":"dc-057","cat":"decode-yourself","hook":"Spot the two moves that point the critical lens only outward, never at yourself.","relearn":"Decoding yourself matters as much as decoding the world.","persona":"any","source":"decode yourself","type":"spot","scene":[{"id":"a","text":"Noticing your own scrolling habits","trick":false},{"id":"b","text":"Only ever fact-checking other people","trick":true},{"id":"c","text":"Checking how tech affects your mood","trick":false},{"id":"d","text":"Assuming you're 'too smart' to be hooked","trick":true},{"id":"e","text":"Watching how a feed shapes your day","trick":false}],"why":"Only checking others and assuming you're immune skip the inward look that decoding yourself needs."},
  {"id":"dc-058","cat":"decode-yourself","type":"branch","hook":"You want a healthier relationship with your phone overall.","options":[{"text":"Set a few intentional habits and stick to them","consequence":"Your digital life steadies and serves you.","outcome":"healthy","best":true},{"text":"Wait for willpower to fix it someday","consequence":"A few intentional habits beat waiting on willpower; design your use."}],"debrief":"A healthy digital life is built from a few deliberate habits.","relearn":"Build a healthier digital life from a few intentional habits.","persona":"any","source":"habits"},
  {"id":"dc-059","cat":"the-decoder","type":"branch","hook":"The Decoder. You're handed any post from the information world. First move?","options":[{"text":"Ask: who made this and why?","consequence":"You start with the source and intent.","outcome":"decode","best":true},{"text":"Just react to how it makes you feel","consequence":"Start the Decoder with 'who made this and why?', not just your reaction."}],"debrief":"The Decoder starts with source and intent, before anything else.","relearn":"Decode anything by asking first: who made this and why?","persona":"any","source":"the decoder"},
  {"id":"dc-060","cat":"the-decoder","type":"match","hook":"Match each Decoder question to what it uncovers.","pairs":[{"left":"Who made it & why?","right":"Source and intent"},{"left":"How did the algorithm serve it?","right":"The machine"},{"left":"What's the manipulation?","right":"The technique"},{"left":"What's actually true?","right":"The verified facts"},{"left":"How will I act?","right":"My own decision"}],"relearn":"The Decoder uncovers source, the machine, the technique, the truth, then your choice.","persona":"any","source":"decoder questions"},
  {"id":"dc-061","cat":"the-decoder","type":"match","hook":"Match each Decoder move to where you'd use it.","pairs":[{"left":"Ask who benefits","right":"A 'miracle' weight-loss reel"},{"left":"Check the source","right":"A forwarded 'news' screenshot"},{"left":"Verify the facts","right":"A shocking quote from a leader"},{"left":"Spot the technique","right":"A countdown timer on a sale"},{"left":"Decide, don't react","right":"An outrage post built to be shared"}],"relearn":"Every Decoder move fits a real moment: claims, forwards, quotes, sales, outrage.","persona":"any","source":"decoder questions"},
  {"id":"dc-062","cat":"the-decoder","type":"branch","hook":"The Decoder. A viral health claim lands in your feed.","options":[{"text":"Run the Decoder: source, intent, algorithm, manipulation, truth","consequence":"You see straight through it.","outcome":"decoded","best":true},{"text":"Share it because it 'feels right'","consequence":"Run the full Decoder before sharing; 'feels right' isn't decoded."}],"debrief":"The Decoder applied fully turns a viral claim into something you can judge.","relearn":"Run the full Decoder on viral claims before believing or sharing.","persona":"any","source":"applying the decoder"},
  {"id":"dc-063","cat":"the-decoder","type":"spot","hook":"Spot the two reactions that skipped the Decoder.","scene":[{"id":"a","text":"Checked who posted it and why","trick":false},{"id":"b","text":"Shared it on a gut feeling","trick":true},{"id":"c","text":"Verified it against reliable outlets","trick":false},{"id":"d","text":"Believed it because it was trending","trick":true},{"id":"e","text":"Paused before reacting","trick":false}],"why":"Sharing on a gut feeling and trusting 'trending' skip the Decoder; checking and pausing are it.","relearn":"A decoded response checks source and verifies, not just reacts.","persona":"any","source":"decoder"},
  {"id":"dc-064","cat":"the-decoder","type":"branch","hook":"The Decoder. Someone you trust shares something you suspect is off.","options":[{"text":"Decode it kindly and check, regardless of who shared it","consequence":"You judge the content, not the messenger.","outcome":"clear","best":true},{"text":"Believe it because they shared it","consequence":"Decode the content itself; even trusted people share things unchecked."}],"debrief":"The Decoder judges the content, not who happened to send it.","relearn":"Decode the content, regardless of who shared it.","persona":"any","source":"source vs messenger"},
  {"id":"dc-065","cat":"the-decoder","type":"reflect","hook":"Lensy: one habit, decode anything, that you carry forever. Powerful, isn't it?","prompt":"What do you think?","options":["Yes","For life","My superpower"],"affirm":"One master habit, applied to anything, is a superpower you keep for life.","relearn":"'Decode anything' is one master habit you carry for life.","persona":"any","source":"master habit"},
  {"id":"dc-066","cat":"the-decoder","type":"role-play","hook":"You want to teach a younger sibling the Decoder.","setup":"Make it simple. Say:","yourLine":[{"text":"\"Before you believe anything online: who made it, why, and is it actually true?\"","best":true},{"text":"\"Just believe whatever's popular.\""}],"relearn":"Teach the Decoder simply: who made it, why, and is it true?","persona":"any","source":"passing it on"},
  {"id":"dc-067","cat":"the-decoder","type":"sort","hook":"Sort each move: part of the Decoder, or not?","items":[{"id":"a","text":"Asking who benefits"},{"id":"b","text":"Reacting on impulse"},{"id":"c","text":"Verifying what's true"},{"id":"d","text":"Sharing before checking"},{"id":"e","text":"Pausing for a few seconds"},{"id":"f","text":"Believing it because it's popular"}],"bins":[{"id":"in","label":"In the Decoder","valence":"pos"},{"id":"out","label":"Not in it","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Asking who benefits, verifying and pausing are the Decoder; impulse and unchecked sharing aren't.","persona":"any","source":"decoder"},
  {"id":"dc-068","cat":"the-decoder","type":"branch","hook":"The Decoder works, but it takes a moment of slowing down.","options":[{"text":"Build the pause in; a few seconds beats being fooled","consequence":"The habit becomes automatic.","outcome":"habit","best":true},{"text":"Skip it because you're in a hurry","consequence":"Build in the pause; a few seconds of decoding beats being fooled."}],"debrief":"A small, deliberate pause is what makes the Decoder work.","relearn":"Build in a short pause; decoding beats reacting in a hurry.","persona":"any","source":"the pause"},
  {"id":"dc-069","cat":"the-decoder","type":"reflect","hook":"Lensy: with the Decoder, almost nothing online can use you without you knowing. Feel that power?","prompt":"What do you think?","options":["Yes","Hard to fool","In control"],"affirm":"The Decoder is what keeps the information world working for you, not on you.","relearn":"The Decoder keeps the information world working for you, not on you.","persona":"any","source":"agency"},
  {"id":"dc-070","cat":"the-decoder","type":"reflect","hook":"Lensy: which Decoder question will you reach for most?","prompt":"Pick one.","options":["Who made it & why?","What's the manipulation?","What's actually true?","How will I act?"],"affirm":"Reaching for any of them makes you an active decoder, not a passive target.","relearn":"Any Decoder question makes you an active decoder, not a passive target.","persona":"any","source":"decoder"},
  {"id":"dc-071","cat":"grow-the-journey","type":"reflect","hook":"Lensy: for years we erased myths together, and rewrote the truth each time. Feel how far that's come?","prompt":"What do you think?","options":["Yes","A long way","So many myths"],"affirm":"Hundreds of myths unlearned and truths relearned, that's the journey you've made.","relearn":"You've spent years unlearning myths and relearning the truth.","persona":"any","source":"journey reflection"},
  {"id":"dc-072","cat":"grow-the-journey","type":"reflect","hook":"Lensy: the real lesson of the whole journey, learning never stops, and that's a good thing. Agree?","prompt":"What do you think?","options":["Yes","Keep learning","For life"],"affirm":"Learning never stopping is the whole point, you get to keep growing your whole life.","relearn":"Learning never stops, and that's a good thing.","persona":"any","source":"lifelong learning"},
  {"id":"dc-073","cat":"grow-the-journey","type":"strike-rewrite","hook":"\"Once you grow up, you stop needing to question the media.\"","myth":{"un":"Once you grow up, you stop needing to question media.","re":"Decoding is a lifelong habit; the techniques keep evolving, so you keep reading.","why":"The information world never stops changing."},"relearn":"Decoding is lifelong; the techniques evolve, so you keep questioning.","persona":"any","source":"lifelong skill"},
  {"id":"dc-074","cat":"grow-the-journey","type":"match","persona":"any","source":"core principle","hook":"Match the principle to what it means.","pairs":[{"left":"Unlearn","right":"Let go of a myth"},{"left":"Relearn","right":"Take in the truth"},{"left":"Grow","right":"Keep doing it, for life"},{"left":"Decode","right":"Read who made this and why"},{"left":"Stay kind","right":"Be gentle while you question"}],"relearn":"Unlearn, Relearn, Grow: drop the myth, take the truth, keep going."},
  {"id":"dc-075","cat":"grow-the-journey","type":"branch","hook":"You're writing your own digital-life charter to carry forward.","options":[{"text":"Commit to a few real principles: use it on purpose, check before sharing, be kind","consequence":"You leave with a charter you'll actually live by.","outcome":"charter","best":true},{"text":"Leave it blank, you'll wing it","consequence":"A few real principles you commit to beat winging it; write your charter."}],"debrief":"A personal charter turns everything learned into how you'll live online.","relearn":"Write a digital-life charter: use it on purpose, check before sharing, be kind.","persona":"any","source":"charter"},
  {"id":"dc-076","cat":"grow-the-journey","hook":"A friend is harshly piling onto someone in the comments.","relearn":"Be both critical and kind online; both matter.","persona":"any","source":"kindness","type":"role-play","setup":"Be the critical-and-kind voice. Say:","yourLine":[{"text":"\"Let's not pile on, we can disagree without tearing someone down.\"","best":true},{"text":"Join in the pile-on"}]},
  {"id":"dc-077","cat":"grow-the-journey","type":"reflect","hook":"Lensy: you now carry the power to unlearn and relearn yourself, for the rest of your life. Believe it?","prompt":"What do you think?","options":["Yes","I carry it","On my own now"],"affirm":"You can do it yourself now, unlearn, relearn, grow, for the rest of your life.","relearn":"You carry the power to unlearn and relearn yourself, for life.","persona":"any","source":"handover"},
  {"id":"dc-078","cat":"grow-the-journey","type":"sort","persona":"any","source":"digital citizenship","hook":"Sort: a wise digital citizen, or not yet?","items":[{"id":"a","text":"Reads the machine and the message"},{"id":"b","text":"Believes whatever's trending"},{"id":"c","text":"Uses tech on purpose and is kind"},{"id":"d","text":"Spreads things unchecked"},{"id":"e","text":"Verifies the source before sharing"},{"id":"f","text":"Forwards a shocking clip on instinct"}],"bins":[{"id":"wise","label":"Wise citizen","valence":"pos"},{"id":"not","label":"Not yet","valence":"neg"}],"key":{"a":"wise","b":"not","c":"wise","d":"not","e":"wise","f":"not"},"relearn":"A wise digital citizen decodes, uses tech on purpose, and is kind; not believes-and-spreads."},
  {"id":"dc-079","cat":"grow-the-journey","type":"reflect","hook":"Lensy: from naming feelings as a small kid to decoding the world as a near-adult, proud of that growth?","prompt":"What do you think?","options":["Yes","Proud","Grown up"],"affirm":"From a small friend naming feelings to a wise decoder, that's a whole growing-up.","relearn":"You've grown from naming feelings to decoding the world; that's real growth.","persona":"any","source":"journey"},
  {"id":"dc-080","cat":"grow-the-journey","type":"match","persona":"any","source":"consolidation","hook":"Match each Decoded motto to what it protects.","pairs":[{"left":"Read the machine","right":"Your clear view of the world"},{"left":"Decode anything","right":"You, from being fooled"},{"left":"Use it on purpose","right":"Your attention and time"},{"left":"Verify the source","right":"You, from convincing fakes"},{"left":"Keep growing","right":"Your skill, for life"}],"relearn":"Read the machine, decode anything, use it on purpose, and keep growing."},
  {"id":"dc-081","cat":"grow-the-journey","type":"branch","hook":"You step into adulthood and the information world is yours to navigate.","options":[{"text":"Carry the Decoder and your charter, and keep learning","consequence":"You meet the world clear-eyed and growing.","outcome":"ready","best":true},{"text":"Leave the skills behind at school","consequence":"Carry the Decoder and charter forward; keep learning, for life."}],"debrief":"What you carry forward, the Decoder, the charter, the habit, is the whole point.","relearn":"Carry the Decoder and your charter into adult life, and keep learning.","persona":"Arjun","source":"forward"},
  {"id":"dc-082","cat":"grow-the-journey","type":"reflect","hook":"Lensy: whatever the information world throws at you, you can read it. Feel ready?","prompt":"What do you think?","options":["Ready","I can read it","Bring it on"],"affirm":"You can read the machine, the message and yourself, you're genuinely ready.","relearn":"You're ready to read whatever the information world throws at you.","persona":"any","source":"readiness"},
  {"id":"dc-083","cat":"grow-the-journey","type":"reflect","hook":"Lensy: a generation that can decode the world clearly and stay kind, worth being part of?","prompt":"What do you think?","options":["Yes","Count me in","Let's go"],"affirm":"A clear-eyed, kind, critical generation, that's exactly what this whole journey was for.","relearn":"Decoding clearly and staying kind is what this whole journey was for.","persona":"any","source":"vision"},
  {"id":"dc-084","cat":"grow-the-journey","type":"reflect","hook":"Lensy: one last time, together. Unlearn. Relearn. And...?","prompt":"Finish it.","options":["Grow","Grow, for life","Keep growing"],"affirm":"Unlearn. Relearn. Grow. Now it's yours, for the rest of your life.","relearn":"Unlearn. Relearn. Grow, for the rest of your life.","persona":"any","source":"finale"},
  {"id":"dc-900","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If a partner is into it, real intimacy should look like what's on screen.\"","myth":{"un":"Real intimacy should look like what's on screen.","re":"On-screen scenes are scripted and filmed for views; real intimacy is whatever two people actually want and agree to.","why":"A script written for a camera was never meant to fit your life."},"relearn":"Real intimacy is what two people want and agree to, not a filmed script.","persona":"Vijay","source":"performance vs reality"},
  {"id":"dc-901","cat":"decode-pornography","type":"strike-rewrite","hook":"\"The reactions you see on screen show how people really feel.\"","myth":{"un":"The reactions on screen show how people really feel.","re":"Reactions are performed and edited for effect; you can't read real feelings off a paid performance.","why":"Acting a feeling and having one are not the same thing."},"relearn":"On-screen reactions are performed, not a window into real feelings.","persona":"Sneha","source":"performed reactions"},
  {"id":"dc-902","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If it didn't matter, sites wouldn't make so much money from it.\"","myth":{"un":"It must be true to life or it wouldn't make so much money.","re":"It's a business selling attention; profit measures views, not how accurate or healthy it is.","why":"Money follows what keeps people watching, not what's real."},"relearn":"It's a business selling views; profit isn't proof it's realistic or healthy.","persona":"any","source":"it's an industry"},
  {"id":"dc-903","cat":"decode-pornography","type":"strike-rewrite","hook":"\"What's most viewed must be the most normal thing to want.\"","myth":{"un":"The most-viewed stuff is the most normal thing to want.","re":"Sites push whatever holds attention, often extreme or staged; popularity isn't a guide to what's normal.","why":"An algorithm chasing clicks is not a map of normal."},"relearn":"Most-viewed means most clickable, not most normal to want.","persona":"any","source":"algorithm vs normal"},
  {"id":"dc-904","cat":"decode-pornography","type":"strike-rewrite","hook":"\"A partner should be able to do everything you've seen on screen.\"","myth":{"un":"A partner should be able to do everything you've seen on screen.","re":"On-screen acts are staged with editing, retakes and rest; expecting them of a real person is an unfair, unrealistic standard.","why":"You're comparing a real person to a heavily edited performance."},"relearn":"Staged, edited acts aren't a checklist to expect of a real partner.","persona":"Vijay","source":"unrealistic expectations"},
  {"id":"dc-905","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If you don't look like the people on screen, something's off with you.\"","myth":{"un":"If you don't look like people on screen, something's wrong with you.","re":"Those bodies are cast, filtered and edited; real bodies vary hugely and yours is normal.","why":"An edited image was never a measure of a real body."},"relearn":"Screen bodies are edited and cast; real bodies vary, and yours is normal.","persona":"Sneha","source":"body image (links g21)"},
  {"id":"dc-906","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Time always works on screen, so something must be wrong with real life.\"","myth":{"un":"Real life is wrong because nothing matches the timing on screen.","re":"Scenes are edited from many takes to look seamless; real intimacy has pauses, talking and awkward bits, and that's fine.","why":"Editing hides the takes, breaks and resets you never see."},"relearn":"Edited scenes hide the real pauses and talking; real life isn't a flaw.","persona":"any","source":"editing hides reality"},
  {"id":"dc-907","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Saying nothing on screen means real partners shouldn't need to talk.\"","myth":{"un":"Real partners shouldn't need to talk, since on screen nobody does.","re":"Scenes skip the conversation entirely; in real life, talking about what you both want is what makes it good and safe.","why":"A scene cut for pace isn't a model for real communication."},"relearn":"Real intimacy needs talking; scenes just edit the conversation out.","persona":"Vijay","source":"communication / consent"},
  {"id":"dc-908","cat":"decode-pornography","type":"strike-rewrite","hook":"\"What you watch can't shape what you expect of real people.\"","myth":{"un":"What you watch can't shape what you expect of real people.","re":"Watching a lot can quietly reset what you assume is normal; noticing that is how you keep your own expectations fair.","why":"What you see often starts to feel like the default."},"relearn":"Heavy viewing can quietly skew your expectations; noticing it keeps them fair.","persona":"any","source":"expectation drift"},
  {"id":"dc-909","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Pressure is fine on screen, so a little pressure with a partner is normal.\"","myth":{"un":"A little pressure with a partner is normal, like on screen.","re":"On screen it's acting; in real life, pressure isn't consent, and a yes only counts when it's freely given.","why":"Performed pressure normalises something real intimacy must never have."},"relearn":"Pressure isn't consent; a real yes is freely given, not pushed.","persona":"any","source":"consent (links g31)"},
  {"id":"dc-910","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Closing it or feeling uncomfortable means you're a prude.\"","myth":{"un":"Closing it or feeling uncomfortable makes you a prude.","re":"Your comfort is yours to set; closing what feels off is good judgement, not a flaw, and there's no shame either way.","why":"You're always allowed to look away, at any moment."},"relearn":"You can always close what feels uncomfortable; that's judgement, not prudishness.","persona":"Counsellor","source":"agency / no shame"},
  {"id":"dc-911","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If a friend watches it, they must have a problem.\"","myth":{"un":"A friend who watches it must have a problem.","re":"Curiosity is common and watching isn't proof of a problem; what matters is thinking critically, with no shame for anyone.","why":"Shaming a friend helps no one; understanding does."},"relearn":"Curiosity is common; it's not proof of a problem, and shame helps no one.","persona":"Counsellor","source":"no shame for others"},
  {"id":"dc-912","cat":"decode-pornography","type":"strike-rewrite","hook":"\"What's filmed shows what everyone secretly wants.\"","myth":{"un":"What's filmed shows what everyone secretly wants.","re":"It's filmed to sell to a market, not to reveal real desire; what people actually want is personal and varied.","why":"A product made for sales isn't a survey of real desire."},"relearn":"Filmed content sells to a market; it doesn't reveal what people really want.","persona":"any","source":"market not desire"},
  {"id":"dc-913","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Real partners should never want to stop or change their mind.\"","myth":{"un":"Real partners should never want to stop or change their mind.","re":"In real life anyone can pause or stop at any point; respecting that is the whole basis of consent.","why":"On screen no one stops because it's edited, not real."},"relearn":"Anyone can pause or stop anytime in real life; respecting that is consent.","persona":"Vijay","source":"consent / agency"},
  {"id":"dc-914","cat":"decode-pornography","type":"strike-rewrite","hook":"\"It's not really staged, the people just look real.\"","myth":{"un":"It's not really staged, the people just look natural.","re":"Looking natural is the craft; there's a crew, a script and many takes behind the 'realness' you see.","why":"Effortless on screen usually means heavily produced off it."},"relearn":"'Looking real' is produced; there's a crew, script and many takes behind it.","persona":"any","source":"staged performance"},
  {"id":"dc-915","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If you've seen a lot, you basically know how relationships work.\"","myth":{"un":"Seeing a lot of it means you know how relationships work.","re":"It skips the real parts, talking, trust, care, so it teaches almost nothing about real relationships.","why":"You can't learn the parts a performance leaves out."},"relearn":"It skips talk, trust and care, so it teaches little about real relationships.","persona":"any","source":"not a relationship model"},
  {"id":"dc-916","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Ads promising 'real amateur' clips mean those are unedited and true.\"","myth":{"un":"'Real amateur' labels mean a clip is unedited and true.","re":"'Real' and 'amateur' are marketing tags to seem authentic; the content is still produced and filmed for views.","why":"A label that sells authenticity isn't proof of it."},"relearn":"'Real'/'amateur' are selling labels, not proof a clip is unedited or true.","persona":"any","source":"marketing labels"},
  {"id":"dc-917","cat":"decode-pornography","type":"strike-rewrite","hook":"\"A pop-up swears everyone your age is doing exactly this.\"","myth":{"un":"A pop-up says everyone your age is doing exactly this.","re":"That's an ad engineered to hook you with fake belonging; 'everyone's doing it' is a sales line, not a fact.","why":"Manufactured 'everyone' is a classic manipulation, not data."},"relearn":"'Everyone your age does this' is ad bait, not a fact about real people.","persona":"any","source":"dark pattern / manipulation"},
  {"id":"dc-918","cat":"decode-pornography","type":"strike-rewrite","hook":"\"If you don't react like the people on screen, you're broken.\"","myth":{"un":"If you don't react like people on screen, you're broken.","re":"Those reactions are performed for a camera; real responses vary and there's nothing to fix about yours.","why":"You're measuring yourself against acting, not real life."},"relearn":"Performed reactions aren't a standard; your real responses are fine as they are.","persona":"Counsellor","source":"no shame / self-worth"},
  {"id":"dc-919","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Feeling drawn to look again means you're addicted and shameful.\"","myth":{"un":"Feeling drawn to look again means you're addicted and shameful.","re":"Feeds and sites are designed to pull you back; noticing the pull is decoding the design, not a reason for shame.","why":"The pull is by design, not a weakness in you."},"relearn":"The pull to look again is by design, not a weakness; notice it, no shame.","persona":"Counsellor","source":"by design, not a weakness"},
  {"id":"dc-920","cat":"decode-pornography","type":"strike-rewrite","hook":"\"There's no harm in treating it as a guide, since it's so common.\"","myth":{"un":"There's no harm treating it as a guide, since it's so common.","re":"Treating a performance as a guide can quietly distort what you expect of yourself and a partner; common isn't a reality check.","why":"How common it is says nothing about how accurate it is."},"relearn":"Common isn't accurate; using a performance as a guide distorts real expectations.","persona":"any","source":"common != accurate"},
  {"id":"dc-921","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Whatever you stumble on is just how things are out there.\"","myth":{"un":"Whatever you stumble on is just how things are out there.","re":"What you stumble on is selected and pushed by an algorithm chasing views, not a sample of real life.","why":"A feed engineered for clicks is not a picture of reality."},"relearn":"What's pushed at you is algorithm-selected for views, not a picture of real life.","persona":"Arjun","source":"algorithm framing"},
  {"id":"dc-922","cat":"decode-pornography","type":"strike-rewrite","hook":"\"Knowing it's fake takes all the curiosity away.\"","myth":{"un":"Knowing it's fake takes all the curiosity away.","re":"Curiosity is normal and stays fine; knowing it's a performance just frees you from holding yourself to an impossible standard.","why":"Decoding it removes the pressure, not the human curiosity."},"relearn":"Knowing it's a performance frees you from an impossible standard, no shame.","persona":"any","source":"reassurance / relief"},
  {"id":"dc-923","cat":"decode-pornography","type":"sort","hook":"Sort: what pornography actually is, vs what it isn't.","items":[{"id":"a","text":"Actors performing to a script"},{"id":"b","text":"A how-to for real sex"},{"id":"c","text":"Edited from many retakes"},{"id":"d","text":"A picture of real consent and care"},{"id":"e","text":"Filmed and cut for views"},{"id":"f","text":"A fair measure of your body"}],"bins":[{"id":"is","label":"What it is","valence":"tell"},{"id":"isnt","label":"What it isn't","valence":"neg"}],"key":{"a":"is","b":"isnt","c":"is","d":"isnt","e":"is","f":"isnt"},"relearn":"It's scripted, edited, view-driven performance, not a how-to, a model of consent, or a body standard.","persona":"any","source":"performance vs reality"},
  {"id":"dc-924","cat":"decode-pornography","type":"sort","hook":"Sort: a realistic idea of intimacy, or a screen-shaped distortion?","items":[{"id":"a","text":"Both people check what the other wants"},{"id":"b","text":"It's always seamless and silent"},{"id":"c","text":"Either person can pause anytime"},{"id":"d","text":"Bodies must match an edited 'ideal'"},{"id":"e","text":"There's talking and the odd awkward bit"},{"id":"f","text":"One partner just performs for the other"}],"bins":[{"id":"real","label":"Realistic","valence":"pos"},{"id":"distortion","label":"Distortion","valence":"neg"}],"key":{"a":"real","b":"distortion","c":"real","d":"distortion","e":"real","f":"distortion"},"relearn":"Real intimacy is mutual, talking, pause-anytime; seamless, silent, 'ideal', one-sided is the distortion.","persona":"any","source":"intimacy vs distortion"},
  {"id":"dc-925","cat":"decode-pornography","type":"sort","hook":"Sort: a healthy, critical response, or an unhealthy one?","items":[{"id":"a","text":"Reminding yourself it's a performance"},{"id":"b","text":"Comparing your body to the screen"},{"id":"c","text":"No shame, just thinking critically"},{"id":"d","text":"Using it as your relationship guide"},{"id":"e","text":"Closing what feels uncomfortable"},{"id":"f","text":"Expecting a partner to copy it"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"unhealthy","label":"Unhealthy","valence":"neg"}],"key":{"a":"healthy","b":"unhealthy","c":"healthy","d":"unhealthy","e":"healthy","f":"unhealthy"},"relearn":"Naming it a performance, no shame, closing what's off is healthy; comparing, copying, using it as a guide isn't.","persona":"any","source":"healthy response"},
  {"id":"dc-926","cat":"decode-pornography","type":"sort","hook":"Sort: where to actually learn about sex and relationships, or not?","items":[{"id":"a","text":"A doctor or trusted health service"},{"id":"b","text":"A streaming porn site"},{"id":"c","text":"A trusted adult or teacher"},{"id":"d","text":"Whatever's trending on a feed"},{"id":"e","text":"Accurate, age-right resources"},{"id":"f","text":"Pop-up ads promising 'the truth'"}],"bins":[{"id":"trusted","label":"Trusted source","valence":"pos"},{"id":"not","label":"Not a source","valence":"neg"}],"key":{"a":"trusted","b":"not","c":"trusted","d":"not","e":"trusted","f":"not"},"relearn":"Learn from a doctor, a trusted adult, accurate resources; not porn sites, feeds or ads.","persona":"any","source":"finding accurate info"},
  {"id":"dc-927","cat":"decode-pornography","type":"sort","hook":"Sort: real production reality behind a scene, or the on-screen illusion?","items":[{"id":"a","text":"A crew, lights and a camera"},{"id":"b","text":"It all just happened naturally"},{"id":"c","text":"Many retakes edited together"},{"id":"d","text":"Everyone felt exactly as they looked"},{"id":"e","text":"A script and a director"},{"id":"f","text":"Nothing was staged at all"}],"bins":[{"id":"reality","label":"Production reality","valence":"tell"},{"id":"illusion","label":"The illusion","valence":"neg"}],"key":{"a":"reality","b":"illusion","c":"reality","d":"illusion","e":"reality","f":"illusion"},"relearn":"Behind the scene: crew, script, retakes, editing; the 'it just happened naturally' is the illusion.","persona":"any","source":"production reality"},
  {"id":"dc-928","cat":"decode-pornography","type":"sort","hook":"Sort: a manipulation tell on a site, or a neutral thing?","items":[{"id":"a","text":"'Everyone your age does this' pop-up"},{"id":"b","text":"A clear close button"},{"id":"c","text":"A fake countdown to 'unlock' more"},{"id":"d","text":"Your own decision to leave"},{"id":"e","text":"Auto-playing the next clip for you"},{"id":"f","text":"A plain age-check you chose to answer"}],"bins":[{"id":"tell","label":"Manipulation tell","valence":"uhoh"},{"id":"neutral","label":"Neutral","valence":"neutral"}],"key":{"a":"tell","b":"neutral","c":"tell","d":"neutral","e":"tell","f":"neutral"},"relearn":"Fake 'everyone does this', countdowns and auto-play are tells; a close button or your own choice aren't.","persona":"Arjun","source":"dark patterns on sites"},
  {"id":"dc-929","cat":"decode-pornography","type":"sort","hook":"Sort: a fair thing to expect of a real partner, or an unfair screen standard?","items":[{"id":"a","text":"That they talk about what they want"},{"id":"b","text":"That their body matches an edit"},{"id":"c","text":"That they can say stop anytime"},{"id":"d","text":"That they perform like an actor"},{"id":"e","text":"That you both go at your own pace"},{"id":"f","text":"That it's flawless every time"}],"bins":[{"id":"fair","label":"Fair to expect","valence":"pos"},{"id":"unfair","label":"Unfair standard","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Fair: talking, stop-anytime, your own pace. Unfair: matching an edit, performing, flawless every time.","persona":"any","source":"fair expectations"},
  {"id":"dc-930","cat":"decode-pornography","type":"sort","hook":"Sort: who decides what you watch and how you feel, the site or you?","items":[{"id":"a","text":"Auto-play queuing your next hour"},{"id":"b","text":"You choosing to close the tab"},{"id":"c","text":"'Recommended for you' steering you on"},{"id":"d","text":"You setting your own comfort line"},{"id":"e","text":"Endless feed with no natural stop"},{"id":"f","text":"You deciding it's not for you today"}],"bins":[{"id":"site","label":"The site decides","valence":"uhoh"},{"id":"you","label":"You decide","valence":"pos"}],"key":{"a":"site","b":"you","c":"site","d":"you","e":"site","f":"you"},"relearn":"Auto-play, 'recommended', endless feed steer you; closing the tab and your own comfort line are your power.","persona":"Arjun","source":"agency vs design"},
  {"id":"dc-931","cat":"decode-pornography","type":"sort","hook":"Sort: something a performance leaves out, or something it shows?","items":[{"id":"a","text":"The conversation beforehand"},{"id":"b","text":"A polished, edited result"},{"id":"c","text":"Real trust between partners"},{"id":"d","text":"Camera-ready bodies and angles"},{"id":"e","text":"Checking in and care"},{"id":"f","text":"A scripted, paced scene"}],"bins":[{"id":"leaves","label":"Left out","valence":"tell"},{"id":"shows","label":"Put on screen","valence":"neutral"}],"key":{"a":"leaves","b":"shows","c":"leaves","d":"shows","e":"leaves","f":"shows"},"relearn":"Performances show the polished, scripted, camera-ready bits and leave out talk, trust and care.","persona":"any","source":"what's left out"},
  {"id":"dc-932","cat":"decode-pornography","type":"sort","hook":"Sort: a no-shame, true thing to tell yourself, or a shaming myth?","items":[{"id":"a","text":"'Curiosity is normal'"},{"id":"b","text":"'Watching means I'm broken'"},{"id":"c","text":"'I can close this anytime'"},{"id":"d","text":"'I should look like that'"},{"id":"e","text":"'It's a performance, not me'"},{"id":"f","text":"'Something's wrong with me'"}],"bins":[{"id":"true","label":"True, no shame","valence":"pos"},{"id":"myth","label":"Shaming myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Curiosity is normal, you can close it, it's a performance, true. 'Broken/wrong/should look like that' is shaming myth.","persona":"Counsellor","source":"no shame"},
  {"id":"dc-933","cat":"decode-pornography","type":"sort","hook":"Sort: a reason something gets pushed to you, or a reason it's true?","items":[{"id":"a","text":"It keeps people scrolling"},{"id":"b","text":"It reflects real relationships"},{"id":"c","text":"It drives clicks and ad money"},{"id":"d","text":"It's an accurate guide"},{"id":"e","text":"It hooks attention fast"},{"id":"f","text":"It teaches real consent"}],"bins":[{"id":"pushed","label":"Why it's pushed","valence":"tell"},{"id":"true","label":"Would make it true","valence":"neg"}],"key":{"a":"pushed","b":"true","c":"pushed","d":"true","e":"pushed","f":"true"},"relearn":"It's pushed because it holds attention and drives money, never because it's accurate or teaches consent.","persona":"any","source":"engagement vs truth"},
  {"id":"dc-934","cat":"decode-pornography","type":"role-play","hook":"A friend says they feel bad because their body doesn't match what they watch.","setup":"Reassure them, no shame. Say:","yourLine":[{"text":"\"Those bodies are cast and edited, they're not a measure of you, your body's normal.\"","best":true},{"text":"\"Yeah, maybe you should try to look more like that.\""}],"relearn":"Remind a friend screen bodies are cast and edited, not a measure of them, no shame.","persona":"Sneha","source":"body image support"},
  {"id":"dc-935","cat":"decode-pornography","type":"role-play","hook":"A friend wants to copy something they saw, without asking their partner first.","setup":"Decode it for them, kindly. Say:","yourLine":[{"text":"\"That's a script, not a plan, talk with them first, what you both want matters most.\"","best":true},{"text":"\"Sure, just go for it, that's how it's done.\""}],"relearn":"A scene is a script, not a plan; in real life you talk and check what you both want.","persona":"Vijay","source":"consent / communication"},
  {"id":"dc-936","cat":"decode-pornography","type":"role-play","hook":"A younger cousin asks if porn is how they should learn about sex.","setup":"Point them somewhere accurate, no shame. Say:","yourLine":[{"text":"\"It's a performance, not a lesson, ask a doctor or a trusted adult for the real picture.\"","best":true},{"text":"\"Yeah, just watch and you'll figure it out.\""}],"relearn":"Porn is a performance, not sex-ed; point people to a doctor or trusted adult instead.","persona":"Vijay","source":"finding accurate info"},
  {"id":"dc-937","cat":"decode-pornography","type":"role-play","hook":"A friend jokes that anyone who watches it is a creep.","setup":"Drop the shame, keep it real. Say:","yourLine":[{"text":"\"Curiosity is normal, the real skill is thinking critically about it, not shaming people.\"","best":true},{"text":"\"Yeah, total creeps, all of them.\""}],"relearn":"Curiosity is normal; the skill is thinking critically, not shaming anyone.","persona":"Counsellor","source":"no shame for others"},
  {"id":"dc-938","cat":"decode-pornography","type":"role-play","hook":"A friend feels pressure to act 'experienced' like the people on screen.","setup":"Take the pressure off. Say:","yourLine":[{"text":"\"That's acting for a camera, not a test, real intimacy goes at your pace, not a script's.\"","best":true},{"text":"\"You'd better catch up, then.\""}],"relearn":"On-screen 'experience' is acting; real intimacy goes at your pace, not a script's.","persona":"Sneha","source":"pressure / pace"},
  {"id":"dc-939","cat":"decode-pornography","type":"role-play","hook":"A friend got an upsetting clip forwarded and feels ashamed they looked.","setup":"Reassure and route to help if needed. Say:","yourLine":[{"text":"\"Looking once isn't your fault, no shame, if it's bugging you, tell a trusted adult or Childline 1098.\"","best":true},{"text":"\"You shouldn't have looked, that's on you.\""}],"relearn":"Seeing something once isn't your fault; no shame, and you can reach out to a trusted adult or Childline 1098.","persona":"Counsellor","source":"distress / help"},
  {"id":"dc-940","cat":"decode-pornography","type":"role-play","hook":"A friend insists 'everyone' is into exactly what the site shows.","setup":"Decode the claim. Say:","yourLine":[{"text":"\"'Everyone does this' is a sales line, what people really want is personal and varied.\"","best":true},{"text":"\"Guess we're the weird ones, then.\""}],"relearn":"'Everyone does this' is a sales line; real desire is personal and varied.","persona":"any","source":"market not desire"},
  {"id":"dc-941","cat":"decode-pornography","type":"role-play","hook":"A friend says a partner 'should' do whatever they've seen on screen.","setup":"Name the line, kindly. Say:","yourLine":[{"text":"\"Nobody owes you a script, a real yes is freely given, never expected or pushed.\"","best":true},{"text":"\"Yeah, they kind of owe you that.\""}],"relearn":"No one owes you a script; a real yes is freely given, never expected or pushed.","persona":"Vijay","source":"consent / expectations"},
  {"id":"dc-942","cat":"decode-pornography","type":"reflect","hook":"Lensy: knowing it's a performance, not a measure of you, does that take some pressure off?","prompt":"What do you think?","options":["Yes","A lot","That helps"],"affirm":"It's a performance, not a standard, and you were never meant to match it, no shame.","relearn":"It's a performance, not a measure of you; that frees you from an impossible standard.","persona":"any","source":"relief / no shame"},
  {"id":"dc-943","cat":"decode-pornography","type":"reflect","hook":"Lensy: it's okay to feel curious, and okay to close anything that feels off. Sound fair?","prompt":"What do you think?","options":["Yes","Fair","Good to know"],"affirm":"Curiosity is human and looking away is always allowed, you're in charge either way.","relearn":"Curiosity is normal and you can always close what feels off; you're in charge.","persona":"any","source":"agency / no shame"},
  {"id":"dc-944","cat":"decode-pornography","type":"reflect","hook":"Lensy: which porn-literacy truth do you most want to carry?","prompt":"Pick one.","options":["It's a performance","It's not sex-ed","Real bodies vary","No shame in curiosity"],"affirm":"Carry that truth and a performance loses its grip on what you expect of real life.","relearn":"It's a performance, not sex-ed, real bodies vary, and curiosity is no shame.","persona":"any","source":"consolidation"},
  {"id":"dc-945","cat":"decode-pornography","type":"reflect","hook":"Lensy: real intimacy is about consent and talking, not matching a screen. Agree?","prompt":"What do you think?","options":["Yes","Makes sense","Agreed"],"affirm":"Real intimacy is mutual, talked-through and consensual, the opposite of a one-way performance.","relearn":"Real intimacy is consent and communication, not matching a screen.","persona":"any","source":"real intimacy"},
  {"id":"dc-946","cat":"decode-pornography","type":"reflect","hook":"Lensy: noticing a site is built to pull you back, that's decoding the design, not a flaw in you. Okay?","prompt":"What do you think?","options":["Okay","That helps","Good to know"],"affirm":"The pull is by design, not a weakness; seeing it is exactly how you take the choice back.","relearn":"The pull is by design, not a weakness; noticing it gives the choice back to you.","persona":"any","source":"by design, not a weakness"},
  {"id":"dc-947","cat":"decode-pornography","type":"reflect","hook":"Lensy: where would you actually go for honest answers about sex and relationships?","prompt":"Pick one.","options":["A doctor","A trusted adult","Accurate resources","A teacher I trust"],"affirm":"Any of those gives you the real, healthy picture, far better than a performance ever could.","relearn":"For honest answers, go to a doctor, a trusted adult, a teacher, or accurate resources.","persona":"any","source":"trusted sources"},
  {"id":"dc-948","cat":"decode-pornography","type":"reflect","hook":"Lensy: you can be curious and still think critically at the same time. True for you?","prompt":"What do you think?","options":["True","Yes","I can"],"affirm":"Curiosity and a critical eye go together, that's exactly what decoding this is about.","relearn":"You can be curious and think critically at once; that's decoding it.","persona":"any","source":"curious + critical"},
  {"id":"dc-949","cat":"decode-pornography","type":"branch","hook":"A clip leaves you comparing your body and feeling low about yourself.","options":[{"text":"Remind yourself it's edited and cast, then step away","consequence":"You drop an unfair comparison and feel steadier.","outcome":"steady","best":true},{"text":"Keep watching and keep comparing","consequence":"Those bodies are edited and cast; step away from an unfair comparison instead."}],"debrief":"Edited images aren't a measure of you; stepping back protects how you see yourself.","relearn":"Screen bodies are edited and cast; step away rather than measure yourself against them.","persona":"Sneha","source":"body image"},
  {"id":"dc-950","cat":"decode-pornography","type":"branch","hook":"You catch yourself expecting a real partner to act like a scene you watched.","options":[{"text":"Notice it's a script, and choose talking and consent instead","consequence":"You build something real, not a re-enactment.","outcome":"real","best":true},{"text":"Expect them to match the scene","consequence":"It's a script, not a plan; choose talking and consent over a re-enactment."}],"debrief":"A scene is a performance; real intimacy is talked-through and mutual.","relearn":"A scene is a script, not a plan; choose talking and consent over re-enacting it.","persona":"Vijay","source":"expectations / consent"},
  {"id":"dc-951","cat":"decode-pornography","type":"branch","hook":"A site keeps auto-playing clips and you've lost track of time.","options":[{"text":"Recognise the design and close it on your own terms","consequence":"You take your attention and choice back.","outcome":"reclaim","best":true},{"text":"Blame yourself for 'no self-control'","consequence":"Auto-play is engineered to hold you; recognise the design and close it, no self-blame."}],"debrief":"Auto-play is attention-capture design; closing it is reading the machine, not willpower.","relearn":"Auto-play is by design; recognise it and close on your own terms, no self-blame.","persona":"Arjun","source":"design vs willpower"},
  {"id":"dc-952","cat":"decode-pornography","type":"branch","hook":"You really want to understand sex and relationships properly.","options":[{"text":"Go to a doctor, trusted adult or accurate resources","consequence":"You get the real, healthy picture.","outcome":"informed","best":true},{"text":"Treat a porn site as your teacher","consequence":"It's a performance, not sex-ed; learn from a doctor, trusted adult or accurate resources."}],"debrief":"For the real picture, trusted sources beat a performance every time.","relearn":"Learn about sex and relationships from trusted sources, not a porn site.","persona":"any","source":"finding accurate info"},
  {"id":"dc-953","cat":"decode-pornography","type":"branch","hook":"A friend keeps forwarding explicit clips into the group chat.","options":[{"text":"Say it's not okay and ask them to stop sending it","consequence":"You set a clear line and protect the group.","outcome":"boundary","best":true},{"text":"Just go along with it to avoid awkwardness","consequence":"It's okay to say stop; setting that line protects you and the group."}],"debrief":"You can decline content you didn't ask for; a clear boundary is fair and kind.","relearn":"You can ask someone to stop forwarding explicit clips; setting that line is fair.","persona":"any","source":"boundaries / consent"},
  {"id":"dc-954","cat":"decode-pornography","type":"branch","hook":"A pop-up swears 'everyone your age is doing this' to keep you watching.","options":[{"text":"Read it as ad bait and close it","consequence":"You see the manipulation and step away.","outcome":"decoded","best":true},{"text":"Believe it and keep going","consequence":"'Everyone does this' is engineered ad bait, not a fact; read the trick and close it."}],"debrief":"Manufactured 'everyone' is a manipulation tell, not data about real people.","relearn":"'Everyone your age does this' is ad bait; read the manipulation and close it.","persona":"Arjun","source":"dark pattern"},
  {"id":"dc-955","cat":"decode-pornography","type":"branch","hook":"Something you stumbled on is genuinely distressing you afterwards.","options":[{"text":"Tell a trusted adult or call Childline 1098","consequence":"You get real support and it's not on you alone.","outcome":"support","best":true},{"text":"Bottle it up and feel ashamed","consequence":"It's not your fault; tell a trusted adult or call Childline 1098 for support."}],"debrief":"Distress from something online isn't your fault; reaching for help is the strong move.","relearn":"If something online distresses you, tell a trusted adult or call Childline 1098, no shame.","persona":"Counsellor","source":"distress / help"},
  {"id":"dc-956","cat":"decode-pornography","type":"match","hook":"Match the porn-literacy truth to the relief it brings.","pairs":[{"left":"It's a scripted performance","right":"Not a standard to live up to"},{"left":"It's not sex education","right":"Learn from trusted sources"},{"left":"Bodies are cast and edited","right":"Real bodies vary, yours is normal"},{"left":"Curiosity is normal","right":"No shame in being curious"},{"left":"You can always close it","right":"You're in charge at every step"}],"relearn":"Each porn-literacy truth lifts a pressure: not a standard, not sex-ed, no shame, you're in charge.","persona":"any","source":"relief / no shame"},
  {"id":"dc-957","cat":"decode-pornography","type":"match","hook":"Match each on-screen illusion to the production reality behind it.","pairs":[{"left":"Looks effortless and natural","right":"Scripted, with many retakes"},{"left":"Seamless from start to end","right":"Edited together from clips"},{"left":"Flawless, camera-ready bodies","right":"Cast, lit and filtered"},{"left":"Nobody pauses or talks","right":"The conversation is cut out"},{"left":"Looks spontaneous","right":"A crew and director set it up"}],"relearn":"Every 'natural' look on screen is scripted, edited, cast and crewed behind the scenes.","persona":"any","source":"production reality"},
  {"id":"dc-958","cat":"decode-pornography","type":"match","hook":"Match the screen distortion to what real intimacy looks like instead.","pairs":[{"left":"Silent and instant","right":"Talking about what you both want"},{"left":"One person performs","right":"Mutual, both people matter"},{"left":"Never stops or changes","right":"Either can pause anytime"},{"left":"Matches an edited 'ideal'","right":"Real bodies, no standard to hit"},{"left":"Pressure looks normal","right":"A freely given yes, no pressure"}],"relearn":"Real intimacy is mutual, talked-through, pause-anytime and freely consenting, not the screen's distortion.","persona":"any","source":"intimacy vs distortion"},
  {"id":"dc-959","cat":"decode-pornography","type":"match","hook":"Match the site's manipulation to the calm, decoded response.","pairs":[{"left":"Auto-play to the next clip","right":"Close it on your own terms"},{"left":"'Everyone your age does this'","right":"Read it as ad bait"},{"left":"Fake countdown to 'unlock'","right":"Ignore the manufactured rush"},{"left":"'Recommended for you'","right":"Decide for yourself instead"},{"left":"Endless feed, no stop","right":"Set your own stopping point"}],"relearn":"Each site trick has a calm decoded answer: close it, name the bait, ignore the rush, decide for yourself.","persona":"Arjun","source":"dark patterns"},
  {"id":"dc-960","cat":"decode-pornography","type":"match","hook":"Match the no-shame reassurance to why it's true.","pairs":[{"left":"Curiosity is normal","right":"Many teens encounter this"},{"left":"The pull is by design","right":"Sites are built to draw you back"},{"left":"You can look away anytime","right":"Agency at every step"},{"left":"It's not a measure of you","right":"It's a performance, not real life"},{"left":"Distress isn't your fault","right":"Support is there if you need it"}],"relearn":"Curiosity is normal, the pull is by design, you have agency, and distress isn't your fault.","persona":"Counsellor","source":"no shame"},
  {"id":"dc-961","cat":"decode-pornography","type":"match","hook":"Match each 'where to learn' question to the right place to ask.","pairs":[{"left":"Is my body normal?","right":"A doctor or health service"},{"left":"What does consent mean?","right":"A trusted adult or teacher"},{"left":"How do real relationships work?","right":"Accurate, age-right resources"},{"left":"This is distressing me","right":"A trusted adult or Childline 1098"},{"left":"Where NOT to learn it","right":"A porn site or trending feed"}],"relearn":"For real answers go to a doctor, a trusted adult, accurate resources, or Childline 1098, not a porn site.","persona":"any","source":"finding accurate info"},
  {"id":"dc-962","cat":"decode-pornography","type":"match","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"It shows real sex","right":"It's a filmed performance"},{"left":"It's good sex-ed","right":"It skips consent and care"},{"left":"That's how bodies look","right":"Real bodies vary hugely"},{"left":"Everyone wants exactly this","right":"Real desire is personal"},{"left":"Watching means I'm broken","right":"Curiosity is normal, no shame"}],"relearn":"Each myth has a truth: it's performance, not sex-ed; bodies vary; desire is personal; curiosity is no shame.","persona":"any","source":"myth vs truth"},
  {"id":"dc-963","cat":"decode-pornography","type":"spot","hook":"Spot the two myths about pornography (the red flags to catch).","scene":[{"id":"a","text":"It's a scripted, filmed performance","trick":false},{"id":"b","text":"It shows exactly how real sex works","trick":true},{"id":"c","text":"Real bodies vary and that's normal","trick":false},{"id":"d","text":"Your body should look like the screen","trick":true},{"id":"e","text":"Curiosity about it is normal","trick":false}],"why":"'Shows how real sex works' and 'your body should look like the screen' are the myths; the rest are true.","relearn":"It's a performance, real bodies vary, curiosity is normal; 'real sex' and 'should look like that' are myths.","persona":"any","source":"performance vs reality"},
  {"id":"dc-964","cat":"decode-pornography","type":"spot","hook":"Spot the two lines that treat a performance as real life.","scene":[{"id":"a","text":"\"That's edited, real life isn't seamless\"","trick":false},{"id":"b","text":"\"A partner should do everything I saw\"","trick":true},{"id":"c","text":"\"Real intimacy needs talking and consent\"","trick":false},{"id":"d","text":"\"That's exactly how everyone really is\"","trick":true},{"id":"e","text":"\"I can close what feels uncomfortable\"","trick":false}],"why":"Expecting a partner to copy it and 'that's how everyone really is' treat a performance as reality.","relearn":"A scene is edited performance; expecting a partner to copy it or calling it 'how everyone is' is the trap.","persona":"any","source":"performance vs reality"},
  {"id":"dc-965","cat":"decode-pornography","type":"spot","hook":"Spot the two manipulation tricks a porn site uses on you.","scene":[{"id":"a","text":"A clear button to close the page","trick":false},{"id":"b","text":"A fake countdown to 'unlock' more","trick":true},{"id":"c","text":"An age-check you chose to answer","trick":false},{"id":"d","text":"Auto-playing the next clip for you","trick":true},{"id":"e","text":"Your own choice to leave the site","trick":false}],"why":"The fake countdown and auto-play are engineered to keep you watching; the rest leave the choice with you.","relearn":"Fake countdowns and auto-play are tricks to keep you watching; a close button and your choice aren't.","persona":"Arjun","source":"dark patterns"},
  {"id":"dc-966","cat":"decode-pornography","type":"spot","hook":"Spot the two shaming lines (the red flags to catch).","scene":[{"id":"a","text":"\"Curiosity about this is normal\"","trick":false},{"id":"b","text":"\"If you watched it, you're broken\"","trick":true},{"id":"c","text":"\"You can close it anytime, no shame\"","trick":false},{"id":"d","text":"\"Only creeps are ever curious\"","trick":true},{"id":"e","text":"\"It's a performance, not about you\"","trick":false}],"why":"'You're broken' and 'only creeps are curious' are shaming myths; the rest are true and kind.","relearn":"Curiosity is normal and shame-free; 'you're broken' and 'only creeps are curious' are shaming myths.","persona":"Counsellor","source":"no shame"},
  {"id":"dc-967","cat":"decode-pornography","type":"spot","hook":"Spot the two lines that confuse pressure with consent.","scene":[{"id":"a","text":"\"A yes only counts if it's freely given\"","trick":false},{"id":"b","text":"\"A bit of pressure is normal, it's on screen\"","trick":true},{"id":"c","text":"\"Either person can stop anytime\"","trick":false},{"id":"d","text":"\"They kind of owe me, like in the clip\"","trick":true},{"id":"e","text":"\"We talk about what we both want\"","trick":false}],"why":"'A bit of pressure is normal' and 'they owe me' confuse pressure with consent; the rest are real consent.","relearn":"Pressure isn't consent; 'a bit of pressure is normal' and 'they owe me' are the lines to catch.","persona":"any","source":"consent"},
  {"id":"dc-968","cat":"decode-pornography","type":"spot","hook":"Spot the two wrong places to learn about sex and relationships.","scene":[{"id":"a","text":"A doctor or trusted health service","trick":false},{"id":"b","text":"A streaming porn site","trick":true},{"id":"c","text":"A trusted adult or teacher","trick":false},{"id":"d","text":"Whatever's trending on a feed","trick":true},{"id":"e","text":"Accurate, age-right resources","trick":false}],"why":"A porn site and a trending feed aren't reliable; a doctor, trusted adult or accurate resources are.","relearn":"Learn from a doctor, trusted adult or accurate resources, not a porn site or a trending feed.","persona":"any","source":"finding accurate info"},
  {"id":"dc-969","cat":"decode-pornography","type":"spot","hook":"Spot the two things a performance leaves out of real intimacy.","scene":[{"id":"a","text":"Edited, camera-ready visuals","trick":false},{"id":"b","text":"The conversation about what you want","trick":true},{"id":"c","text":"A scripted, paced scene","trick":false},{"id":"d","text":"Real trust and checking in","trick":true},{"id":"e","text":"A polished final cut","trick":false}],"why":"A performance shows the polished, scripted visuals but leaves out the real conversation, trust and care.","relearn":"Performances show the polished visuals and leave out the talking, trust and care of real intimacy.","persona":"any","source":"what's left out"},
  {"id":"dc-970","cat":"decode-pornography","type":"spot","hook":"Spot the two illusions of 'realness' a scene sells you.","scene":[{"id":"a","text":"There's a script behind it","trick":false},{"id":"b","text":"\"It all just happened naturally\"","trick":true},{"id":"c","text":"Many takes are edited together","trick":false},{"id":"d","text":"\"Nothing here was staged at all\"","trick":true},{"id":"e","text":"A crew and director set it up","trick":false}],"why":"'It just happened naturally' and 'nothing was staged' are the illusions; script, takes and crew are the reality.","relearn":"'It just happened' and 'nothing was staged' are illusions; there's a script, retakes and a crew.","persona":"any","source":"production reality"},
  {"id":"dc-990","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"Veer","source":"i'm too smart","relearn":"Smart people get hooked too; the defence is reading the design, not raw cleverness.","hook":"\"I'm too smart for the feed to manipulate me.\"","myth":{"un":"I'm too smart for the feed to manipulate me.","re":"Smart people get hooked too; the defence is reading the design, not raw cleverness.","why":"Feeds tune to everyone's reflexes; being smart isn't a shield, knowing the design is."}},
  {"id":"dc-991","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"viral","relearn":"Trending tells you it spread fast, not that it's true.","hook":"\"If a reel goes viral, it must be saying something true.\"","myth":{"un":"A viral reel must be saying something true.","re":"Trending tells you it spread fast, not that it's true.","why":"Going viral measures how fast it spread, often on outrage, not whether it's accurate."}},
  {"id":"dc-992","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"Arjun","source":"reels for me","relearn":"The feed shapes your interests over time; it isn't a neutral mirror.","hook":"\"The Reels tab is just showing me my own interests.\"","myth":{"un":"The Reels tab just shows me my own interests.","re":"The feed shapes your interests over time; it isn't a neutral mirror.","why":"It shows whatever holds you longest, slowly steering your interests, not only reflecting them."}},
  {"id":"dc-993","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"filter bubble","relearn":"A like-minded group narrows your view; seek sources outside it on purpose.","hook":"\"My WhatsApp groups give me the full picture of what's happening.\"","myth":{"un":"My WhatsApp groups give me the full picture.","re":"A like-minded group narrows your view; seek sources outside it on purpose.","why":"Like-minded groups are a bubble; you can't weigh views you're simply never forwarded."}},
  {"id":"dc-994","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"one more","relearn":"The missing stop is by design; naming it is how you reclaim the choice.","hook":"\"One more video can't hurt; I'll stop whenever I want.\"","myth":{"un":"One more video can't hurt; I'll stop whenever I want.","re":"The missing stop is by design; naming it is how you reclaim the choice.","why":"Auto-play is built to make 'one more' endless; the stop is engineered away, not weak willpower."}},
  {"id":"dc-995","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"ads neutral","relearn":"You're shown ads tuned to your data; that targeting is the product being sold.","hook":"\"The ads I get are random, they don't really know me.\"","myth":{"un":"The ads I get are random; they don't know me.","re":"You're shown ads tuned to your data; that targeting is the product being sold.","why":"Ads are targeted from your activity and data; that's the business model, not chance."}},
  {"id":"dc-996","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"Arjun","source":"notifications help","relearn":"Turning off non-essential pings is choosing your attention on purpose.","hook":"\"Notifications buzz only when something important happens.\"","myth":{"un":"Notifications buzz only when something important happens.","re":"Turning off non-essential pings is choosing your attention on purpose.","why":"Most pings are engagement bait to pull you back, not signals that something matters."}},
  {"id":"dc-997","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"more time more truth","relearn":"Hours scrolled is a platform metric, not a measure of what you understand.","hook":"\"The longer I scroll, the better informed I get.\"","myth":{"un":"The longer I scroll, the better informed I get.","re":"Hours scrolled is a platform metric, not a measure of what you understand.","why":"Endless scroll optimises for time spent, not understanding; more minutes can mean less clarity."}},
  {"id":"dc-998","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"search neutral","relearn":"What 'trends' is engineered ranking; spread isn't the same as honest popularity.","hook":"\"Trending just shows whatever's genuinely most popular.\"","myth":{"un":"Trending just shows whatever is genuinely most popular.","re":"What 'trends' is engineered ranking; spread isn't the same as honest popularity.","why":"Trending is ranked and gameable; spread can be bought, botted or boosted, not pure popularity."}},
  {"id":"dc-999","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"Arjun","source":"stop is willpower","relearn":"Stopping is design-awareness; seeing the hook gives the choice back to you.","hook":"\"Putting the phone down should just be about willpower.\"","myth":{"un":"Putting the phone down is just about willpower.","re":"Stopping is design-awareness; seeing the hook gives the choice back to you.","why":"The hooks are designed by experts; recognising the design, not white-knuckling, reclaims the choice."}},
  {"id":"dc-1000","cat":"decode-the-algorithm","type":"strike-rewrite","persona":"any","source":"feed is the world","relearn":"You can only weigh what you're shown; the feed quietly decides what you never see.","hook":"\"What's on my feed is basically what's happening in the world.\"","myth":{"un":"My feed is basically what's happening in the world.","re":"You can only weigh what you're shown; the feed quietly decides what you never see.","why":"Your feed is a tiny, tuned slice picked for you; whole topics never reach you at all."}},
  {"id":"dc-1001","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"attention design","relearn":"Endless refresh and badge nudges are attention-capture design.","hook":"Spot the 2 design tricks built to keep you scrolling.","scene":[{"id":"a","text":"Pull-to-refresh that never runs out","trick":true},{"id":"b","text":"A clear 'you're all caught up' marker","trick":false},{"id":"c","text":"A little red badge nudging you back","trick":true},{"id":"d","text":"A reading list you built yourself","trick":false},{"id":"e","text":"A timer you set to leave the app","trick":false}],"why":"Bottomless refresh and red-badge nudges are attention hooks; the others keep you in charge."},
  {"id":"dc-1002","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"engineered ranking","relearn":"Outrage and rage-bait are amplified because they drive engagement, not because they're true.","hook":"Spot the 2 posts the feed pushed for engagement, not for you.","scene":[{"id":"a","text":"A rage-bait clip everyone's arguing under","trick":true},{"id":"b","text":"A note from a friend you follow","trick":false},{"id":"c","text":"An outrage headline with no source","trick":true},{"id":"d","text":"A class timetable you saved","trick":false},{"id":"e","text":"A search result you typed in","trick":false}],"why":"Rage-bait and source-free outrage win engagement; the feed amplifies them, not your wellbeing."},
  {"id":"dc-1003","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"filter bubbles","relearn":"Following only your side and muting others harden the filter bubble.","hook":"Spot the 2 habits that lock you inside a filter bubble.","scene":[{"id":"a","text":"Only following accounts you already agree with","trick":true},{"id":"b","text":"Muting every view you dislike","trick":true},{"id":"c","text":"Occasionally reading a source you'd usually skip","trick":false},{"id":"d","text":"Checking who's behind a claim","trick":false},{"id":"e","text":"Asking what the other side actually argues","trick":false}],"why":"Following only your side and muting the rest hardens the bubble; the others open it up."},
  {"id":"dc-1004","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"virality","relearn":"Trending measures spread (often outrage or bots), not accuracy.","hook":"Spot the 2 tells that 'trending' isn't the same as 'true'.","scene":[{"id":"a","text":"It spread because it made people furious","trick":true},{"id":"b","text":"It's been checked by a named newsroom","trick":false},{"id":"c","text":"A bot network boosted the hashtag","trick":true},{"id":"d","text":"Several outlets report the same facts","trick":false},{"id":"e","text":"The original source is clearly linked","trick":false}],"why":"Anger-driven spread and bot-boosting make things trend; none of that makes them accurate."},
  {"id":"dc-1005","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"attention economy","relearn":"When the app is free and tracks you, your attention is the product being sold.","hook":"Spot the 2 signs you're the product being sold.","scene":[{"id":"a","text":"The app is free but tracks everything you tap","trick":true},{"id":"b","text":"You can export and delete your data","trick":false},{"id":"c","text":"Your watch-time is packaged for advertisers","trick":true},{"id":"d","text":"There's a clear off switch for the feed","trick":false},{"id":"e","text":"You chose exactly what to look up","trick":false}],"why":"Free-but-tracked and watch-time-sold mean your attention is the product; the others give you control."},
  {"id":"dc-1006","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"recommendation systems","relearn":"Recommenders push what people like you finish and what triggers emotion, not what's most true.","hook":"Spot the 2 reasons this video reached you, by design.","scene":[{"id":"a","text":"People like you watched it to the end","trick":true},{"id":"b","text":"It triggers a strong, quick emotion","trick":true},{"id":"c","text":"A teacher judged it the most accurate","trick":false},{"id":"d","text":"It was fact-checked before publishing","trick":false},{"id":"e","text":"An editor ranked it for importance","trick":false}],"why":"Look-alike watch-time and quick emotion drive recommendations, not accuracy or importance."},
  {"id":"dc-1007","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"reading the system","relearn":"Believing on a feeling and forwarding unchecked keep you a passive target.","hook":"Spot the 2 moves of a passive target, not a decoder.","scene":[{"id":"a","text":"Believing a clip just because it felt true","trick":true},{"id":"b","text":"Forwarding before checking who made it","trick":true},{"id":"c","text":"Asking who benefits from you sharing this","trick":false},{"id":"d","text":"Pausing to seek another viewpoint","trick":false},{"id":"e","text":"Noticing the feeling the post is built to trigger","trick":false}],"why":"Believing on a feeling and forwarding unchecked make you a target; the others make you a decoder."},
  {"id":"dc-1008","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"attention design","relearn":"Streaks and fake-scarcity counters are dark patterns built to drive engagement.","hook":"Spot the 2 dark-pattern nudges in this app.","scene":[{"id":"a","text":"A streak you'll 'lose' if you skip a day","trick":true},{"id":"b","text":"A simple, dismissable settings menu","trick":false},{"id":"c","text":"A fake 'only 2 left, hurry!' counter","trick":true},{"id":"d","text":"A clear price shown up front","trick":false},{"id":"e","text":"An easy way to turn the feed off","trick":false}],"why":"Loss-fear streaks and fake-scarcity counters are dark patterns engineered to pull you back."},
  {"id":"dc-1009","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"engineered feeds","relearn":"Different feeds tuned to what you linger on means it's engineered, not neutral.","hook":"Spot the 2 things that mean the feed is ranked, not neutral.","scene":[{"id":"a","text":"Two friends see totally different feeds","trick":true},{"id":"b","text":"What you linger on shapes what's next","trick":true},{"id":"c","text":"A plain time-ordered list","trick":false},{"id":"d","text":"Results for exactly what you typed","trick":false},{"id":"e","text":"A profile you tapped directly","trick":false}],"why":"Different feeds and lingering-driven ranking are engineered; time-order and direct taps are neutral."},
  {"id":"dc-1010","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"agency","relearn":"Opening with intent and leaving when done is using the feed, not being used.","hook":"Spot the 2 ways the feed ends up using you, not you using it.","scene":[{"id":"a","text":"Opening the app with one thing you want to find","trick":false},{"id":"b","text":"Drifting in with no reason and scrolling for an hour","trick":true},{"id":"c","text":"Leaving once you've got what you came for","trick":false},{"id":"d","text":"Letting auto-play pick your whole evening","trick":true},{"id":"e","text":"Turning off the pings that pull you back","trick":false}],"why":"Drift and auto-play hand over the wheel; the others use the feed on purpose."},
  {"id":"dc-1011","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"virality","relearn":"Urgency and 'they're hiding this' framing are engineered to rush you into sharing.","hook":"Spot the 2 emotional hooks engineered to make you share fast.","scene":[{"id":"a","text":"'Share before they delete this!'","trick":true},{"id":"b","text":"A calm, sourced explainer thread","trick":false},{"id":"c","text":"'They don't want you to see this'","trick":true},{"id":"d","text":"A correction politely linking the facts","trick":false},{"id":"e","text":"A clearly-labelled opinion piece","trick":false}],"why":"Urgency and 'they're hiding it' bait rush your share reflex; pause and check the source instead."},
  {"id":"dc-1012","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"attention economy","relearn":"Platforms optimise watch-time and taps, not your wellbeing or how true the content is.","hook":"Spot the 2 metrics the platform actually optimises for.","scene":[{"id":"a","text":"Minutes you spend in the app","trick":true},{"id":"b","text":"Whether you felt calmer afterwards","trick":false},{"id":"c","text":"Taps, watches and shares you generate","trick":true},{"id":"d","text":"Whether you learned something true","trick":false},{"id":"e","text":"Whether you slept on time","trick":false}],"why":"Time-in-app and taps are the targets; your calm, truth and sleep aren't what's measured."},
  {"id":"dc-1013","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"filter bubbles","relearn":"Filter bubbles make your view feel universal and harden you against other people.","hook":"Spot the 2 results of living only inside your bubble.","scene":[{"id":"a","text":"You start to think your view is everyone's view","trick":true},{"id":"b","text":"The other side stops looking like real people","trick":true},{"id":"c","text":"You occasionally hear a take that annoys you","trick":false},{"id":"d","text":"You can explain what others actually believe","trick":false},{"id":"e","text":"You check a claim against a different source","trick":false}],"why":"Bubbles make your view feel universal and the other side unreal; stepping out keeps it honest."},
  {"id":"dc-1014","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"design vs willpower","relearn":"Auto-play and infinite scroll remove the stop by design; naming the hook reclaims your choice.","hook":"Spot the 2 hooks that aren't really about your willpower.","scene":[{"id":"a","text":"Auto-play starting the next video for you","trick":true},{"id":"b","text":"Choosing to close the app yourself","trick":false},{"id":"c","text":"Infinite scroll erasing the natural stop","trick":true},{"id":"d","text":"Setting a timer before you open it","trick":false},{"id":"e","text":"Deciding in advance what you came to do","trick":false}],"why":"Auto-play and infinite scroll engineer the stop away; recognising that, not willpower, reclaims it."},
  {"id":"dc-1015","cat":"decode-the-algorithm","type":"spot","persona":"any","source":"recommendation systems","relearn":"Your feed is personalised to your behaviour and predicted watch-time, not the same for everyone.","hook":"Spot the 2 reasons your 'For You' page differs from a friend's.","scene":[{"id":"a","text":"It's tuned to your past taps and pauses","trick":true},{"id":"b","text":"It predicts what'll keep you, specifically, watching","trick":true},{"id":"c","text":"Everyone is shown the exact same posts","trick":false},{"id":"d","text":"It lists events strictly by time","trick":false},{"id":"e","text":"It only ever shows what you searched","trick":false}],"why":"Your page is personalised to your behaviour and predicted watch-time, so no two feeds match."},
  {"id":"dc-1016","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"what the feed sells","relearn":"The platform sells your attention, data and time; the 'neutral free square' is the cover story.","hook":"Sort: what the platform actually sells, or what it claims to give.","items":[{"id":"a","text":"Your attention, packaged for advertisers"},{"id":"b","text":"A free, neutral public square"},{"id":"c","text":"Your data, profiled and targeted"},{"id":"d","text":"Just the truth, fairly ranked"},{"id":"e","text":"Your watch-time, sold by the minute"},{"id":"f","text":"A simple service with no agenda"}],"bins":[{"id":"sold","label":"What it sells","valence":"neg"},{"id":"claim","label":"What it claims","valence":"pos"}],"key":{"a":"sold","b":"claim","c":"sold","d":"claim","e":"sold","f":"claim"}},
  {"id":"dc-1017","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"engagement vs truth","relearn":"Feeds surface the engaging, often the angry or shocking; accuracy is what you have to seek out.","hook":"Sort: chosen because it's engaging, or because it's accurate.","items":[{"id":"a","text":"A furious clip everyone's fighting over"},{"id":"b","text":"A boring but verified correction"},{"id":"c","text":"A shocking 'you won't believe' headline"},{"id":"d","text":"A sourced report that ranks low"},{"id":"e","text":"A meme that's wrong but hilarious"},{"id":"f","text":"A quiet thread that cites its facts"}],"bins":[{"id":"engaging","label":"Picked for engagement","valence":"uhoh"},{"id":"accurate","label":"Actually accurate","valence":"pos"}],"key":{"a":"engaging","b":"accurate","c":"engaging","d":"accurate","e":"engaging","f":"accurate"}},
  {"id":"dc-1018","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"reading the why","relearn":"Asking who benefits and who posted it is decoding; sharing on a feeling is the feed using you.","hook":"Sort: reading why you see it, or just reacting to it.","items":[{"id":"a","text":"Asking who benefits from you sharing this"},{"id":"b","text":"Tapping share on the first wave of anger"},{"id":"c","text":"Noticing the emotion it's built to trigger"},{"id":"d","text":"Believing it because it confirms your side"},{"id":"e","text":"Checking who actually posted it"},{"id":"f","text":"Forwarding before you've read past the headline"}],"bins":[{"id":"decode","label":"Decoding it","valence":"pos"},{"id":"react","label":"Just reacting","valence":"neg"}],"key":{"a":"decode","b":"react","c":"decode","d":"react","e":"decode","f":"react"}},
  {"id":"dc-1019","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"intentional vs doomscroll","relearn":"Opening with intent and leaving when done is using it; drift and chasing pings is being used.","hook":"Sort: using the feed on purpose, or being pulled by it.","items":[{"id":"a","text":"Opening with one thing you want to find"},{"id":"b","text":"Drifting in out of boredom for an hour"},{"id":"c","text":"Leaving once you've got what you came for"},{"id":"d","text":"Following auto-play wherever it goes"},{"id":"e","text":"Setting a limit and respecting it"},{"id":"f","text":"Chasing every notification the second it buzzes"}],"bins":[{"id":"intentional","label":"On purpose","valence":"pos"},{"id":"pulled","label":"Pulled along","valence":"neg"}],"key":{"a":"intentional","b":"pulled","c":"intentional","d":"pulled","e":"intentional","f":"pulled"}},
  {"id":"dc-1020","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"bubble vs broadening","relearn":"Following only your side hardens the bubble; deliberately seeking other views is how you escape it.","hook":"Sort: hardens your filter bubble, or broadens your view.","items":[{"id":"a","text":"Following only accounts that agree with you"},{"id":"b","text":"Reading one source you'd usually skip"},{"id":"c","text":"Muting everyone who annoys you"},{"id":"d","text":"Asking what the other side actually argues"},{"id":"e","text":"Letting the feed pick all your news"},{"id":"f","text":"Seeking a viewpoint you weren't shown"}],"bins":[{"id":"bubble","label":"Hardens the bubble","valence":"neg"},{"id":"broaden","label":"Broadens your view","valence":"pos"}],"key":{"a":"bubble","b":"broaden","c":"bubble","d":"broaden","e":"bubble","f":"broaden"}},
  {"id":"dc-1021","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"attention design vs neutral","relearn":"Infinite scroll, auto-play and loss-fear streaks capture attention; ends, markers and search keep you in charge.","hook":"Sort: an attention-capture design, or a more neutral one.","items":[{"id":"a","text":"Infinite scroll with no stop"},{"id":"b","text":"A page that ends with a back button"},{"id":"c","text":"Auto-play to the next video"},{"id":"d","text":"A list you can mark 'all caught up'"},{"id":"e","text":"A streak you'll lose if you skip"},{"id":"f","text":"A search box you typed into"}],"bins":[{"id":"capture","label":"Attention-capture","valence":"uhoh"},{"id":"neutral","label":"More neutral","valence":"neutral"}],"key":{"a":"capture","b":"neutral","c":"capture","d":"neutral","e":"capture","f":"neutral"}},
  {"id":"dc-1022","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"metric vs meaning","relearn":"Platforms optimise watch-time, shares and taps; your calm, truth and sleep aren't on the dashboard.","hook":"Sort: a metric the platform optimises, or something it ignores.","items":[{"id":"a","text":"Minutes you spend in the app"},{"id":"b","text":"Whether you felt calmer after"},{"id":"c","text":"Shares and taps you generate"},{"id":"d","text":"Whether you learned what's true"},{"id":"e","text":"How long you watch each clip"},{"id":"f","text":"Whether you got to bed on time"}],"bins":[{"id":"metric","label":"What it optimises","valence":"uhoh"},{"id":"ignored","label":"What it ignores","valence":"neutral"}],"key":{"a":"metric","b":"ignored","c":"metric","d":"ignored","e":"metric","f":"ignored"}},
  {"id":"dc-1023","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"personalised vs shared","relearn":"Different feeds, shifting ranking and targeted ads mean it's tuned to you, not shared.","hook":"Sort: a sign your feed is tuned to you, or the same for all.","items":[{"id":"a","text":"Two friends see totally different 'For You' pages"},{"id":"b","text":"A printed newspaper everyone reads alike"},{"id":"c","text":"Ranking shifts as you linger on things"},{"id":"d","text":"A noticeboard with one fixed list"},{"id":"e","text":"Ads that seem to know your last search"},{"id":"f","text":"A timetable that's identical for the class"}],"bins":[{"id":"tuned","label":"Tuned to you","valence":"uhoh"},{"id":"shared","label":"Same for everyone","valence":"neutral"}],"key":{"a":"tuned","b":"shared","c":"tuned","d":"shared","e":"tuned","f":"shared"}},
  {"id":"dc-1024","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"trending tells","relearn":"Anger, coordinated pushes and shareable emotion drive spread; verification and sources are what make it true.","hook":"Sort: a reason something trends, or a reason something is true.","items":[{"id":"a","text":"It made huge numbers of people angry"},{"id":"b","text":"Several newsrooms verified the facts"},{"id":"c","text":"A coordinated push boosted the hashtag"},{"id":"d","text":"The primary source is checkable"},{"id":"e","text":"It's emotional enough to share fast"},{"id":"f","text":"Experts in the field back it up"}],"bins":[{"id":"spread","label":"Why it spreads","valence":"uhoh"},{"id":"truth","label":"Why it's true","valence":"pos"}],"key":{"a":"spread","b":"truth","c":"spread","d":"truth","e":"spread","f":"truth"}},
  {"id":"dc-1025","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"notifications","relearn":"Real replies and alerts inform; 'see who reacted' and 'don't miss out' are engagement bait.","hook":"Sort: a notification that informs you, or one that just baits you back.","items":[{"id":"a","text":"'5 people reacted, see who!'"},{"id":"b","text":"A real reply from someone you messaged"},{"id":"c","text":"'You haven't posted in a while…'"},{"id":"d","text":"A genuine security alert on your account"},{"id":"e","text":"'Trending now, don't miss out'"},{"id":"f","text":"A reminder you set yourself"}],"bins":[{"id":"inform","label":"Actually informs","valence":"pos"},{"id":"bait","label":"Just bait","valence":"neg"}],"key":{"a":"bait","b":"inform","c":"bait","d":"inform","e":"bait","f":"inform"}},
  {"id":"dc-1026","cat":"decode-the-algorithm","type":"sort","persona":"any","source":"privacy on the feed","relearn":"Minimal permissions and reviewing data guard you; blanket 'OK' and always-on location hand you over.","hook":"Sort: a choice that guards you on the feed, or one that hands you over.","items":[{"id":"a","text":"Granting only the permissions an app needs"},{"id":"b","text":"Accepting every tracker by tapping 'OK'"},{"id":"c","text":"Reviewing what data you're sharing"},{"id":"d","text":"Leaving location on for every app"},{"id":"e","text":"Turning off ad personalisation"},{"id":"f","text":"Reposting your live location for fun"}],"bins":[{"id":"guard","label":"Guards you","valence":"pos"},{"id":"handover","label":"Hands you over","valence":"neg"}],"key":{"a":"guard","b":"handover","c":"guard","d":"handover","e":"guard","f":"handover"}},
  {"id":"dc-1027","cat":"decode-the-algorithm","type":"branch","persona":"Arjun","source":"popping the bubble","relearn":"Seek other views on purpose to escape the filter bubble.","hook":"Your feed only shows one side of a hot debate.","options":[{"text":"Follow a thoughtful account from the other side","consequence":"You see views you were never shown, and judge for yourself.","best":true},{"text":"Assume your feed shows the full picture","consequence":"Seek other views; one feed is never the whole story."},{"text":"Mute everyone who disagrees","consequence":"That hardens the bubble; seek a view you weren't shown instead."}],"debrief":"You can't weigh views you're never shown; step outside on purpose."},
  {"id":"dc-1028","cat":"decode-the-algorithm","type":"branch","persona":"Arjun","source":"reclaim the stop","relearn":"Recognise the design and reclaim the stop; it's not just willpower.","hook":"You meant to check one thing; you've scrolled 40 minutes.","options":[{"text":"Name the hook and close the app","consequence":"You take your attention back; the scroll was engineered.","best":true},{"text":"Blame yourself for 'no willpower'","consequence":"It's built to hold you; spot the design, no self-blame."},{"text":"Tell yourself five more minutes","consequence":"Auto-play makes 'five more' endless; name it and stop."}],"debrief":"Long scrolls are by design; naming the hook reclaims the choice."},
  {"id":"dc-1029","cat":"decode-the-algorithm","type":"branch","persona":"any","source":"verify before share","relearn":"Verify the source before forwarding; urgency is a tell to slow down.","hook":"A shocking 'leaked' clip lands with 'share fast!'","options":[{"text":"Check who posted it and if outlets report it","consequence":"You avoid spreading a fake and keep the group's trust.","best":true},{"text":"Forward it at once so they don't miss it","consequence":"Urgency is the bait; check the source first."},{"text":"Believe it because it fits your view","consequence":"Confirmation isn't proof; verify before sharing."}],"debrief":"'Share fast' is engineered urgency; a pause to verify is power."},
  {"id":"dc-1030","cat":"decode-the-algorithm","type":"branch","persona":"Arjun","source":"intentional use","relearn":"Use tech on purpose: open with an intent, not out of habit.","hook":"You pick up your phone with no reason, just habit.","options":[{"text":"Pick one thing you want, then do only that","consequence":"You use the feed on purpose, then put it down.","best":true},{"text":"Open the feed and see where it goes","consequence":"Aimless opening hands over the wheel; set your intent."},{"text":"Scroll till something's worth stopping for","consequence":"It's built so that moment rarely comes; set intent."}],"debrief":"Opening with intent is using the feed; drifting is being used."},
  {"id":"dc-1031","cat":"decode-the-algorithm","type":"branch","persona":"Arjun","source":"notifications off","relearn":"Turn off non-essential notifications; choose your attention.","hook":"Your phone buzzes all day with 'come back' pings.","options":[{"text":"Keep only the notifications that truly matter","consequence":"You get hours and focus back; the rest was just bait.","best":true},{"text":"Leave them all on so you don't 'miss anything'","consequence":"Most pings are bait; keep only the ones that matter."},{"text":"Check each one the instant it buzzes","consequence":"That lets the feed set your attention; choose your pings."}],"debrief":"Most notifications exist to pull you back, not to inform you."},
  {"id":"dc-1032","cat":"decode-the-algorithm","type":"branch","persona":"any","source":"decode the why","relearn":"When a post triggers instant emotion, ask why it was served first.","hook":"A post in your feed makes you instantly furious.","options":[{"text":"Ask why the feed served this and what it wants","consequence":"You see the engineering behind the anger and stay calm.","best":true},{"text":"React and fire off an angry comment","consequence":"That's the engagement it's built for; ask why first."},{"text":"Share it before you've read it fully","consequence":"Outrage is the hook; pause and decode why you see it."}],"debrief":"Strong instant emotion is often engineered; ask 'why this?' first."},
  {"id":"dc-1033","cat":"decode-the-algorithm","type":"branch","persona":"any","source":"trending check","relearn":"Trending isn't true; verify a source before believing or repeating.","hook":"A claim is 'trending No.1' so your friend says it's true.","options":[{"text":"Treat 'trending' as 'spread fast', then check","consequence":"You separate popularity from accuracy and decide on evidence.","best":true},{"text":"Believe it because it's number one","consequence":"Trending measures spread, not truth."},{"text":"Repeat it as fact to others","consequence":"Passing it on spreads it; verify before you repeat."}],"debrief":"Trending tells you it spread, not that it's accurate; check it."},
  {"id":"dc-1034","cat":"decode-the-algorithm","type":"branch","persona":"any","source":"data permissions","relearn":"Guard your privacy: grant only the permissions an app truly needs.","hook":"A new app wants your contacts, location and photos.","options":[{"text":"Grant only what the app genuinely needs","consequence":"You keep your data and footprint smaller and safer.","best":true},{"text":"Tap 'Allow all' to get past it fast","consequence":"Blanket access funds targeting; grant only what's needed."},{"text":"Assume it needs all it asks for","consequence":"Apps over-ask; review each permission first."}],"debrief":"Your data and footprint last; grant only what's truly needed."},
  {"id":"dc-1035","cat":"decode-the-algorithm","type":"match","persona":"any","source":"read the machine","relearn":"Each feature is engineered for engagement; naming what it does defuses it.","hook":"Match each feed design to what it's really doing.","pairs":[{"left":"Infinite scroll","right":"Removes the natural place to stop"},{"left":"Auto-play","right":"Decides your next minute for you"},{"left":"Red badges","right":"Bait you back into the app"},{"left":"Personalised ranking","right":"Tunes the feed to hold you"},{"left":"Streaks","right":"Use loss-fear to keep you returning"}]},
  {"id":"dc-1036","cat":"decode-the-algorithm","type":"match","persona":"any","source":"engineered feelings","relearn":"Strong feelings on a feed are often engineered; spotting the tell hands you back the choice.","hook":"Match the engineered feeling to the tell behind it.","pairs":[{"left":"Sudden fury","right":"Built to make you comment and share"},{"left":"Fear of missing out","right":"An engineered nudge, not a fact"},{"left":"Can't-stop pull","right":"Auto-play, not your weak willpower"},{"left":"'They're hiding this'","right":"Bait to rush you into sharing"},{"left":"Endless 'one more'","right":"The stop was designed away"}]},
  {"id":"dc-1037","cat":"decode-the-algorithm","type":"match","persona":"any","source":"trending vs true","relearn":"Spread is not truth; verification and sources are what make a claim reliable.","hook":"Match each word to what it actually measures.","pairs":[{"left":"Trending","right":"How fast something spread"},{"left":"Verified","right":"Checked against real sources"},{"left":"Viral","right":"Often outrage-driven reach"},{"left":"Sourced","right":"Linked to where it came from"},{"left":"Popular","right":"Spread, not accuracy"}]},
  {"id":"dc-1038","cat":"decode-the-algorithm","type":"match","persona":"any","source":"who pays","relearn":"If the app is free, you're usually the product; your attention and data fund it.","hook":"Match the 'free' app to the real cost you pay.","pairs":[{"left":"Free social app","right":"Your attention and time"},{"left":"Free game with ads","right":"Your data, profiled"},{"left":"Free email","right":"Activity used to target you"},{"left":"Free streaming feed","right":"Your watch-time, sold"},{"left":"Free quiz that wants logins","right":"Your contacts and profile"}]},
  {"id":"dc-1039","cat":"decode-the-algorithm","type":"match","persona":"any","source":"decode the why","relearn":"Asking who, why, what-feeling and who-benefits turns you from target into decoder.","hook":"Match the Decoder question to what it uncovers.","pairs":[{"left":"Who made this?","right":"The source and its motive"},{"left":"Why am I seeing it?","right":"How the algorithm served it"},{"left":"What's it making me feel?","right":"The engineered hook"},{"left":"Who benefits if I share?","right":"Who profits from the spread"},{"left":"What's actually true?","right":"Evidence, not the ranking"}]},
  {"id":"dc-1040","cat":"decode-the-algorithm","type":"match","persona":"any","source":"intentional vs pulled","relearn":"Acting with intent uses the feed; drifting and chasing pings lets it use you.","hook":"Match the habit to whether it uses tech or is used by it.","pairs":[{"left":"Opening with a goal","right":"Using the feed on purpose"},{"left":"Aimless doomscroll","right":"Being used by the feed"},{"left":"Limit, then leave","right":"Choosing your time"},{"left":"Chasing every ping","right":"Letting the feed choose"},{"left":"Curating who you follow","right":"Shaping your own feed"}]},
  {"id":"dc-1041","cat":"decode-the-algorithm","type":"match","persona":"any","source":"escape the bubble","relearn":"Following only your side narrows your world; seeking other views on purpose opens it.","hook":"Match each move to bubble or broadening.","pairs":[{"left":"Follow only your side","right":"Hardens the bubble"},{"left":"Read a source you'd skip","right":"Broadens your view"},{"left":"Mute all disagreement","right":"Narrows what you see"},{"left":"Ask the other case","right":"Opens the bubble"},{"left":"Let the feed pick all news","right":"Tightens the bubble"}]},
  {"id":"dc-1042","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"consolidation","relearn":"Engineered feeds, trending-isn't-true, filter bubbles, intentional use: read the machine.","hook":"Lensy: which 'read the machine' truth lands hardest for you?","prompt":"Pick one.","options":["The feed is engineered for engagement","Trending isn't the same as true","Filter bubbles are real and quiet","I can use the feed on purpose"],"affirm":"Carry that one, and the feed starts working for you instead of on you."},
  {"id":"dc-1043","cat":"decode-the-algorithm","type":"reflect","persona":"Arjun","source":"intentional use","relearn":"Using the feed on purpose, opening with intent and leaving when done, is your power.","hook":"Lensy: what's one way you'd like to use your feed more on purpose?","prompt":"There's no wrong answer here.","options":["Open with a reason, not out of habit","Set a limit and respect it","Turn off the pings that pull me back","Leave once I've got what I came for"],"affirm":"Any of these hands the wheel back to you, a little at a time."},
  {"id":"dc-1044","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"filter bubbles","relearn":"You can't weigh views you're never shown; seek other views on purpose.","hook":"Lensy: how could you let a little more of the world into your feed?","prompt":"Whatever fits you is fine.","options":["Follow one thoughtful account I'd usually skip","Read past my own side on a hot topic","Ask what the other case actually is","Notice when everyone in my feed agrees"],"affirm":"Letting other views in is how you keep a clear, honest picture of the world."},
  {"id":"dc-1045","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"design vs willpower","relearn":"Stopping is design-awareness; recognising the hook reclaims the choice.","hook":"Lensy: which engineered hook do you most want to start naming?","prompt":"Pick the one that's yours.","options":["Auto-play deciding my next video","Infinite scroll with no stop","Badges and pings pulling me back","The 'just one more' feeling"],"affirm":"Naming the hook, not blaming yourself, is what gives the choice back."},
  {"id":"dc-1046","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"attention economy","relearn":"Your attention is the platform's currency; protect it with self-respect, not fear.","hook":"Lensy: knowing your attention is what's sold, what feels worth protecting?","prompt":"Your call, all of these count.","options":["My focus when I'm studying","My calm before I sleep","My time with people I'm actually with","My mood when I put the phone down"],"affirm":"Guarding your attention isn't paranoia; it's self-respect in a feed built to spend it."},
  {"id":"dc-1047","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"trending vs true","relearn":"Trending measures spread, not truth; one question before believing is your power.","hook":"Lensy: next time something's 'trending', what will you ask first?","prompt":"Any of these is a good first question.","options":["Who made this, and why?","Did it spread on anger?","Is there a named source?","Who benefits if I share it?"],"affirm":"One question turns you from passing it on to actually decoding it."},
  {"id":"dc-1048","cat":"decode-the-algorithm","type":"reflect","persona":"any","source":"digital citizenship","relearn":"Reading the system, not just spotting lies, is the leap to digital wisdom.","hook":"Lensy: you've started reading the machine. What will you carry from it?","prompt":"Take whichever is yours.","options":["The feed is designed, so I can decode it","I choose, the algorithm doesn't","I can step outside my bubble","Critical, never cynical"],"affirm":"That's the leap from media-literate to digitally wise, and it's yours to keep."},
  {"id":"dc-1049","cat":"decode-the-algorithm","type":"role-play","persona":"Arjun","source":"intervene","relearn":"Trending measures spread, not truth; check the source before believing it.","hook":"A friend says 'it's number one on trending, so it's obviously true.'","setup":"Decode it for them, kindly. Say:","yourLine":[{"text":"\"Trending just means it spread fast, often on anger. Let's check who actually sourced it.\"","best":true},{"text":"\"Yeah, if it's trending it must be real.\""}]},
  {"id":"dc-1050","cat":"decode-the-algorithm","type":"role-play","persona":"any","source":"intervene","relearn":"Verify the source before forwarding; 'share fast' is engineered urgency.","hook":"Your cousin's about to forward a shocking 'leaked' clip to the family group.","setup":"Slow them down, no drama. Say:","yourLine":[{"text":"\"Before you send it, let's see who posted it and if any real outlet has it.\"","best":true},{"text":"\"Just forward it, everyone should see this.\""}]},
  {"id":"dc-1051","cat":"decode-the-algorithm","type":"role-play","persona":"Arjun","source":"boundary","relearn":"Long scrolls are by design; recognising the hook beats self-blame.","hook":"A friend keeps saying you've 'no willpower' for scrolling so long.","setup":"Reframe it for both of you. Say:","yourLine":[{"text":"\"It's built to be endless, auto-play removes the stop. Naming the design helps more than blame.\"","best":true},{"text":"\"Yeah, I'm just hopeless at putting it down.\""}]},
  {"id":"dc-1052","cat":"decode-the-algorithm","type":"role-play","persona":"any","source":"bubble","relearn":"A like-minded feed is a bubble; you can't weigh views you're never shown.","hook":"A friend insists 'everyone I follow agrees, so this view is just obviously right.'","setup":"Open it up gently. Say:","yourLine":[{"text":"\"That might be our bubble talking. Want to read what the other side actually argues?\"","best":true},{"text":"\"True, everyone I see thinks the same, so it must be right.\""}]},
  {"id":"dc-1053","cat":"decode-the-algorithm","type":"role-play","persona":"Arjun","source":"intentional use","relearn":"Opening with intent and leaving when done is using the feed, not being used.","hook":"A friend says 'just one thing' and is still scrolling 30 minutes later.","setup":"Nudge them kindly. Say:","yourLine":[{"text":"\"The feed's built so 'one thing' never ends. Got what you came for? Let's put it down.\"","best":true},{"text":"\"Same, I always end up scrolling for ages too.\""}]},
  {"id":"dc-1054","cat":"decode-the-algorithm","type":"role-play","persona":"any","source":"intervene","relearn":"Outrage posts are engineered for engagement; sharing them feeds the machine.","hook":"Someone in your group shares an outrage post just to 'see what people say.'","setup":"Decode the bait, no lecture. Say:","yourLine":[{"text":"\"That post is engineered to make us argue. Sharing it is exactly what it's built for.\"","best":true},{"text":"\"Ha, yeah, let's all pile on in the comments.\""}]},
  {"id":"dc-1055","cat":"decode-the-algorithm","type":"role-play","persona":"Arjun","source":"privacy","relearn":"Grant only the permissions an app truly needs; your data and footprint last.","hook":"A friend taps 'Allow all' on every app to get past the permission screen.","setup":"Flag it, no judgement. Say:","yourLine":[{"text":"\"You can grant just what it needs. 'Allow all' hands over data you don't have to.\"","best":true},{"text":"\"Yeah, I always just tap allow to make it go away.\""}]},
  {"id":"dc-1056","cat":"decode-the-algorithm","type":"role-play","persona":"any","source":"intervene","relearn":"Targeted content is built from your data; knowing you isn't proof it's true.","hook":"A friend believes an ad-style post because 'it knew exactly what I wanted.'","setup":"Name the design for them. Say:","yourLine":[{"text":"\"That's targeting from your data, not a sign it's true. The feed knows you, that's the product.\"","best":true},{"text":"\"Spooky how it gets me, must be meant for me.\""}]},
  {"id":"dc-1080","type":"strike-rewrite","persona":"Veer","source":"forwarded as fact","hook":"\"It came on the family WhatsApp group, so it must be checked.\"","myth":{"un":"If elders forwarded it, it's already verified.","re":"Forwards aren't checked by anyone; decode the content, not who sent it.","why":"A trusted relative can pass on a fake without knowing."},"relearn":"A forward isn't verified just because family sent it; check the content itself.","cat":"decode-the-influence"},
  {"id":"dc-1081","type":"strike-rewrite","persona":"Veer","source":"deepfake voice","hook":"\"That voice note is clearly my favourite actor's real voice.\"","myth":{"un":"A voice that sounds exactly right must be real.","re":"AI can clone a familiar voice now; verify the source, don't trust your ear.","why":"Sounding real stopped being proof, just like looking real did."},"relearn":"A familiar-sounding voice can be AI-cloned; verify the source, not the sound.","cat":"decode-the-influence"},
  {"id":"dc-1082","type":"strike-rewrite","persona":"Veer","source":"screenshot edited","hook":"\"A screenshot of a chat is solid proof of what was said.\"","myth":{"un":"A screenshot can't be faked.","re":"Screenshots are trivial to edit or stage; trace it to the real source first.","why":"A picture of text is not the text's origin."},"relearn":"Screenshots are easy to fake; trace the claim to its real source before believing it.","cat":"decode-the-influence"},
  {"id":"dc-1083","type":"strike-rewrite","persona":"Veer","source":"verified tick","hook":"\"This account has a blue tick, so whatever it posts is true.\"","myth":{"un":"A verified badge means the posts are accurate.","re":"A badge can be bought and only marks an account, never each claim.","why":"Verifying an account isn't verifying its facts."},"relearn":"A blue tick marks an account, not the truth of each post; still check the claim.","cat":"decode-the-influence"},
  {"id":"dc-1084","type":"strike-rewrite","persona":"Veer","source":"old clip recycled","hook":"\"This dramatic clip is from the event everyone's talking about today.\"","myth":{"un":"A clip going viral now must be from the current event.","re":"Old clips get relabelled as breaking news; check when and where it's really from.","why":"Recycled footage with a fresh caption is a classic tell."},"relearn":"Viral clips are often old footage relabelled; check the real date and place.","cat":"decode-the-influence"},
  {"id":"dc-1085","type":"strike-rewrite","persona":"any","source":"more shares = true","hook":"\"Thousands of people shared it, so it can't be made up.\"","myth":{"un":"If huge numbers shared it, it must be real.","re":"Spread measures emotion and engagement, not accuracy; popularity isn't proof.","why":"Fakes go viral precisely because they're built to be shared."},"relearn":"How much something is shared measures spread, not truth; popularity isn't proof.","cat":"decode-the-influence"},
  {"id":"dc-1086","type":"strike-rewrite","persona":"any","source":"reverse-image lazy","hook":"\"If the photo looks normal, there's no point checking it.\"","myth":{"un":"A normal-looking photo needs no checking.","re":"A reverse-image search takes seconds and often reveals it's old or staged.","why":"The quick check beats the confident eye."},"relearn":"A quick reverse-image search often exposes a recycled or staged photo in seconds.","cat":"decode-the-influence"},
  {"id":"dc-1087","type":"strike-rewrite","persona":"any","source":"fear urgency","hook":"\"A warning this scary and urgent has to be passed on right away.\"","myth":{"un":"Scary, urgent warnings should be forwarded fast.","re":"Manufactured fear plus 'forward now' is a manipulation tell; slow down and check.","why":"Urgency exists to stop you from thinking."},"relearn":"Scary 'forward now' warnings use urgency to bypass thinking; slow down and verify.","cat":"decode-the-influence"},
  {"id":"dc-1088","type":"strike-rewrite","persona":"any","source":"cashback scam","hook":"\"The message says I won cashback, so I enter my UPI PIN to receive it.\"","myth":{"un":"You enter your UPI PIN to receive money.","re":"You never enter a PIN to get money in, only to pay out; that prompt is a scam.","why":"Receiving never needs your secret PIN."},"relearn":"You enter a UPI PIN only to send money, never to receive it; that 'reward' is a scam.","cat":"decode-the-influence"},
  {"id":"dc-1089","type":"strike-rewrite","persona":"any","source":"OTP social-engineering","hook":"\"The caller sounds official, so sharing the OTP they ask for is fine.\"","myth":{"un":"A convincing official caller can be given your OTP.","re":"No real bank or service ever asks for your OTP; the ask itself is the scam.","why":"The OTP is the last lock; only a thief needs it from you."},"relearn":"No genuine service asks for your OTP; being asked at all is the scam signal.","cat":"decode-the-influence"},
  {"id":"dc-1090","type":"strike-rewrite","persona":"any","source":"dark pattern default","hook":"\"If a box is already ticked, the app must know what's best for me.\"","myth":{"un":"A pre-ticked box is the helpful default.","re":"Pre-ticked boxes are a dark pattern set to benefit the app, not you; untick and read.","why":"The default is chosen for their gain, not your consent."},"relearn":"A pre-ticked box is designed for the app's gain; untick it and read what you agreed to.","cat":"decode-the-influence"},
  {"id":"dc-1091","type":"strike-rewrite","persona":"any","source":"propaganda repetition","hook":"\"I've heard this slogan so many times it must be true by now.\"","myth":{"un":"Hearing something repeated often makes it true.","re":"Repetition only makes a claim familiar; familiarity isn't evidence.","why":"Endless repeating is a propaganda tool, not a fact-check."},"relearn":"Repetition makes a claim feel familiar, not true; familiarity is not evidence.","cat":"decode-the-influence"},
  {"id":"dc-1092","type":"strike-rewrite","persona":"any","source":"AI image tells","hook":"\"You can always catch an AI image by counting fingers in it.\"","myth":{"un":"AI pictures always have obvious flaws like extra fingers.","re":"AI fixes its tells fast; the reliable move is checking the source, not hunting flaws.","why":"It's an arms race the eye alone keeps losing."},"relearn":"AI fixes its visible flaws quickly; rely on verifying the source, not spotting glitches.","cat":"decode-the-influence"},
  {"id":"dc-1093","type":"sort","persona":"Arjun","source":"tell vs reliable","hook":"Sort each one: a manipulation tell, or a reliable signal?","items":[{"id":"a","text":"\"Forward before it's deleted!\""},{"id":"b","text":"A dateline and named reporter"},{"id":"c","text":"\"They don't want you to know this\""},{"id":"d","text":"A link to the original report"},{"id":"e","text":"All caps and ten fire emojis"},{"id":"f","text":"A correction noted at the bottom"}],"bins":[{"id":"tell","label":"Manipulation tell","valence":"neg"},{"id":"reliable","label":"Reliable signal","valence":"pos"}],"key":{"a":"tell","b":"reliable","c":"tell","d":"reliable","e":"tell","f":"reliable"},"relearn":"Urgency, secrecy framing and caps are tells; datelines, source links and corrections are reliable.","cat":"decode-the-influence"},
  {"id":"dc-1094","type":"sort","persona":"Arjun","source":"scam vs genuine","hook":"Sort each message: scam signal, or a normal genuine one?","items":[{"id":"a","text":"\"Claim your prize, pay a small fee first\""},{"id":"b","text":"Your order is out for delivery"},{"id":"c","text":"\"Your account is blocked, verify PIN now\""},{"id":"d","text":"A bill reminder from your saved provider"},{"id":"e","text":"\"Job offer: deposit to confirm seat\""},{"id":"f","text":"An OTP you yourself just requested"}],"bins":[{"id":"scam","label":"Scam signal","valence":"neg"},{"id":"genuine","label":"Likely genuine","valence":"pos"}],"key":{"a":"scam","b":"genuine","c":"scam","d":"genuine","e":"scam","f":"genuine"},"relearn":"Pay-to-win, verify-your-PIN and pay-to-get-a-job are scams; expected updates and your own OTP aren't.","cat":"decode-the-influence"},
  {"id":"dc-1095","type":"sort","persona":"Arjun","source":"influence families","hook":"Sort each example into the influence family it belongs to.","items":[{"id":"a","text":"A cloned video of a leader saying fake words"},{"id":"b","text":"A fake countdown timer at checkout"},{"id":"c","text":"An AI-altered photo of an event"},{"id":"d","text":"A pre-ticked 'add insurance' box"},{"id":"e","text":"A face-swapped clip passed as real"},{"id":"f","text":"\"Only 1 seat left!\" that never changes"}],"bins":[{"id":"deepfake","label":"Deepfake / AI fake","valence":"neg"},{"id":"dark","label":"Dark pattern","valence":"neg"}],"key":{"a":"deepfake","b":"dark","c":"deepfake","d":"dark","e":"deepfake","f":"dark"},"relearn":"Cloned and AI-altered media are deepfakes; fake timers, pre-ticks and false scarcity are dark patterns.","cat":"decode-the-influence"},
  {"id":"dc-1096","type":"sort","persona":"Arjun","source":"verify steps vs react","hook":"Sort: a step that verifies, or a reaction that spreads risk?","items":[{"id":"a","text":"Check two independent outlets"},{"id":"b","text":"Forward to the whole family group"},{"id":"c","text":"Search for the original source"},{"id":"d","text":"React before reading past the headline"},{"id":"e","text":"Note the date and place"},{"id":"f","text":"Share because it made you angry"}],"bins":[{"id":"verify","label":"Verifies","valence":"pos"},{"id":"react","label":"Spreads risk","valence":"neg"}],"key":{"a":"verify","b":"react","c":"verify","d":"react","e":"verify","f":"react"},"relearn":"Cross-checking, finding the origin and noting date and place verify; impulse forwarding spreads risk.","cat":"decode-the-influence"},
  {"id":"dc-1097","type":"sort","persona":"Arjun","source":"who benefits","hook":"Sort each post by who it's really built to serve.","items":[{"id":"a","text":"\"Buy now, secret deal ends tonight\""},{"id":"b","text":"A how-to guide with no product push"},{"id":"c","text":"Rage-bait engineered to get angry shares"},{"id":"d","text":"A clearly labelled, sourced explainer"},{"id":"e","text":"\"Tag 10 friends or bad luck follows\""},{"id":"f","text":"A creator citing where they got their info"}],"bins":[{"id":"them","label":"Serves the poster","valence":"neg"},{"id":"you","label":"Serves you","valence":"pos"}],"key":{"a":"them","b":"you","c":"them","d":"you","e":"them","f":"you"},"relearn":"Hard-sell urgency, rage-bait and chain dares serve the poster; sourced, honest help serves you.","cat":"decode-the-influence"},
  {"id":"dc-1098","type":"sort","persona":"any","source":"propaganda vs argument","hook":"Sort: a propaganda technique, or fair argument?","items":[{"id":"a","text":"Painting one group as the enemy"},{"id":"b","text":"Citing evidence you can check"},{"id":"c","text":"Endlessly repeating a catchy slogan"},{"id":"d","text":"Admitting a point against your side"},{"id":"e","text":"\"Everyone good agrees with us\""},{"id":"f","text":"Naming who made the claim and why"}],"bins":[{"id":"prop","label":"Propaganda","valence":"neg"},{"id":"fair","label":"Fair argument","valence":"pos"}],"key":{"a":"prop","b":"fair","c":"prop","d":"fair","e":"prop","f":"fair"},"relearn":"Enemy framing, slogans and bandwagon are propaganda; checkable evidence and named sources are fair.","cat":"decode-the-influence"},
  {"id":"dc-1099","type":"sort","persona":"any","source":"strong vs weak source","hook":"Sort each as a stronger or weaker source for a claim.","items":[{"id":"a","text":"\"A friend's cousin told them\""},{"id":"b","text":"The named original report"},{"id":"c","text":"An anonymous forwarded image"},{"id":"d","text":"Several outlets reporting the same"},{"id":"e","text":"A screenshot with no link"},{"id":"f","text":"A primary document you can open"}],"bins":[{"id":"weak","label":"Weaker source","valence":"uhoh"},{"id":"strong","label":"Stronger source","valence":"pos"}],"key":{"a":"weak","b":"strong","c":"weak","d":"strong","e":"weak","f":"strong"},"relearn":"Hearsay, anonymous forwards and linkless screenshots are weak; named originals and primary docs are strong.","cat":"decode-the-influence"},
  {"id":"dc-1100","type":"sort","persona":"any","source":"dark pattern vs honest design","hook":"Sort each interface move: dark pattern, or honest design?","items":[{"id":"a","text":"A hidden, tiny 'unsubscribe' link"},{"id":"b","text":"A clear, equal-size 'No thanks'"},{"id":"c","text":"A guilt button: 'No, I hate saving'"},{"id":"d","text":"A plain price with no hidden add-ons"},{"id":"e","text":"A countdown that resets on refresh"},{"id":"f","text":"An easy one-tap cancel"}],"bins":[{"id":"dark","label":"Dark pattern","valence":"neg"},{"id":"honest","label":"Honest design","valence":"pos"}],"key":{"a":"dark","b":"honest","c":"dark","d":"honest","e":"dark","f":"honest"},"relearn":"Hidden exits, guilt buttons and fake timers are dark patterns; clear choices and easy cancel are honest.","cat":"decode-the-influence"},
  {"id":"dc-1101","type":"sort","persona":"any","source":"resist vs exposed","hook":"Sort each habit: helps you resist influence, or leaves you exposed?","items":[{"id":"a","text":"Pausing before you share"},{"id":"b","text":"Believing it because it's shocking"},{"id":"c","text":"Asking 'who benefits from this?'"},{"id":"d","text":"Assuming you're too clever to be fooled"},{"id":"e","text":"Checking the source every time"},{"id":"f","text":"Reacting to the headline alone"}],"bins":[{"id":"resist","label":"Helps resist","valence":"pos"},{"id":"open","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"resist","b":"open","c":"resist","d":"open","e":"resist","f":"open"},"relearn":"Pausing, asking who benefits and checking sources resist; shock-belief and overconfidence expose you.","cat":"decode-the-influence"},
  {"id":"dc-1102","type":"sort","persona":"any","source":"real-account tells","hook":"Sort each profile clue: bot-farm tell, or a real account?","items":[{"id":"a","text":"Made yesterday, posting 200 times a day"},{"id":"b","text":"Years of varied, personal posts"},{"id":"c","text":"A stock photo as its only picture"},{"id":"d","text":"Real friends in tagged comments"},{"id":"e","text":"The same line copy-pasted everywhere"},{"id":"f","text":"A normal mix of likes and replies"}],"bins":[{"id":"bot","label":"Bot-farm tell","valence":"neg"},{"id":"real","label":"Real account","valence":"pos"}],"key":{"a":"bot","b":"real","c":"bot","d":"real","e":"bot","f":"real"},"relearn":"Brand-new, spammy, copy-paste, stock-photo profiles are bot tells; varied lived history reads real.","cat":"decode-the-influence"},
  {"id":"dc-1103","type":"branch","persona":"Arjun","source":"deepfake of a classmate","hook":"A fake clip is going around that puts a classmate's face on someone else.","options":[{"text":"Don't share it; tell them and report it","consequence":"You stop the spread and back a friend.","outcome":"protect","best":true},{"text":"Screenshot it for the group laugh","consequence":"That spreads harm; a deepfake of a person isn't a joke, report it."}],"debrief":"With a fake of a real person, don't spread it; support them and report it.","relearn":"If a deepfake targets someone you know, don't forward it; tell them and report it.","cat":"decode-the-influence"},
  {"id":"dc-1104","type":"branch","persona":"Arjun","source":"OTP call pressure","hook":"A caller says your account will be frozen unless you read out the OTP now.","options":[{"text":"Hang up; no real service asks for an OTP","consequence":"You keep your account safe.","outcome":"safe","best":true},{"text":"Read it out to avoid the freeze","consequence":"That hands a thief your account; no genuine service needs your OTP."}],"debrief":"Pressure plus an OTP request is the scam; hang up and verify on the official app.","relearn":"A caller demanding your OTP under pressure is a scam; hang up and share nothing.","cat":"decode-the-influence"},
  {"id":"dc-1105","type":"branch","persona":"any","source":"too-good job offer","hook":"A message offers a high-pay work-from-home job if you pay a small registration fee.","options":[{"text":"Refuse; real jobs don't charge you to join","consequence":"You dodge an advance-fee scam.","outcome":"safe","best":true},{"text":"Pay the small fee, it's worth a shot","consequence":"Paying to get a job is the scam; the 'job' vanishes after you pay."}],"debrief":"Pay-to-get-a-job and urgency are the advance-fee scam signature; walk away.","relearn":"A job that charges you to join is a scam; genuine work never asks for a fee upfront.","cat":"decode-the-influence"},
  {"id":"dc-1106","type":"branch","persona":"any","source":"viral health cure","hook":"A forward claims one home trick instantly cures a serious illness.","options":[{"text":"Check trusted health sources before sharing","consequence":"You avoid spreading dangerous advice.","outcome":"verify","best":true},{"text":"Forward it; it might help someone","consequence":"Unchecked 'miracle cures' can cause harm; verify with a doctor's source first."}],"debrief":"Miracle-cure forwards can endanger people; verify with trusted health sources first.","relearn":"Verify viral 'instant cure' claims with trusted health sources before sharing or trying them.","cat":"decode-the-influence"},
  {"id":"dc-1107","type":"branch","persona":"any","source":"fake countdown checkout","hook":"A shopping page flashes 'offer ends in 2:00' to rush you into buying now.","options":[{"text":"Ignore the timer and decide calmly","consequence":"You buy only if you actually want it.","outcome":"calm","best":true},{"text":"Rush to buy before it 'ends'","consequence":"Fake countdowns reset on refresh; the urgency is manufactured to rush you."}],"debrief":"A countdown that pressures you is usually fake; decide on your own time.","relearn":"Checkout countdowns are often fake pressure; ignore the timer and decide calmly.","cat":"decode-the-influence"},
  {"id":"dc-1108","type":"branch","persona":"Arjun","source":"breaking-news photo","hook":"A dramatic 'breaking news' photo is spreading, but you can't find it on any outlet.","options":[{"text":"Run a reverse-image search first","consequence":"You find it's an old, recycled photo.","outcome":"verify","best":true},{"text":"Share it as breaking before others do","consequence":"Being first with a fake spreads it; reverse-search the image before sharing."}],"debrief":"If no real outlet carries a 'breaking' photo, reverse-search it before believing it.","relearn":"If no credible outlet has a 'breaking' image, reverse-search it before sharing.","cat":"decode-the-influence"},
  {"id":"dc-1109","type":"branch","persona":"any","source":"friend shared a fake","hook":"A close friend just shared something you can tell is fake.","options":[{"text":"Message them kindly with the real source","consequence":"You correct it without shaming them.","outcome":"kind","best":true},{"text":"Call them out publicly in the comments","consequence":"Public shaming makes people defensive; share the correction privately and kindly."}],"debrief":"Anyone can share a fake; correct a friend privately and kindly, decode content not the person.","relearn":"Even a friend can share a fake; correct it kindly and privately, not by public shaming.","cat":"decode-the-influence"},
  {"id":"dc-1110","type":"branch","persona":"any","source":"quiz harvesting data","hook":"A fun quiz asks for your phone, birthday and contacts to reveal your 'true self'.","options":[{"text":"Skip it; the quiz is harvesting your data","consequence":"You keep your personal info private.","outcome":"safe","best":true},{"text":"Fill it in; it's just a harmless game","consequence":"These 'quizzes' often exist to collect data; don't hand over personal details."}],"debrief":"A 'fun quiz' demanding personal data is often data-harvesting; give it nothing.","relearn":"Quizzes asking for personal data are often harvesting it; skip them and keep info private.","cat":"decode-the-influence"},
  {"id":"dc-1111","type":"branch","persona":"any","source":"rage-bait headline","hook":"A headline is written purely to make you furious and hit share instantly.","options":[{"text":"Read the full piece and check it first","consequence":"You see the headline twisted the facts.","outcome":"verify","best":true},{"text":"Quote it angrily without reading on","consequence":"That spreads the bait; the anger is the product, read and check first."}],"debrief":"Outrage headlines are engineered to be shared on reflex; read fully and verify first.","relearn":"Rage-bait headlines are built to be shared on reflex; read the full piece and verify first.","cat":"decode-the-influence"},
  {"id":"dc-1112","type":"branch","persona":"any","source":"spread it then learned","hook":"You shared something yesterday and now realise it was false.","options":[{"text":"Post a correction and note the tell","consequence":"You limit the harm and get sharper.","outcome":"repair","best":true},{"text":"Leave it up to avoid embarrassment","consequence":"Leaving a fake up lets it travel; correct it openly, no shame, just repair."}],"debrief":"Everyone gets fooled sometimes; the decoder move is to correct openly and learn the tell.","relearn":"If you spread something false, correct it openly and learn the tell, no shame, just repair.","cat":"decode-the-influence"},
  {"id":"dc-1113","type":"spot","persona":"Veer","source":"scam SMS red flags","hook":"Spot the two red flags in this 'bank' SMS.","scene":[{"id":"a","text":"\"Your KYC expires today, act now or account blocks\"","trick":true},{"id":"b","text":"It comes from a normal personal mobile number","trick":true},{"id":"c","text":"Your bank's app shows no such alert","trick":false},{"id":"d","text":"The official bank number is printed on your card","trick":false},{"id":"e","text":"You can call the bank yourself to check","trick":false}],"why":"Manufactured urgency and a personal-number 'bank' message are the scam tells; verify in the real app.","relearn":"'Expires today' urgency and a personal-number sender are scam tells; verify in the official app.","cat":"decode-the-influence"},
  {"id":"dc-1114","type":"spot","persona":"Veer","source":"phishing link tells","hook":"Spot the two red flags in this 'you won a prize' message.","scene":[{"id":"a","text":"A link like bank-rewards-india.xyz, not the real site","trick":true},{"id":"b","text":"It asks you to enter your card PIN to claim","trick":true},{"id":"c","text":"You never entered any such contest","trick":false},{"id":"d","text":"Real prizes don't need your secret PIN","trick":false},{"id":"e","text":"You can ignore and delete it safely","trick":false}],"why":"A look-alike link and a PIN request are the phishing tells; a real prize never needs your PIN.","relearn":"A look-alike web link and a request for your PIN are phishing tells; delete and ignore.","cat":"decode-the-influence"},
  {"id":"dc-1115","type":"spot","persona":"any","source":"deepfake video tells","hook":"Spot the two tells this 'celebrity investment' clip is fake.","scene":[{"id":"a","text":"It promises guaranteed doubling of your money","trick":true},{"id":"b","text":"The clip lives only on an unknown reposted page","trick":true},{"id":"c","text":"No outlet or official channel carries it","trick":false},{"id":"d","text":"You can verify the claim at the source","trick":false},{"id":"e","text":"Real advisers never promise sure returns","trick":false}],"why":"A 'guaranteed money' promise and an unverifiable repost are deepfake-scam tells; verify the source.","relearn":"'Guaranteed returns' and an unverifiable repost are deepfake-scam tells; verify the source.","cat":"decode-the-influence"},
  {"id":"dc-1116","type":"spot","persona":"any","source":"dark pattern screen","hook":"Spot the two dark patterns on this sign-up screen.","scene":[{"id":"a","text":"A pre-ticked box adding paid extras","trick":true},{"id":"b","text":"A 'No, I don't want to save money' decline link","trick":true},{"id":"c","text":"A clearly shown total price","trick":false},{"id":"d","text":"An equal-size 'No thanks' button","trick":false},{"id":"e","text":"An easy one-tap way to cancel later","trick":false}],"why":"A pre-ticked paid box and a guilt-trip decline are dark patterns; clear prices and equal choices aren't.","relearn":"Pre-ticked paid boxes and guilt-trip 'decline' wording are dark patterns nudging you off course.","cat":"decode-the-influence"},
  {"id":"dc-1117","type":"spot","persona":"any","source":"propaganda post tells","hook":"Spot the two propaganda tells in this post.","scene":[{"id":"a","text":"It brands a whole group as 'the enemy'","trick":true},{"id":"b","text":"It repeats one slogan over and over","trick":true},{"id":"c","text":"It links to evidence you can open","trick":false},{"id":"d","text":"It names who made the claim","trick":false},{"id":"e","text":"It admits one point against its own side","trick":false}],"why":"Enemy framing and endless slogans are propaganda tells; sources, named claims and fairness aren't.","relearn":"'Enemy' framing and slogan-repetition are propaganda tells; checkable, fair posts show neither.","cat":"decode-the-influence"},
  {"id":"dc-1118","type":"spot","persona":"Veer","source":"fake account tells","hook":"Spot the two tells that this 'official' account is fake.","scene":[{"id":"a","text":"The handle adds a sneaky extra letter","trick":true},{"id":"b","text":"It was created only days ago","trick":true},{"id":"c","text":"The real brand links its page from its site","trick":false},{"id":"d","text":"You can check the official handle yourself","trick":false},{"id":"e","text":"A long, consistent history reads genuine","trick":false}],"why":"A misspelt look-alike handle and a brand-new account are impostor tells; verify via the official site.","relearn":"A misspelt handle and a days-old account are impostor tells; confirm via the brand's official site.","cat":"decode-the-influence"},
  {"id":"dc-1119","type":"role-play","persona":"any","source":"slow a forward","hook":"A relative is about to forward a scary 'warning' to everyone.","setup":"Slow it down kindly. Say:","yourLine":[{"text":"\"Wait, let's check if it's real before we forward it to everyone.\"","best":true},{"text":"\"Okay, just send it, better safe than sorry.\""}],"relearn":"Kindly suggest checking a scary 'warning' is real before forwarding it on.","cat":"decode-the-influence"},
  {"id":"dc-1120","type":"role-play","persona":"any","source":"refuse OTP ask","hook":"A caller claiming to be from your bank asks you to read out the OTP.","setup":"Hold your line. Say:","yourLine":[{"text":"\"No bank asks for an OTP. I'll hang up and check on the official app.\"","best":true},{"text":"\"Um, okay, the code is...\""}],"relearn":"Refuse any OTP request and verify on the official app; no real service needs your OTP.","cat":"decode-the-influence"},
  {"id":"dc-1121","type":"role-play","persona":"any","source":"correct a friend","hook":"A friend posts a fake and tags you to share it too.","setup":"Correct it without shaming. Say:","yourLine":[{"text":"\"Hey, I checked and this one's fake, here's the real source.\"","best":true},{"text":"\"Sharing it now so I don't seem rude.\""}],"relearn":"Privately share the real source instead of forwarding a friend's fake, kind not harsh.","cat":"decode-the-influence"},
  {"id":"dc-1122","type":"role-play","persona":"any","source":"decline pressure buy","hook":"A site keeps flashing 'last chance!' to make you buy add-ons now.","setup":"Keep your own pace. Say:","yourLine":[{"text":"\"I'll decide on my own time, the countdown doesn't change that.\"","best":true},{"text":"\"Better grab it before the timer runs out.\""}],"relearn":"Decide on your own time; a flashing countdown is manufactured pressure, not a real deadline.","cat":"decode-the-influence"},
  {"id":"dc-1123","type":"role-play","persona":"any","source":"ask who benefits","hook":"Someone insists a viral claim is true because 'everyone is posting it'.","setup":"Decode it out loud. Say:","yourLine":[{"text":"\"Lots of shares isn't proof, who made this and who benefits?\"","best":true},{"text":"\"Yeah, if it's everywhere it must be true.\""}],"relearn":"Many shares isn't proof; ask who made a claim and who benefits before believing it.","cat":"decode-the-influence"},
  {"id":"dc-1124","type":"role-play","persona":"any","source":"protect deepfake target","hook":"Friends are giggling over a deepfake clip of a schoolmate.","setup":"Stand up for them. Say:","yourLine":[{"text":"\"That's a fake of a real person, let's not share it, it's not a joke.\"","best":true},{"text":"\"Ha, send it to the group, it's funny.\""}],"relearn":"Refuse to spread a deepfake of a real person and name it as harm, not a joke.","cat":"decode-the-influence"},
  {"id":"dc-1125","type":"role-play","persona":"any","source":"own up to a share","hook":"You shared a claim that turned out false; the group is still passing it on.","setup":"Own it openly. Say:","yourLine":[{"text":"\"I shared this earlier and it's actually false, here's the correction.\"","best":true},{"text":"\"I'll just stay quiet and hope nobody noticed.\""}],"relearn":"Openly correct a false claim you shared; honest repair beats quietly hoping no one noticed.","cat":"decode-the-influence"},
  {"id":"dc-1126","type":"match","persona":"any","source":"influence type to tell","hook":"Match each influence type to its giveaway tell.","pairs":[{"left":"Phishing message","right":"A look-alike link asking for your PIN"},{"left":"Deepfake clip","right":"Convincing footage with no verifiable source"},{"left":"Dark pattern","right":"A pre-ticked box you didn't choose"},{"left":"Propaganda post","right":"Endless slogans and 'enemy' framing"},{"left":"Advance-fee scam","right":"Pay a small fee to claim a big prize"}],"relearn":"Each influence type has a learnable tell: look-alike links, unverifiable footage, pre-ticks, slogans, pay-first.","cat":"decode-the-influence"},
  {"id":"dc-1127","type":"match","persona":"any","source":"tell to defence","hook":"Match each tell to the move that defuses it.","pairs":[{"left":"'Forward now or else!' urgency","right":"Pause and check before sharing"},{"left":"A photo you can't place","right":"Run a reverse-image search"},{"left":"A caller wanting your OTP","right":"Hang up and use the official app"},{"left":"'Guaranteed double your money'","right":"Treat it as a scam, verify the source"},{"left":"A fake checkout countdown","right":"Ignore the timer, decide calmly"}],"relearn":"Every manipulation tell has a defence: pause, reverse-search, hang up, verify, ignore the fake timer.","cat":"decode-the-influence"},
  {"id":"dc-1128","type":"match","persona":"any","source":"manipulation truths","hook":"Match each manipulation truth to why it matters.","pairs":[{"left":"It only works while invisible","right":"Naming the tell defuses it"},{"left":"Everyone is targeted","right":"It's not about being clever"},{"left":"'Looks real' isn't proof","right":"Verify the source, not your eyes"},{"left":"Urgency is a tactic","right":"Slowing down is your defence"},{"left":"Spread isn't truth","right":"Ask who benefits before believing"}],"relearn":"Manipulation works while invisible and hits everyone; naming tells and verifying sources defuse it.","cat":"decode-the-influence"},
  {"id":"dc-1129","type":"match","persona":"any","source":"verify steps","hook":"Match each thing to check against its verification step.","pairs":[{"left":"Is this image old?","right":"Reverse-image search it"},{"left":"Is this account official?","right":"Find the link on the brand's own site"},{"left":"Is this claim backed up?","right":"See if independent outlets report it"},{"left":"Who is behind this post?","right":"Look at who made it and why"},{"left":"Is this video genuine?","right":"Trace it to a verifiable original"}],"relearn":"Verifying means tracing images, accounts, claims and videos back to checkable, independent origins.","cat":"decode-the-influence"},
  {"id":"dc-1130","type":"match","persona":"any","source":"scam line to red flag","hook":"Match each scam line to the red flag it reveals.","pairs":[{"left":"\"Pay a fee to release your prize\"","right":"You pay to receive, never how it works"},{"left":"\"Share your OTP to verify\"","right":"No real service ever needs your OTP"},{"left":"\"Account blocks in 10 minutes\"","right":"Made-up urgency to stop you thinking"},{"left":"\"Click this link to fix it\"","right":"A look-alike address, not the real site"},{"left":"\"Guaranteed returns, no risk\"","right":"No real investment can promise that"}],"relearn":"Pay-to-receive, OTP asks, urgency, look-alike links and 'no-risk' all flag a scam.","cat":"decode-the-influence"},
  {"id":"dc-1131","type":"match","persona":"any","source":"dark patterns named","hook":"Match each dark pattern to what it tricks you into.","pairs":[{"left":"Pre-ticked add-on box","right":"Buying extras you didn't choose"},{"left":"Fake countdown timer","right":"Rushing a decision you'd rethink"},{"left":"Hidden tiny unsubscribe link","right":"Staying signed up by accident"},{"left":"Guilt-trip decline wording","right":"Feeling bad for saying no"},{"left":"'Only 1 left!' false scarcity","right":"Panic-buying on a fake shortage"}],"relearn":"Pre-ticks, fake timers, hidden exits, guilt wording and false scarcity each push a choice you didn't mean.","cat":"decode-the-influence"},
  {"id":"dc-1132","type":"reflect","persona":"any","source":"pause habit","hook":"Lensy: before you share something that grabs you, what's your pause?","prompt":"What feels like yours?","options":["I ask who made it","I check the source","I just breathe first"],"relearn":"A short pause before sharing gives your decoder brain time to catch up; any version works.","affirm":"Any pause that slows the reflex gives your decoder brain time to catch up, that's the skill.","cat":"decode-the-influence"},
  {"id":"dc-1133","type":"reflect","persona":"any","source":"who benefits","hook":"Lensy: when a post wants something from you, what do you ask?","prompt":"Pick what fits you.","options":["Who benefits?","What's the catch?","Why now, why me?"],"relearn":"Asking who benefits when a post wants something turns you from a target into a decoder.","affirm":"Asking who benefits turns you from a target into a decoder, every version of the question works.","cat":"decode-the-influence"},
  {"id":"dc-1134","type":"reflect","persona":"any","source":"feeling targeted","hook":"Lensy: a fake almost fooled you once. How do you hold that?","prompt":"What's true for you?","options":["Everyone gets targeted","It's not about being smart","I just know the tell now"],"relearn":"Being targeted isn't a flaw; manipulation hits everyone, and noticing it is the growth.","affirm":"Being targeted isn't a flaw, manipulation hits everyone; noticing it is exactly the growth.","cat":"decode-the-influence"},
  {"id":"dc-1135","type":"reflect","persona":"any","source":"critical not cynical","hook":"Lensy: decoding doesn't mean trusting nothing. Where do you land?","prompt":"What sits right?","options":["I check, then I can trust","I stay curious, not cynical","I verify, then enjoy it"],"relearn":"Decoding is critical, not cynical; you can question a feed and still find real good in it.","affirm":"Critical and kind go together, you can question a feed and still find real good in it.","cat":"decode-the-influence"},
  {"id":"dc-1136","type":"reflect","persona":"any","source":"after being fooled","hook":"Lensy: you once shared a fake. What does the repair feel like?","prompt":"What's your move?","options":["Correct it openly","Learn the tell","Be gentle with myself"],"relearn":"Everyone gets fooled sometimes; correcting openly and learning the tell is the repair, no shame.","affirm":"Everyone gets fooled sometimes; correcting openly and learning the tell is the whole point, no shame.","cat":"decode-the-influence"},
  {"id":"dc-1137","type":"reflect","persona":"any","source":"your strongest tell","hook":"Lensy: of all the tells, which one do you catch fastest now?","prompt":"Which is yours?","options":["Manufactured urgency","'Too good to be true'","A source I can't trace"],"relearn":"Whichever tell you catch first is your edge; spotting one makes the next ones easier to see.","affirm":"Whichever tell you catch first is your edge; spotting one makes the next ones easier to see.","cat":"decode-the-influence"},
  {"id":"dc-1138","type":"reflect","persona":"any","source":"decoder identity","hook":"Lensy: knowing the whole toolkit now, who are you to the feed?","prompt":"How does it feel?","options":["A decoder, not a target","Harder to fool","Calmer about it all"],"relearn":"Knowing the techniques flips you from target to decoder; the feed works for you, not on you.","affirm":"Knowing the techniques flips you from target to decoder, the feed works for you, not on you.","cat":"decode-the-influence"},
  {"id":"dc-1170","cat":"decode-yourself","type":"branch","persona":"any","source":"intentional use","hook":"You sit down to study, then your hand reaches for the phone on reflex.","options":[{"text":"Leave the phone in the other room and start the first task","consequence":"The reflex fades and your focus comes back.","outcome":"intentional","best":true},{"text":"Keep it face-up beside you, just in case","consequence":"A face-up phone keeps pulling your eyes; move it away to use tech on purpose."}],"debrief":"Removing the trigger beats fighting the urge; that's using tech on purpose.","relearn":"Use tech on purpose: remove the trigger instead of relying on willpower."},
  {"id":"dc-1171","cat":"decode-yourself","type":"branch","persona":"any","source":"comparison","hook":"A classmate's holiday reel makes your own break feel small and boring.","options":[{"text":"Remind yourself you're seeing their edit, not their whole trip","consequence":"The sting eases; you stop measuring your life against a highlight.","outcome":"reframe","best":true},{"text":"Decide everyone's life is better than yours","consequence":"You're judging your full life against their curated reel; that's not a fair test."}],"debrief":"Feeds show edited highlights, not the ordinary or hard parts.","relearn":"A reel is a highlight, not a life; don't measure yourself against an edit."},
  {"id":"dc-1172","cat":"decode-yourself","type":"branch","persona":"any","source":"footprint","hook":"A group chat is roasting a teacher and someone says \"screenshot it for the meme.\"","options":[{"text":"Skip it; you don't want that resurfacing with your name on it","consequence":"You leave nothing of yours to be screenshotted back at you later.","outcome":"footprint","best":true},{"text":"Join in; it's just a private joke","consequence":"Private screenshots travel; a footprint can resurface, so post with future-you in mind."}],"debrief":"Your digital footprint lasts; a moment's post can outlive the moment.","relearn":"Post with future-you in mind; screenshots and footprints last."},
  {"id":"dc-1173","cat":"decode-yourself","type":"branch","persona":"any","source":"privacy / DPDP","hook":"A free quiz app wants your contacts, location and photos to \"work.\"","options":[{"text":"Deny what it doesn't need and use it anyway","consequence":"You keep the fun without handing over your whole phone.","outcome":"private","best":true},{"text":"Tap 'allow all' so it stops asking","consequence":"A quiz doesn't need your contacts; grant only the data truly needed."}],"debrief":"Most apps work fine with the minimum; share only what's necessary.","relearn":"Guard your privacy: grant only the permissions an app truly needs."},
  {"id":"dc-1174","cat":"decode-yourself","type":"branch","persona":"Counsellor","source":"digital wellbeing / help","hook":"You feel worse every night after an hour on the feed.","options":[{"text":"Swap the late scroll for a wind-down, and tell someone if the low stays","consequence":"Your mood steadies; you have a person to turn to if it doesn't.","outcome":"wellbeing","best":true},{"text":"Push through; you'll feel better eventually","consequence":"If the low stays, adjust use and reach for a trusted adult or Tele-MANAS 14416."}],"debrief":"If scrolling lowers your mood, change the habit and get help if it lasts.","relearn":"If a habit lowers your mood, adjust it and reach for support if it persists."},
  {"id":"dc-1175","cat":"decode-yourself","type":"branch","persona":"any","source":"FOMO","hook":"It's 1am; you're tired but afraid you'll miss something if you log off.","options":[{"text":"Log off and sleep; the feed will still be there tomorrow","consequence":"You wake rested and miss nothing that mattered.","outcome":"balance","best":true},{"text":"Stay up scrolling so you're not left out","consequence":"FOMO is an engineered feeling; logging off gives back rest, not loss."}],"debrief":"FOMO is manufactured; sleep and limits are a gain, not a miss.","relearn":"FOMO is engineered; choosing rest and limits is gaining, not missing out."},
  {"id":"dc-1176","cat":"decode-yourself","type":"branch","persona":"any","source":"intentional use","hook":"Autoplay just rolled you into a fourth video you never chose to watch.","options":[{"text":"Turn off autoplay so each video is a real choice","consequence":"The next video is yours to pick, not the app's to feed you.","outcome":"intentional","best":true},{"text":"Leave it on; it's easier","consequence":"Autoplay is attention-capture design; turning it off puts the choice back with you."}],"debrief":"Autoplay isn't an accident; switching it off reclaims your choice.","relearn":"Autoplay is capture design; turning it off makes each watch a real choice."},
  {"id":"dc-1177","cat":"decode-yourself","type":"branch","persona":"any","source":"comparison / body image","hook":"Fitness reels leave you picking apart your own body in the mirror.","options":[{"text":"Unfollow the accounts that make you feel worse","consequence":"Your feed stops feeding the comparison and your mood lifts.","outcome":"curate","best":true},{"text":"Keep watching to 'stay motivated'","consequence":"A feed that makes you pick yourself apart isn't motivation; curate who you follow."}],"debrief":"Curating your feed is a wellbeing habit, not vanity.","relearn":"Curate your feed: drop accounts that make you measure yourself harshly."},
  {"id":"dc-1178","cat":"decode-yourself","type":"branch","persona":"any","source":"footprint / privacy","hook":"You're about to post a photo that has your school gate and uniform in frame.","options":[{"text":"Crop out the location clues before posting","consequence":"You share the moment without broadcasting where to find you.","outcome":"private","best":true},{"text":"Post it as-is; nobody's looking that closely","consequence":"Location clues add up; crop them so your footprint stays on your terms."}],"debrief":"Small details build a map of you; guard what your posts reveal.","relearn":"Guard your privacy: strip location clues before you post."},
  {"id":"dc-1179","cat":"decode-yourself","type":"branch","persona":"any","source":"intentional use","hook":"You open an app to message one person and surface twenty minutes later.","options":[{"text":"Send the message first, then decide if you're staying","consequence":"You do what you came for and leave on your own terms.","outcome":"intentional","best":true},{"text":"Open the feed first 'for a second'","consequence":"The feed is built to hold you; do your task first to use tech on purpose."}],"debrief":"Going in with a purpose beats getting pulled into the loop.","relearn":"Open apps for a reason and leave when it's done; use tech on purpose."},
  {"id":"dc-1180","cat":"decode-yourself","type":"branch","persona":"Counsellor","source":"digital wellbeing / help","hook":"A friend says late-night scrolling is wrecking their sleep and mood.","options":[{"text":"Suggest a phone-out-of-room night and offer to check in","consequence":"They get a doable first step and know you're alongside them.","outcome":"support","best":true},{"text":"Tell them to just have more willpower","consequence":"A concrete step and support land better, plus Tele-MANAS 14416 if it persists."}],"debrief":"Help a friend with a small step and real support, not shame.","relearn":"Support beats 'willpower': offer a step and a route to help like Tele-MANAS 14416."},
  {"id":"dc-1181","cat":"decode-yourself","type":"branch","persona":"any","source":"comparison","hook":"Your post has fewer likes than a friend's and you feel small over it.","options":[{"text":"Remind yourself likes measure the algorithm, not your worth","consequence":"The number loses its grip on how you feel about yourself.","outcome":"reframe","best":true},{"text":"Delete the post; clearly it wasn't good enough","consequence":"Likes track reach the feed chose, not your value; don't let a count judge you."}],"debrief":"Like-counts reflect distribution and timing, not your worth.","relearn":"Likes measure reach, not your worth; don't hand a number the verdict."},
  {"id":"dc-1182","cat":"decode-yourself","type":"branch","persona":"any","source":"balance","hook":"You've decided screens are 'bad' and try to quit your phone cold turkey.","options":[{"text":"Aim for balance: keep what helps, cut what drains","consequence":"You keep real connection and learning while dropping the doomscroll.","outcome":"balance","best":true},{"text":"Go full no-phone and white-knuckle it","consequence":"Abstinence usually snaps back; balance keeps the good and guards the rest."}],"debrief":"The aim is balance, not abstinence; the digital world holds real good.","relearn":"Aim for balance, not quitting: use the good, guard against the rest."},
  {"id":"dc-1183","cat":"decode-yourself","type":"branch","persona":"any","source":"footprint","hook":"An old account still has posts the 13-year-old you would cringe at now.","options":[{"text":"Tidy or lock the old account so it reflects who you are now","consequence":"Your visible footprint matches the person you've grown into.","outcome":"footprint","best":true},{"text":"Forget it exists; it's ancient history","consequence":"Old posts can resurface; tidy or lock them so your footprint stays yours."}],"debrief":"You can shape your footprint by curating what's still public.","relearn":"Curate old posts; your footprint lasts but you can still tend it."},
  {"id":"dc-1184","cat":"decode-yourself","type":"branch","persona":"any","source":"intentional use","hook":"Your screen-time report says 5 hours yesterday and you feel a flash of shame.","options":[{"text":"Skip the shame; pick one app to cap and try it for a week","consequence":"You turn a number into one small, doable change.","outcome":"intentional","best":true},{"text":"Feel guilty and change nothing","consequence":"Shame doesn't help; one concrete limit does. The pull is by design, not a weakness."}],"debrief":"The number is information, not a verdict; act on it without shame.","relearn":"Use screen-time data to pick one change, not to shame yourself."},
  {"id":"dc-1185","cat":"decode-yourself","type":"branch","persona":"any","source":"privacy / DPDP","hook":"A site offers a discount if you log in with your main social account.","options":[{"text":"Use a guest checkout or separate email instead","consequence":"You get the deal without linking your whole identity to the shop.","outcome":"private","best":true},{"text":"Link your main account for the discount","consequence":"Linking shares more than you think; keep accounts separate to guard your data."}],"debrief":"Convenience often costs data; share the minimum to get what you want.","relearn":"Guard your data: avoid linking your main identity for small perks."},
  {"id":"dc-1186","cat":"decode-yourself","type":"branch","persona":"any","source":"digital wellbeing","hook":"Notifications buzz all through dinner with your family.","options":[{"text":"Set a 'do not disturb' for meals and be present","consequence":"Dinner becomes real time together, not a half-watched feed.","outcome":"intentional","best":true},{"text":"Glance at each buzz so you don't miss anything","consequence":"Each glance pulls you out; a meal-time DND protects the moment you're in."}],"debrief":"Designing your notifications protects the offline time that matters.","relearn":"Use 'do not disturb' on purpose so pings don't run your real life."},
  {"id":"dc-1187","cat":"decode-yourself","type":"branch","persona":"any","source":"comparison","hook":"A 'study-with-me' reel makes your messy desk feel like failure.","options":[{"text":"Take what's useful and ignore the aesthetic","consequence":"You borrow a good tip without buying the impossible-looking standard.","outcome":"reframe","best":true},{"text":"Decide you can't study until your desk looks like theirs","consequence":"The aesthetic is staged; learning doesn't need it, so don't let it block you."}],"debrief":"A polished setup is content; real studying happens in messy rooms too.","relearn":"Borrow the tip, skip the staged standard; it's an edit, not a requirement."},
  {"id":"dc-1188","cat":"decode-yourself","type":"branch","persona":"any","source":"intentional use","hook":"You realise the same three apps eat most of your day without you choosing them.","options":[{"text":"Move them off the home screen so opening one is a decision","consequence":"The reflex breaks and you open them on purpose, not by habit.","outcome":"intentional","best":true},{"text":"Keep them front and centre for convenience","consequence":"Easy access feeds the reflex; adding friction makes each open a choice."}],"debrief":"Small friction turns an automatic tap into an intentional one.","relearn":"Add friction to reflex apps so each open is a real choice."},
  {"id":"dc-1189","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"intentional use","hook":"\"If I had real self-control I wouldn't need any phone limits.\"","myth":{"un":"Needing limits means I lack self-control.","re":"Limits aren't a willpower failure; they remove triggers an app is engineered to exploit.","why":"The pull is by design, so design-awareness, not raw willpower, reclaims the choice."},"relearn":"Limits remove engineered triggers; that's design-awareness, not a lack of self-control."},
  {"id":"dc-1190","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"comparison","hook":"\"Everyone online seems happier and more sorted than me.\"","myth":{"un":"Everyone online is happier and more sorted than me.","re":"You're seeing curated highlights; their ordinary and hard days just aren't posted.","why":"Feeds are highlight reels that hide the dull and difficult parts everyone has."},"relearn":"Feeds show curated highlights; everyone's hard and ordinary days just aren't posted."},
  {"id":"dc-1191","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"footprint","hook":"\"It's a private story, so it disappears and doesn't count.\"","myth":{"un":"A private, disappearing post doesn't count.","re":"Anything posted can be screenshotted or saved, so it can outlast the moment.","why":"Your footprint lasts, so it's worth posting with future-you in mind."},"relearn":"'Disappearing' posts can be saved; your footprint lasts, so post with future-you in mind."},
  {"id":"dc-1192","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"privacy / DPDP","hook":"\"I've nothing to hide, so privacy settings don't matter to me.\"","myth":{"un":"With nothing to hide, privacy settings don't matter.","re":"Privacy isn't about hiding; it's about choosing who gets your data and when.","why":"Sharing only what's needed protects you whether or not you have 'something to hide'."},"relearn":"Privacy is choosing who gets your data, not hiding; share only what's needed."},
  {"id":"dc-1193","cat":"decode-yourself","type":"strike-rewrite","persona":"Counsellor","source":"digital wellbeing / help","hook":"\"Feeling low after scrolling just means I'm weak.\"","myth":{"un":"Feeling low after scrolling means I'm weak.","re":"Feeds are built to hook attention; a dip in mood is a signal to adjust, not a flaw in you.","why":"The pull is by design; if it persists, support like Tele-MANAS 14416 helps."},"relearn":"A low mood after scrolling is a signal to adjust, not a weakness; support helps if it persists."},
  {"id":"dc-1194","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"balance","hook":"\"To be healthy I should just quit social media completely.\"","myth":{"un":"Being healthy means quitting social media completely.","re":"The goal is balance: the digital world holds real friendship, learning and joy worth keeping.","why":"Use the good and guard against the rest beats all-or-nothing abstinence."},"relearn":"Health is balance, not quitting; keep the real connection, learning and joy."},
  {"id":"dc-1195","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"intentional use","hook":"\"Checking my phone first thing is just how mornings work now.\"","myth":{"un":"Checking my phone the instant I wake is just normal.","re":"It's a habit the app designed, not a law; you can choose what your morning starts with.","why":"Noticing the auto-reach is the first step to using tech on purpose."},"relearn":"The morning phone-grab is a designed habit, not a law; choose how your day starts."},
  {"id":"dc-1196","cat":"decode-yourself","type":"strike-rewrite","persona":"any","source":"comparison","hook":"\"If a post flops, it means people don't like the real me.\"","myth":{"un":"A post that flops means people dislike the real me.","re":"Reach is set by timing and the algorithm, not by your worth as a person.","why":"Likes measure distribution, so a low count is no verdict on you."},"relearn":"Reach is set by the algorithm and timing, not your worth; a flop isn't a verdict."},
  {"id":"dc-1197","cat":"decode-yourself","type":"sort","persona":"any","source":"intentional use","hook":"Sort: using tech on purpose, or being used by it?","items":[{"id":"a","text":"Opening an app, doing the task, leaving"},{"id":"b","text":"Reaching for the phone the second you're bored"},{"id":"c","text":"Setting a timer before you start scrolling"},{"id":"d","text":"Letting autoplay pick your next ten videos"},{"id":"e","text":"Muting notifications while you study"},{"id":"f","text":"Refreshing the feed for nothing in particular"}],"bins":[{"id":"onpurpose","label":"On purpose","valence":"pos"},{"id":"beingused","label":"Being used","valence":"neg"}],"key":{"a":"onpurpose","b":"beingused","c":"onpurpose","d":"beingused","e":"onpurpose","f":"beingused"},"relearn":"Choosing your use protects your attention; letting the app choose hands it over."},
  {"id":"dc-1198","cat":"decode-yourself","type":"sort","persona":"any","source":"comparison","hook":"Sort: a fair comparison, or the highlight-reel trap?","items":[{"id":"a","text":"Comparing today-you to last-month-you"},{"id":"b","text":"Comparing your Monday to a friend's holiday reel"},{"id":"c","text":"Noting your own progress on a goal"},{"id":"d","text":"Measuring your body against fitness influencers"},{"id":"e","text":"Asking a friend how they actually felt that day"},{"id":"f","text":"Judging your life by strangers' edited posts"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"trap","label":"Highlight trap","valence":"neg"}],"key":{"a":"fair","b":"trap","c":"fair","d":"trap","e":"fair","f":"trap"},"relearn":"Compare to your own past or ask real questions; don't measure against edited reels."},
  {"id":"dc-1199","cat":"decode-yourself","type":"sort","persona":"any","source":"privacy / DPDP","hook":"Sort: guards your privacy, or leaks it?","items":[{"id":"a","text":"Granting only the permissions an app needs"},{"id":"b","text":"Tapping 'allow all' to skip the prompts"},{"id":"c","text":"Using a separate email for sign-ups"},{"id":"d","text":"Posting your live location in real time"},{"id":"e","text":"Reviewing what an app can access"},{"id":"f","text":"Reusing one password everywhere"}],"bins":[{"id":"guards","label":"Guards it","valence":"pos"},{"id":"leaks","label":"Leaks it","valence":"neg"}],"key":{"a":"guards","b":"leaks","c":"guards","d":"leaks","e":"guards","f":"leaks"},"relearn":"Minimum permissions, separate emails and unique passwords guard you; the rest leaks."},
  {"id":"dc-1200","cat":"decode-yourself","type":"sort","persona":"any","source":"footprint","hook":"Sort: footprint-aware, or future-you's regret?","items":[{"id":"a","text":"Cropping a school badge out of a photo"},{"id":"b","text":"Posting a roast with someone's name attached"},{"id":"c","text":"Checking a caption before it goes public"},{"id":"d","text":"Sharing a screenshot of a private chat"},{"id":"e","text":"Locking an old cringe account"},{"id":"f","text":"Tagging a friend's exact location without asking"}],"bins":[{"id":"aware","label":"Footprint-aware","valence":"pos"},{"id":"regret","label":"Future regret","valence":"neg"}],"key":{"a":"aware","b":"regret","c":"aware","d":"regret","e":"aware","f":"regret"},"relearn":"Posting with future-you and others in mind protects a footprint that lasts."},
  {"id":"dc-1201","cat":"decode-yourself","type":"sort","persona":"any","source":"wellbeing","hook":"Sort: protects your wellbeing, or wears it down?","items":[{"id":"a","text":"Phone out of the bedroom at night"},{"id":"b","text":"Doomscrolling until 2am"},{"id":"c","text":"Taking real breaks from the screen"},{"id":"d","text":"Refreshing for bad news on repeat"},{"id":"e","text":"Unfollowing accounts that drain you"},{"id":"f","text":"Comparing yourself the moment you wake"}],"bins":[{"id":"protects","label":"Protects it","valence":"pos"},{"id":"wears","label":"Wears it down","valence":"neg"}],"key":{"a":"protects","b":"wears","c":"protects","d":"wears","e":"protects","f":"wears"},"relearn":"Sleep, breaks and curating your feed protect wellbeing; doomscrolling and comparison erode it."},
  {"id":"dc-1202","cat":"decode-yourself","type":"sort","persona":"any","source":"FOMO","hook":"Sort: an engineered pull, or a real reason to stay online?","items":[{"id":"a","text":"\"You'll miss out if you log off\""},{"id":"b","text":"A video call with a far-away cousin"},{"id":"c","text":"A streak counter guilt-tripping you"},{"id":"d","text":"Looking up something you need to learn"},{"id":"e","text":"A red badge designed to make you tap"},{"id":"f","text":"Messaging back a friend who's waiting"}],"bins":[{"id":"engineered","label":"Engineered pull","valence":"neg"},{"id":"real","label":"Real reason","valence":"pos"}],"key":{"a":"engineered","b":"real","c":"engineered","d":"real","e":"engineered","f":"real"},"relearn":"FOMO, streaks and badges are engineered hooks; connection and learning are real reasons."},
  {"id":"dc-1203","cat":"decode-yourself","type":"sort","persona":"any","source":"balance","hook":"Sort: the good of digital life to keep, or the drain to guard against?","items":[{"id":"a","text":"Learning a skill from a tutorial"},{"id":"b","text":"Endless comparison spirals"},{"id":"c","text":"Staying close to distant friends"},{"id":"d","text":"Mindless doomscrolling for hours"},{"id":"e","text":"Finding a community that gets you"},{"id":"f","text":"Chasing every notification all day"}],"bins":[{"id":"keep","label":"Keep","valence":"pos"},{"id":"guard","label":"Guard against","valence":"neg"}],"key":{"a":"keep","b":"guard","c":"keep","d":"guard","e":"keep","f":"guard"},"relearn":"Balance means keeping the connection and learning while guarding against the drain."},
  {"id":"dc-1204","cat":"decode-yourself","type":"sort","persona":"any","source":"intentional use","hook":"Sort: a design hook to notice, or your own intentional move?","items":[{"id":"a","text":"Infinite scroll with no end in sight"},{"id":"b","text":"Setting a daily limit on an app"},{"id":"c","text":"A red notification dot pulling your eye"},{"id":"d","text":"Turning off autoplay"},{"id":"e","text":"Auto-playing the next episode"},{"id":"f","text":"Greyscaling your screen to reduce the pull"}],"bins":[{"id":"hook","label":"Design hook","valence":"tell"},{"id":"yours","label":"Your move","valence":"pos"}],"key":{"a":"hook","b":"yours","c":"hook","d":"yours","e":"hook","f":"yours"},"relearn":"Infinite scroll, badges and autoplay are hooks; limits, greyscale and off-switches are your moves."},
  {"id":"dc-1205","cat":"decode-yourself","type":"reflect","persona":"any","source":"intentional use","hook":"Lensy: which one small habit would help you use tech more on purpose?","prompt":"Pick the one you'd try first.","options":["Phone out of reach while studying","Turn off non-essential pings","Open apps only with a reason"],"affirm":"Any of these puts you, not the app, back in charge of your attention. 🧩","relearn":"Small intentional habits put you, not the app, back in charge of your attention."},
  {"id":"dc-1206","cat":"decode-yourself","type":"reflect","persona":"any","source":"comparison","hook":"Lensy: when a feed makes you feel behind, what helps you most?","prompt":"There's no wrong answer here.","options":["Remembering it's a highlight reel","Logging off for a bit","Texting a real friend"],"affirm":"Whatever steadies you is a real skill; the comparison was engineered, not the truth. 🧩","relearn":"When a feed makes you feel behind, steady yourself; the comparison is engineered."},
  {"id":"dc-1207","cat":"decode-yourself","type":"reflect","persona":"any","source":"balance","hook":"Lensy: what does the good side of your digital life give you?","prompt":"Name one for yourself.","options":["Staying close to people","Learning new things","A community that gets me"],"affirm":"That good is real and worth keeping; balance means guarding it, not quitting it. 🧩","relearn":"The digital world holds real good; balance means keeping it, not quitting it."},
  {"id":"dc-1208","cat":"decode-yourself","type":"reflect","persona":"any","source":"footprint","hook":"Lensy: before you post, what's a quick check you could make your own?","prompt":"Choose what fits you.","options":["Would future-me be okay with this?","Does this reveal where I am?","Is this kind to whoever's in it?"],"affirm":"A two-second check keeps your footprint yours; that's decoding yourself. 🧩","relearn":"A quick check before posting keeps your footprint yours."},
  {"id":"dc-1209","cat":"decode-yourself","type":"reflect","persona":"any","source":"wellbeing","hook":"Lensy: how do you know when a scroll has stopped feeling good?","prompt":"Tune into your own signal.","options":["I feel more tense than relaxed","I've forgotten what I opened it for","I'm comparing myself to everyone"],"affirm":"Noticing your own signal is half of digital wisdom; it tells you when to step back. 🧩","relearn":"Noticing your own signal tells you when a scroll has stopped feeling good."},
  {"id":"dc-1210","cat":"decode-yourself","type":"reflect","persona":"any","source":"privacy / DPDP","hook":"Lensy: what would make guarding your privacy feel doable, not a chore?","prompt":"Pick your starting point.","options":["A yearly check of app permissions","Saying no to data I don't owe","A separate email for sign-ups"],"affirm":"Any small habit here keeps your data yours to give, not theirs to take. 🧩","relearn":"A small privacy habit keeps your data yours to give, not theirs to take."},
  {"id":"dc-1211","cat":"decode-yourself","type":"reflect","persona":"Counsellor","source":"digital wellbeing / help","hook":"Lensy: if a friend's mood kept dropping after scrolling, what would you do?","prompt":"There's no single right answer.","options":["Listen without judging","Suggest a small change together","Point them to support if it lasts"],"affirm":"All of these help; you don't have to fix it alone, and nor do they. Tele-MANAS 14416 is there. 🧩","relearn":"Helping a struggling friend means listening and support, not fixing it alone."},
  {"id":"dc-1212","cat":"decode-yourself","type":"reflect","persona":"any","source":"the journey","hook":"Lensy: you've learned to decode the feed and yourself. What will you carry?","prompt":"Pick what feels most yours.","options":["Pause before I share or scroll","Use tech on purpose","Be both critical and kind"],"affirm":"Carrying even one of these makes you the decoder, not the target, for life. 🧩","relearn":"Carrying one decode-yourself habit keeps you the decoder, not the target, for life."},
  {"id":"dc-1213","cat":"decode-yourself","type":"spot","persona":"any","source":"intentional use","hook":"Spot the two habits that mean the app is using you, not the other way round.","scene":[{"id":"a","text":"You open it for one reason and leave when done","trick":false},{"id":"b","text":"You reach for it the instant a queue forms","trick":true},{"id":"c","text":"You muted pings to focus on study","trick":false},{"id":"d","text":"You can't remember what you opened it for","trick":true},{"id":"e","text":"You set a timer before scrolling","trick":false}],"why":"Reflex-reaching and forgetting why you opened it are signs the design is steering you, not you.","relearn":"Reflex-grabbing and forgetting why you opened an app mean it's using you; use it on purpose."},
  {"id":"dc-1214","cat":"decode-yourself","type":"spot","persona":"any","source":"comparison","hook":"Spot the two thoughts that are the highlight-reel trap, not reality.","scene":[{"id":"a","text":"\"This is their edit, not their whole day\"","trick":false},{"id":"b","text":"\"Everyone's life is better than mine\"","trick":true},{"id":"c","text":"\"They post the wins, not the boring bits\"","trick":false},{"id":"d","text":"\"If I looked like them I'd be happy\"","trick":true},{"id":"e","text":"\"A like-count isn't a measure of me\"","trick":false}],"why":"\"Everyone's life is better\" and \"if I looked like them I'd be happy\" judge your real life against an edit.","relearn":"Judging your life or body against an edited feed is the highlight-reel trap, not reality."},
  {"id":"dc-1215","cat":"decode-yourself","type":"spot","persona":"any","source":"privacy / DPDP","hook":"Spot the two moves that quietly leak your private data.","scene":[{"id":"a","text":"Granting only the permissions an app needs","trick":false},{"id":"b","text":"Tapping 'allow all' to stop the prompts","trick":true},{"id":"c","text":"Using a separate email to sign up","trick":false},{"id":"d","text":"Posting your live location for everyone","trick":true},{"id":"e","text":"Checking what an app can access","trick":false}],"why":"'Allow all' and broadcasting your live location hand over far more than you meant to.","relearn":"'Allow all' and live-location posts leak your data; grant the minimum instead."},
  {"id":"dc-1216","cat":"decode-yourself","type":"spot","persona":"any","source":"footprint","hook":"Spot the two posts future-you might regret.","scene":[{"id":"a","text":"A photo with the location cropped out","trick":false},{"id":"b","text":"A screenshot of a private chat, names shown","trick":true},{"id":"c","text":"A caption you checked before going public","trick":false},{"id":"d","text":"A cruel meme with a classmate's face on it","trick":true},{"id":"e","text":"A throwaway joke kept just in the group","trick":false}],"why":"Posting a private chat and a cruel meme can resurface with your name attached; tread carefully.","relearn":"Private chats and cruel memes can resurface with your name on them; post with future-you in mind."},
  {"id":"dc-1217","cat":"decode-yourself","type":"spot","persona":"any","source":"wellbeing","hook":"Spot the two habits that wear your wellbeing down.","scene":[{"id":"a","text":"Phone out of the bedroom at night","trick":false},{"id":"b","text":"Doomscrolling bad news until you can't sleep","trick":true},{"id":"c","text":"Taking real breaks from the screen","trick":false},{"id":"d","text":"Comparing yourself the second you wake","trick":true},{"id":"e","text":"Unfollowing accounts that drain you","trick":false}],"why":"Doomscrolling till you can't sleep and waking to comparison both erode mood and rest.","relearn":"Late doomscrolling and waking to comparison erode mood and rest; sleep and breaks protect them."},
  {"id":"dc-1218","cat":"decode-yourself","type":"spot","persona":"any","source":"FOMO","hook":"Spot the two engineered hooks pulling you to stay online.","scene":[{"id":"a","text":"A video call with a cousin you miss","trick":false},{"id":"b","text":"A streak counter guilt-tripping you to open it","trick":true},{"id":"c","text":"Looking up something you actually need","trick":false},{"id":"d","text":"A red badge designed to make you tap","trick":true},{"id":"e","text":"Replying to a friend who's waiting","trick":false}],"why":"Streak counters and red badges are designed pulls, not real reasons to keep scrolling.","relearn":"Streak counters and badges are engineered hooks; real connection and need are different."},
  {"id":"dc-1219","cat":"decode-yourself","type":"spot","persona":"any","source":"balance","hook":"Spot the two that are the drain to guard against, not the good to keep.","scene":[{"id":"a","text":"Learning a skill from a tutorial","trick":false},{"id":"b","text":"Hours of mindless doomscrolling","trick":true},{"id":"c","text":"Staying close to distant friends","trick":false},{"id":"d","text":"Endless comparison spirals","trick":true},{"id":"e","text":"Finding a community that gets you","trick":false}],"why":"Doomscrolling and comparison spirals are the drain; the rest is the real good worth keeping.","relearn":"Doomscrolling and comparison are the drain to guard against; learning and connection are the good to keep."},
  {"id":"dc-1220","cat":"decode-yourself","type":"spot","persona":"any","source":"intentional use","hook":"Spot the two design hooks (not your own intentional moves) in this feed.","scene":[{"id":"a","text":"You set a daily limit on the app","trick":false},{"id":"b","text":"Infinite scroll with no stopping point","trick":true},{"id":"c","text":"You turned off autoplay","trick":false},{"id":"d","text":"A pull-to-refresh slot-machine animation","trick":true},{"id":"e","text":"You greyscaled the screen to dull the pull","trick":false}],"why":"Infinite scroll and the slot-machine refresh are capture design; limits and off-switches are your moves.","relearn":"Infinite scroll and slot-machine refresh are capture design; limits are your moves."},
  {"id":"dc-1221","cat":"decode-yourself","type":"role-play","persona":"Sneha","source":"comparison / support","hook":"A friend keeps saying everyone in their feed has a better life than them.","setup":"Help them reframe it. Say:","yourLine":[{"text":"\"You're seeing their highlights against your whole messy day; that's not a fair match.\"","best":true},{"text":"\"Honestly, yeah, their lives do look better.\""}],"relearn":"Help a friend see they're matching their whole day against someone's highlights."},
  {"id":"dc-1222","cat":"decode-yourself","type":"role-play","persona":"any","source":"intentional use","hook":"Your sibling says they 'can't' stop checking the phone every few minutes.","setup":"Offer a doable nudge. Say:","yourLine":[{"text":"\"Try leaving it in the other room for one task; the urge fades faster than you think.\"","best":true},{"text":"\"You just need more willpower, that's all.\""}],"relearn":"A doable nudge like 'leave it in the other room' beats telling someone to use willpower."},
  {"id":"dc-1223","cat":"decode-yourself","type":"role-play","persona":"Counsellor","source":"digital wellbeing / help","hook":"A friend admits the feed leaves them low most nights.","setup":"Respond with care, not a brush-off. Say:","yourLine":[{"text":"\"That's the design pulling at you, not a flaw. Want to try a phone-free hour, and talk to someone if it stays?\"","best":true},{"text":"\"Just stop scrolling then, simple.\""}],"relearn":"Meet a friend's low mood with care and a small step, plus support if it stays."},
  {"id":"dc-1224","cat":"decode-yourself","type":"role-play","persona":"any","source":"privacy / DPDP","hook":"A friend is about to tap 'allow all' on an app asking for everything.","setup":"Flag it before they tap. Say:","yourLine":[{"text":"\"Hold on, it doesn't need your contacts; just allow what the app actually uses.\"","best":true},{"text":"\"Eh, just allow it all so it stops nagging.\""}],"relearn":"Flag a friend before they 'allow all'; grant only what an app actually uses."},
  {"id":"dc-1225","cat":"decode-yourself","type":"role-play","persona":"any","source":"footprint","hook":"A friend wants to post a screenshot of a private group chat 'for laughs.'","setup":"Talk them out of it. Say:","yourLine":[{"text":"\"That can resurface with everyone's names on it; let's keep it in the group.\"","best":true},{"text":"\"Go on, it's funny, nobody'll mind.\""}],"relearn":"A posted private chat can resurface with names; keep it in the group."},
  {"id":"dc-1226","cat":"decode-yourself","type":"role-play","persona":"any","source":"balance","hook":"A friend declares they're deleting every app forever to 'fix' themselves.","setup":"Offer balance instead of abstinence. Say:","yourLine":[{"text":"\"Maybe keep the ones that help and cut the doomscroll, rather than all-or-nothing?\"","best":true},{"text":"\"Yeah, just nuke everything, screens are evil.\""}],"relearn":"Offer balance over all-or-nothing: keep what helps, cut the doomscroll."},
  {"id":"dc-1227","cat":"decode-yourself","type":"role-play","persona":"any","source":"FOMO","hook":"At midnight a friend says they can't sleep because they might miss a post.","setup":"Name the engineered feeling. Say:","yourLine":[{"text":"\"That 'might miss out' feeling is built to keep you scrolling; it'll still be there tomorrow.\"","best":true},{"text":"\"Same, better stay up just in case.\""}],"relearn":"Name FOMO as the engineered feeling it is; the feed will still be there tomorrow."},
  {"id":"dc-1228","cat":"decode-yourself","type":"match","persona":"any","source":"intentional use","hook":"Match each design hook to the intentional move that answers it.","pairs":[{"left":"Infinite scroll","right":"Set a daily time limit"},{"left":"Autoplay next video","right":"Turn autoplay off"},{"left":"Buzzing notifications","right":"Mute non-essential pings"},{"left":"Bright pull-you-in colours","right":"Switch to greyscale"},{"left":"App on the home screen","right":"Move it into a folder"}],"relearn":"Every design hook has an intentional move that puts the choice back with you."},
  {"id":"dc-1229","cat":"decode-yourself","type":"match","persona":"any","source":"comparison","hook":"Match the comparison thought to the reframe that frees you.","pairs":[{"left":"\"Their life is better\"","right":"\"I'm seeing their edit\""},{"left":"\"My post flopped\"","right":"\"Reach isn't my worth\""},{"left":"\"I should look like them\"","right":"\"Real bodies vary\""},{"left":"\"Everyone's sorted but me\"","right":"\"Hard days don't get posted\""},{"left":"\"I'm falling behind\"","right":"\"Compare me to past-me\""}],"relearn":"Each comparison thought has a reframe that frees you from measuring against an edit."},
  {"id":"dc-1230","cat":"decode-yourself","type":"match","persona":"any","source":"wellbeing","hook":"Match each habit to whether it protects or erodes your wellbeing.","pairs":[{"left":"Phone out of bedroom","right":"Protects sleep"},{"left":"Late-night doomscroll","right":"Erodes rest"},{"left":"Curating who you follow","right":"Protects mood"},{"left":"Chasing every ping","right":"Erodes focus"},{"left":"Real screen breaks","right":"Protects attention"}],"relearn":"Sleep, curating and breaks protect wellbeing; chasing pings and doomscrolling erode it."},
  {"id":"dc-1231","cat":"decode-yourself","type":"match","persona":"any","source":"privacy / DPDP","hook":"Match each privacy move to what it protects.","pairs":[{"left":"Minimum app permissions","right":"Your data"},{"left":"Cropping location clues","right":"Your whereabouts"},{"left":"Separate sign-up email","right":"Your main identity"},{"left":"Unique passwords","right":"Your accounts"},{"left":"Reviewing app access","right":"Your control"}],"relearn":"Each privacy move protects something: your data, whereabouts, identity, accounts and control."},
  {"id":"dc-1232","cat":"decode-yourself","type":"match","persona":"any","source":"footprint","hook":"Match each post choice to its footprint outcome.","pairs":[{"left":"Crop the school badge","right":"Stays hard to locate"},{"left":"Post a private chat","right":"Can resurface with names"},{"left":"Check before going public","right":"Future-you stays glad"},{"left":"Tag a live location","right":"Maps you for strangers"},{"left":"Lock an old account","right":"Old cringe stays private"}],"relearn":"Each post choice shapes your footprint; check before sharing so future-you stays glad."},
  {"id":"dc-1233","cat":"decode-yourself","type":"match","persona":"any","source":"FOMO","hook":"Match each online pull to what it really is.","pairs":[{"left":"Streak counter guilt","right":"A pressure tactic"},{"left":"Call with a distant cousin","right":"Real connection"},{"left":"Red badge on the icon","right":"An attention grab"},{"left":"Looking up homework help","right":"A real need"},{"left":"\"You might miss out\"","right":"An engineered feeling"}],"relearn":"Streaks, badges and FOMO are engineered pulls; connection and need are real reasons."},
  {"id":"dc-1234","cat":"decode-yourself","type":"match","persona":"any","source":"balance","hook":"Match each part of digital life to what it gives or costs you.","pairs":[{"left":"Learning a skill","right":"Builds you up"},{"left":"Comparison spirals","right":"Wear you down"},{"left":"Distant friendships","right":"Keep you close"},{"left":"Mindless doomscroll","right":"Eats your time"},{"left":"A community that gets you","right":"Helps you belong"}],"relearn":"Balance means keeping what builds you up and guarding against what wears you down."},
  {"id":"dc-1235","cat":"decode-yourself","type":"match","persona":"any","source":"the journey","hook":"Match each decode-yourself idea to what it puts you back in charge of.","pairs":[{"left":"Use tech on purpose","right":"Your attention"},{"left":"Resist the highlight reel","right":"Your self-image"},{"left":"Guard your privacy","right":"Your data"},{"left":"Mind your footprint","right":"Your future"},{"left":"Tend your mood","right":"Your wellbeing"}],"relearn":"Each decode-yourself habit puts you back in charge of one part of your digital life."},
  {"id":"dc-1260","cat":"grow-the-journey","type":"reflect","persona":"any","source":"unlearn relearn grow","hook":"Lensy: three little words carried this whole journey. Unlearn. Relearn. Grow. Which one feels most yours?","prompt":"What do you think?","options":["Unlearn","Relearn","Grow"],"affirm":"All three are yours now: drop the myth, take the truth, keep going. That's the signature you carry for life.","relearn":"Unlearn, Relearn, Grow: drop the myth, take the truth, keep going."},
  {"id":"dc-1261","cat":"grow-the-journey","type":"reflect","persona":"any","source":"lifelong learning","hook":"Lensy: the feeds will change, the tricks will change. The habit of reading them won't. Does that feel freeing?","prompt":"What do you think?","options":["Yes","A bit","I'll keep reading"],"affirm":"Learning never stops, and that's a good thing. A changing world just means you keep growing too.","relearn":"Learning never stops, and that's a good thing."},
  {"id":"dc-1262","cat":"grow-the-journey","type":"reflect","persona":"any","source":"critical and kind","hook":"Lensy: you've learned to be critical. The other half is staying kind. Can you hold both?","prompt":"What do you think?","options":["Yes","Both matter","I'll try"],"affirm":"Critical and kind, together. You can question the world clearly and still be gentle with the people in it.","relearn":"Be both critical and kind online; both matter."},
  {"id":"dc-1263","cat":"grow-the-journey","type":"reflect","persona":"any","source":"digital charter","hook":"Lensy: if you wrote one rule for your future digital life, what would it protect?","prompt":"What do you think?","options":["My attention","My calm","The people I talk to"],"affirm":"Whatever you'd protect, that's the start of your own charter. Use it on purpose, check before sharing, be kind.","relearn":"Write a digital-life charter: use it on purpose, check before sharing, be kind."},
  {"id":"dc-1264","cat":"grow-the-journey","type":"reflect","persona":"any","source":"the good in digital life","hook":"Lensy: this wasn't about fearing the internet. It's a place of real connection too. What's the good you'd keep?","prompt":"What do you think?","options":["Friends far away","Learning anything","Making things"],"affirm":"The aim was always balance, not abstinence. Keep the real connection, the learning, the joy; guard against the rest.","relearn":"The aim is balance: keep the real connection and joy, guard against the rest."},
  {"id":"dc-1266","cat":"grow-the-journey","type":"reflect","persona":"any","source":"the pause","hook":"Lensy: the smallest skill you take with you is a pause before you react. Tiny, but mighty. Agree?","prompt":"What do you think?","options":["Yes","A short pause","It works"],"affirm":"A short pause beats reacting in a hurry. That tiny gap is where decoding happens, for the rest of your life.","relearn":"Build in a short pause; decoding beats reacting in a hurry."},
  {"id":"dc-1267","cat":"grow-the-journey","type":"reflect","persona":"any","source":"growth across the journey","hook":"Lensy: you started this whole journey naming feelings as a small kid. Now you decode a whole world. Feel that?","prompt":"What do you think?","options":["Yes","I've grown","A long way"],"affirm":"From naming feelings to decoding the world, that's real growth across the whole journey. It was always you doing it.","relearn":"You've grown from naming feelings to decoding the world; that's real growth."},
  {"id":"dc-1268","cat":"grow-the-journey","type":"reflect","persona":"any","source":"handover","hook":"Lensy: I've walked beside you the whole way. From here, you've got this on your own. Ready?","prompt":"What do you think?","options":["Ready","I've got this","On my own"],"affirm":"You carry the power to unlearn and relearn yourself now, for life. You never needed me, just a little company.","relearn":"You carry the power to unlearn and relearn yourself, for life."},
  {"id":"dc-1269","cat":"grow-the-journey","type":"reflect","persona":"any","source":"pressure-free close","hook":"Lensy: there's no test at the end of this. Just you, a little wiser, walking on. How does that sit?","prompt":"What do you think?","options":["Good","Light","No pressure"],"affirm":"The close is warm and pressure-free, a send-off, never a test. You take what you take, and that's enough.","relearn":"The close is warm and pressure-free; a send-off, never a test."},
  {"id":"dc-1270","cat":"grow-the-journey","type":"reflect","persona":"any","source":"stay kind not believe-spread","hook":"Lensy: a wise digital citizen decodes, uses tech on purpose, and stays kind. Sound like someone you could be?","prompt":"What do you think?","options":["Yes","That's me now","I'll be that"],"affirm":"That's exactly who you've grown into: decode, use it on purpose, stay kind, not believe-and-spread.","relearn":"A wise digital citizen decodes, uses tech on purpose, and stays kind."},
  {"id":"dc-1271","cat":"grow-the-journey","type":"reflect","persona":"any","source":"finale","hook":"Lensy: the journey's done, but the habit isn't. What carries on from here?","prompt":"Say it for yourself.","options":["I keep questioning","I keep reading the feed","I keep it kind"],"affirm":"The chapters end; the habit doesn't. You carry the Decoder out into the real feed now.","relearn":"The journey ends but the decoding habit carries on for life."},
  {"id":"dc-1272","cat":"grow-the-journey","type":"reflect","persona":"any","source":"teaching others","hook":"Lensy: you can pass this on now, a friend, a younger cousin. Would you teach someone to decode?","prompt":"What do you think?","options":["Yes","Gladly","Already do"],"affirm":"Sharing the habit spreads it. Teaching someone to read the feed is one of the kindest things you can do.","relearn":"You can pass the decoding habit on; sharing it is its own kind of kindness."},
  {"id":"dc-1273","cat":"grow-the-journey","type":"reflect","persona":"any","source":"not cynical","hook":"Lensy: questioning everything could tip into cynicism. We chose a different word. Which one?","prompt":"What do you think?","options":["Critical","Curious","Clear-eyed"],"affirm":"Critical, not cynical. You read the world clearly without deciding it's all rotten. That's the harder, better path.","relearn":"Critical, not cynical: read the world clearly without giving up on it."},
  {"id":"dc-1274","cat":"grow-the-journey","type":"reflect","persona":"any","source":"the decoder for life","hook":"Lensy: who made this, how did the algorithm serve it, what's the trick, what's true, how will I act. Yours now?","prompt":"What do you think?","options":["Yes","I know the steps","For life"],"affirm":"That's the master habit, one you carry for life, applicable to any feed, claim, habit or choice you'll ever meet.","relearn":"The Decoder is one habit you carry for life, applicable to anything."},
  {"id":"dc-1276","cat":"grow-the-journey","type":"reflect","persona":"any","source":"footprint","hook":"Lensy: what you post outlives the moment. Knowing that, would you change anything about how you'll share?","prompt":"What do you think?","options":["Yes","Post with care","Think first"],"affirm":"Your digital footprint lasts; posting with future-you in mind is wisdom, not fear. You get to choose what you leave.","relearn":"Your digital footprint lasts; post with future-you in mind."},
  {"id":"dc-1277","cat":"grow-the-journey","type":"reflect","persona":"any","source":"readiness","hook":"Lensy: next time a feed tries to use you, what's your honest first move?","prompt":"Be real with yourself.","options":["I'll slow down","I'll question it","I'll check before I share"],"affirm":"Slowing down, questioning, checking first, that's a decoder's reflex, and it's now yours.","relearn":"Your first move on a manipulative feed is to slow down and question it."},
  {"id":"dc-1278","cat":"grow-the-journey","type":"reflect","persona":"any","source":"both halves","hook":"Lensy: you decoded the world out there, and you decoded yourself in here. Which felt harder?","prompt":"What do you think?","options":["The world","Myself","Both"],"affirm":"Decoding yourself matters as much as decoding the world. You did both, and both make you whole online.","relearn":"Decoding yourself matters as much as decoding the world."},
  {"id":"dc-1279","cat":"grow-the-journey","type":"reflect","persona":"any","source":"generation vision","hook":"Lensy: who's one person you'd pass these decoding skills on to?","prompt":"Picture them.","options":["A younger sibling","A friend who shares too fast","Anyone who'll listen"],"affirm":"Teaching even one person to read the feed clearly is how a kinder, sharper generation spreads.","relearn":"Passing on the decoding habit is how a clear-eyed, kind generation grows."},
  {"id":"dc-1280","cat":"grow-the-journey","type":"reflect","persona":"any","source":"mistakes are repair","hook":"Lensy: you'll still get fooled sometimes, everyone does. What matters more, never slipping or knowing how to repair?","prompt":"What do you think?","options":["Repair","Learn the tell","Own it"],"affirm":"If you spread something false, correct it openly and learn the tell. No shame, just repair. That's the grown-up move.","relearn":"If you slip, correct it openly and learn the tell; no shame, just repair."},
  {"id":"dc-1281","cat":"grow-the-journey","type":"reflect","persona":"any","source":"on purpose","hook":"Lensy: 'use it on purpose' was a thread through the whole thing. What's one thing you'll do on purpose now?","prompt":"What do you think?","options":["Turn off pings","Curate my feed","Take breaks"],"affirm":"Using tech on purpose, choosing instead of drifting, is the quiet superpower. You leave with it in hand.","relearn":"Use tech on purpose: choose your use rather than drifting."},
  {"id":"dc-1282","cat":"grow-the-journey","type":"reflect","persona":"any","source":"distress is not your fault","hook":"Lensy: if the feed ever pulls you low, remember the pull is by design. Does knowing that take some weight off?","prompt":"What do you think?","options":["Yes","It helps","Not my fault"],"affirm":"The pull is by design, not a weakness. If scrolling lowers your mood, adjust use and reach for support if it lasts.","relearn":"The pull is by design, not a weakness; adjust use and reach for support if low mood persists."},
  {"id":"dc-1283","cat":"grow-the-journey","type":"reflect","persona":"any","source":"trending not true","hook":"Lensy: 'trending' will follow you the rest of your life. What will you remember it actually measures?","prompt":"What do you think?","options":["Spread","Not truth","Engagement"],"affirm":"Trending measures spread, often engineered, not accuracy. You'll carry that quiet correction for good.","relearn":"Trending measures spread, not truth."},
  {"id":"dc-1284","cat":"grow-the-journey","type":"reflect","persona":"any","source":"verify the source","hook":"Lensy: 'looks real' stopped being proof somewhere in this journey. What replaced it as your real check?","prompt":"What do you think?","options":["The source","Verify it","Don't trust the eye"],"affirm":"Verifying the source, not trusting your eye, is the durable skill. It's the one defence the deepfake arms race can't beat.","relearn":"Verify the source; don't trust your eye."},
  {"id":"dc-1285","cat":"grow-the-journey","type":"reflect","persona":"any","source":"breaks protect you","hook":"Lensy: stepping away from the screen isn't quitting. It's tending yourself. What does a good break look like for you?","prompt":"What do you think?","options":["Sleep","Outside","Real talk"],"affirm":"Breaks, sleep and curating your feed protect wellbeing. Stepping back is care, not failure. Take it whenever you need.","relearn":"Breaks, sleep and curating your feed protect wellbeing."},
  {"id":"dc-1286","cat":"grow-the-journey","type":"reflect","persona":"any","source":"FOMO is engineered","hook":"Lensy: that itch that you're missing out? We learned where it comes from. Does naming it loosen its grip?","prompt":"What do you think?","options":["Yes","A little","It's engineered"],"affirm":"FOMO is itself an engineered feeling. Intentional limits give back time and calm, you gain, not miss out.","relearn":"FOMO is an engineered feeling; intentional limits give back time and calm."},
  {"id":"dc-1287","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"lifelong skill","hook":"\"I've finished the game, so I'm done learning to decode.\"","myth":{"un":"Finishing the game means you're done learning to decode.","re":"Decoding is a lifelong habit; the tricks keep evolving, so you keep reading.","why":"The information world never stops changing, so the skill stays useful for life."},"relearn":"Decoding is lifelong; the tricks evolve, so you keep reading."},
  {"id":"dc-1288","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"critical not cynical","hook":"\"To stay safe online, you should just distrust everything and everyone.\"","myth":{"un":"Staying safe online means distrusting everything and everyone.","re":"Be critical, not cynical: question what you read while staying kind and open to the good.","why":"Cynicism shuts you off from real connection; healthy scepticism keeps you both safe and human."},"relearn":"Be critical, not cynical: question clearly while staying kind."},
  {"id":"dc-1289","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"balance not abstinence","hook":"\"The only truly wise choice is to quit screens completely.\"","myth":{"un":"The only wise choice is to quit screens completely.","re":"The aim is balance, not abstinence: use the good, guard against the rest.","why":"The digital world holds real connection and learning; throwing it all away loses the good with the bad."},"relearn":"The aim is balance, not abstinence: use the good, guard against the rest."},
  {"id":"dc-1290","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"kindness matters","hook":"\"Once you can decode the world, being kind online doesn't really matter anymore.\"","myth":{"un":"Once you can decode the world, being kind online stops mattering.","re":"A wise digital citizen is both critical and kind; both matter, always.","why":"Smart without kind just makes a sharper way to hurt people; the goal is clear-eyed and gentle."},"relearn":"A wise digital citizen is both critical and kind; both matter."},
  {"id":"dc-1291","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"one slip","hook":"\"If you ever get fooled by a fake, it means all this decoding was useless.\"","myth":{"un":"Getting fooled once means the decoding was useless.","re":"Everyone slips sometimes; correct it openly, learn the tell, and keep going.","why":"The skill isn't never being fooled, it's catching it, repairing it, and growing from it."},"relearn":"Everyone slips; correct it openly, learn the tell, keep going."},
  {"id":"dc-1292","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"charter is real","hook":"\"Writing down your own digital rules is pointless; nobody actually sticks to them.\"","myth":{"un":"Writing your own digital rules is pointless; nobody sticks to them.","re":"A digital-life charter turns what you've learned into how you'll actually live online.","why":"Naming a few real principles makes them easier to keep than vague good intentions."},"relearn":"A digital-life charter turns what you learned into how you live online."},
  {"id":"dc-1293","cat":"grow-the-journey","type":"strike-rewrite","persona":"any","source":"growth is real","hook":"\"You're basically the same person you were before all this; nothing really changed.\"","myth":{"un":"You're the same person as before; nothing really changed.","re":"You've grown from naming feelings to decoding the world; that's real growth.","why":"Learning to read the machine, the message and yourself genuinely changes how you meet the world."},"relearn":"You've grown from naming feelings to decoding the world; that's real growth."},
  {"id":"dc-1294","cat":"grow-the-journey","type":"match","persona":"any","source":"core principle","hook":"Match each Decoder move to the moment you'd use it.","pairs":[{"left":"Pause","right":"A post spikes your anger"},{"left":"Check the source","right":"A clip looks too perfect"},{"left":"Ask 'why me?'","right":"An ad knows you too well"},{"left":"Verify","right":"A 'fact' is going viral"},{"left":"Stay kind","right":"Someone you know got fooled"}],"relearn":"Each Decoder move fits a moment: pause, check, ask, verify, stay kind."},
  {"id":"dc-1295","cat":"grow-the-journey","type":"match","persona":"any","source":"mottos and what they protect","hook":"Match each Decoded motto to what it protects.","pairs":[{"left":"Read the machine","right":"Your clear view of the world"},{"left":"Decode anything","right":"You, from being fooled"},{"left":"Use it on purpose","right":"Your attention and time"},{"left":"Verify the source","right":"You, from convincing fakes"},{"left":"Take breaks","right":"Your sleep and your calm"}],"relearn":"Read the machine, decode anything, use it on purpose, verify, and rest."},
  {"id":"dc-1296","cat":"grow-the-journey","type":"match","persona":"any","source":"module to power","hook":"Match each part of the journey to the power it gave you.","pairs":[{"left":"The algorithm","right":"Seeing why you see what you see"},{"left":"The influence","right":"Naming the manipulation's tell"},{"left":"Yourself","right":"Guarding your attention and mood"},{"left":"The Decoder","right":"One habit for any claim"},{"left":"The journey","right":"Growing, for life"}],"relearn":"Each module gave you a power; together they're the decoder you carry for life."},
  {"id":"dc-1297","cat":"grow-the-journey","type":"match","persona":"any","source":"feeling to skill","hook":"Match the start of your journey to where it grew.","pairs":[{"left":"Naming a feeling","right":"Reading the whole world"},{"left":"A small kid","right":"A near-adult decoder"},{"left":"Asking a grown-up","right":"Verifying for yourself"},{"left":"One safe friend","right":"A digital-life charter"},{"left":"First lessons","right":"A habit for life"}],"relearn":"You grew from naming feelings to decoding the world; the skill is yours now."},
  {"id":"dc-1298","cat":"grow-the-journey","type":"match","persona":"any","source":"charter lines","hook":"Match each charter promise to the moment it helps.","pairs":[{"left":"Check before sharing","right":"A shocking clip lands in your chat"},{"left":"Use it on purpose","right":"You open an app out of habit"},{"left":"Be kind","right":"A pile-on starts in the comments"},{"left":"Take a pause","right":"Outrage makes you want to react fast"},{"left":"Verify the source","right":"A video looks too real to doubt"}],"relearn":"A charter is promises matched to the real moments they'll meet."},
  {"id":"dc-1299","cat":"grow-the-journey","type":"match","persona":"any","source":"unlearned to relearned","hook":"Match each myth you unlearned to the truth you relearned.","pairs":[{"left":"Trending is true","right":"Trending measures spread, not truth"},{"left":"Looks real, so it's real","right":"Verify the source, not the look"},{"left":"I'm too smart to be fooled","right":"Everyone is targeted"},{"left":"More screens, more fun","right":"Balance beats endless scrolling"},{"left":"Decoding ends at school","right":"It's a habit for life"}],"relearn":"For every myth you dropped, you took in a truth; that's the whole journey."},
  {"id":"dc-1300","cat":"grow-the-journey","type":"match","persona":"any","source":"decoder steps","hook":"Match each Decoder step to the question it asks.","pairs":[{"left":"Source","right":"Who made this, and why?"},{"left":"Algorithm","right":"How did the feed serve it to me?"},{"left":"Manipulation","right":"What trick is in play here?"},{"left":"Truth","right":"What is actually true?"},{"left":"Action","right":"How will I respond?"}],"relearn":"The Decoder runs five questions, in order, on anything you meet."},
  {"id":"dc-1301","cat":"grow-the-journey","type":"match","persona":"any","source":"wise vs not","hook":"Match each move to the wiser version of it.","pairs":[{"left":"Believe and spread","right":"Check, then decide"},{"left":"Doomscroll for hours","right":"Use it on purpose, then stop"},{"left":"Pile on in comments","right":"Disagree without tearing down"},{"left":"Trust the look","right":"Verify the source"},{"left":"Quit screens entirely","right":"Find your balance"}],"relearn":"For every reflex, there's a wiser move; you've learned them all."},
  {"id":"dc-1302","cat":"grow-the-journey","type":"branch","persona":"Arjun","source":"forward into adulthood","hook":"You step into adulthood and the information world is yours to navigate. What do you carry?","options":[{"text":"Carry the Decoder and your charter, and keep learning","consequence":"You meet the world clear-eyed and still growing.","outcome":"ready","best":true},{"text":"Leave the skills behind now the game's over","consequence":"The tricks evolve, so carry the Decoder forward; it stays useful for life."}],"debrief":"What you carry forward, the Decoder and the charter, is the whole point.","relearn":"Carry the Decoder and your charter into adult life, and keep learning."},
  {"id":"dc-1303","cat":"grow-the-journey","type":"branch","persona":"any","source":"writing the charter","hook":"You're writing your own digital-life charter to carry forward. How do you start?","options":[{"text":"Name a few real principles: use it on purpose, check before sharing, be kind","consequence":"You leave with a charter you'll actually live by.","outcome":"charter","best":true},{"text":"Leave it blank; you'll just wing it","consequence":"A few principles you commit to beat winging it; write them so they stick."}],"debrief":"A charter turns what you learned into how you'll live online.","relearn":"Write a digital-life charter: use it on purpose, check before sharing, be kind."},
  {"id":"dc-1304","cat":"grow-the-journey","type":"branch","persona":"any","source":"passing it on","hook":"Your younger cousin just got their first phone and is already deep in the feed. What do you do?","options":[{"text":"Sit with them and show one decoding trick you learned","consequence":"You pass the habit on; now two of you read the feed.","outcome":"teach","best":true},{"text":"Decide it's not your problem and scroll on","consequence":"Showing them one trick is a real gift; the habit spreads when you share it."}],"debrief":"Sharing the decoding habit is one of the kindest things you can do with it.","relearn":"You can pass the decoding habit on; sharing it spreads the skill."},
  {"id":"dc-1305","cat":"grow-the-journey","type":"branch","persona":"any","source":"feeling low from the feed","hook":"After long scrolls you feel flat and down on yourself. What's the wise move?","options":[{"text":"Adjust your use, curate the feed, talk to someone if it lasts","consequence":"You tend your mood and reach support; the low is by design.","outcome":"care","best":true},{"text":"Push through and keep scrolling; it'll pass","consequence":"If scrolling lowers your mood, adjust use and reach for support if it lasts."}],"debrief":"Tending your mental health is part of a healthy digital life.","relearn":"If scrolling lowers your mood, adjust use and reach for support if it persists."},
  {"id":"dc-1306","cat":"grow-the-journey","type":"branch","persona":"any","source":"a fake you shared","hook":"Weeks from now you realise a clip you reshared was a deepfake. What do you do?","options":[{"text":"Post a correction openly and note the tell you missed","consequence":"You repair the harm and learn the tell; no shame, just growth.","outcome":"repair","best":true},{"text":"Quietly delete it and hope nobody noticed","consequence":"Correcting openly repairs more than deleting; owning it is the grown-up move."}],"debrief":"If you spread something false, correct it openly and learn the tell.","relearn":"If you spread something false, correct it openly and learn the tell."},
  {"id":"dc-1307","cat":"grow-the-journey","type":"branch","persona":"Counsellor","source":"a friend who can't switch off","hook":"A friend says the feed runs their whole day and they can't stop. What do you offer?","options":[{"text":"Listen without judging and point them to support","consequence":"They feel less alone and learn the pull is by design, not weakness.","outcome":"support","best":true},{"text":"Tell them to just have more willpower","consequence":"Stopping is design-awareness, not willpower; listening beats blame."}],"debrief":"The pull is by design; warmth and support beat 'just try harder'.","relearn":"Stopping is design-awareness, not willpower; offer warmth and real support."},
  {"id":"dc-1308","cat":"grow-the-journey","type":"branch","persona":"any","source":"the next new thing","hook":"A brand-new app everyone's joining works in ways you've never seen. How do you meet it?","options":[{"text":"Run the Decoder: who made it, how does it want my attention, what's true","consequence":"You read the new thing like the old; the habit transfers.","outcome":"transfer","best":true},{"text":"Assume your old skills won't apply; dive in","consequence":"The Decoder applies to anything; a new app is when it pays off."}],"debrief":"Decode anything is one habit for life, even for the not-yet-invented.","relearn":"Decode anything: the habit applies to any new feed or app, for life."},
  {"id":"dc-1309","cat":"grow-the-journey","type":"branch","persona":"any","source":"critical and kind in comments","hook":"You disagree with a stranger's post, and the comments are turning into a pile-on. What now?","options":[{"text":"Make your point clearly without joining the pile-on","consequence":"You stay critical and kind; you disagree without tearing someone down.","outcome":"kind","best":true},{"text":"Pile on; they had it coming","consequence":"Being right doesn't need cruelty; disagree without tearing someone down."}],"debrief":"Critical and kind, together: question the idea, don't crush the person.","relearn":"Be both critical and kind; disagree without tearing someone down."},
  {"id":"dc-1310","cat":"grow-the-journey","type":"role-play","persona":"any","source":"kindness","hook":"A friend is harshly piling onto someone in the comments, and tagging you in.","setup":"Be the critical-and-kind voice. Say:","yourLine":[{"text":"\"Let's not pile on; we can disagree without tearing someone down.\"","best":true},{"text":"\"Yeah, go off, they deserve it.\""}],"relearn":"Be both critical and kind online; both matter."},
  {"id":"dc-1311","cat":"grow-the-journey","type":"role-play","persona":"any","source":"teaching a younger sibling","hook":"Your younger sibling forwards you a shocking 'breaking news' clip, thrilled, asking if it's real.","setup":"Pass on the habit. Say:","yourLine":[{"text":"\"Cool find, let's check the source together before we believe or forward it.\"","best":true},{"text":"\"If it's that dramatic it's probably true, just send it on.\""}],"relearn":"Verify before you forward; teaching the habit passes it on."},
  {"id":"dc-1312","cat":"grow-the-journey","type":"role-play","persona":"any","source":"naming your charter","hook":"A friend asks why you suddenly turned off most of your notifications.","setup":"Own your charter out loud. Say:","yourLine":[{"text":"\"I decided to use my phone on purpose instead of letting it ping me around.\"","best":true},{"text":"\"No reason, I'll probably turn them back on.\""}],"relearn":"Use tech on purpose; naming your charter makes it real."},
  {"id":"dc-1313","cat":"grow-the-journey","type":"role-play","persona":"any","source":"defending balance","hook":"Someone teases you for taking a screen-break, calling you boring for 'logging off'.","setup":"Stand by balance, not shame. Say:","yourLine":[{"text":"\"I'm not quitting, I'm just choosing when to be on. Balance, not boring.\"","best":true},{"text":"\"You're right, I'll just stay on so I don't miss anything.\""}],"relearn":"The aim is balance, not abstinence; a break is a choice, not a flaw."},
  {"id":"dc-1314","cat":"grow-the-journey","type":"role-play","persona":"any","source":"owning a slip","hook":"A friend points out that something you reshared last week turned out to be fake.","setup":"Repair without shame. Say:","yourLine":[{"text":"\"You're right, thanks, I'll post a correction and I'll know the tell next time.\"","best":true},{"text":"\"Whatever, everyone shares stuff, it's not a big deal.\""}],"relearn":"If you spread something false, correct it openly and learn the tell; no shame, just repair."},
  {"id":"dc-1315","cat":"grow-the-journey","type":"role-play","persona":"any","source":"critical not cynical","hook":"A friend, newly sceptical, declares that 'everything online is a lie and everyone's fake'.","setup":"Pull them from cynical back to critical. Say:","yourLine":[{"text":"\"We can question what we see without deciding the whole world's rotten.\"","best":true},{"text":"\"Yeah, trust no one, it's all fake anyway.\""}],"relearn":"Be critical, not cynical: question clearly without giving up on the good."},
  {"id":"dc-1316","cat":"grow-the-journey","type":"role-play","persona":"any","source":"handover confidence","hook":"A younger friend asks, 'But how will you know what to do when something totally new comes along?'","setup":"Speak your readiness. Say:","yourLine":[{"text":"\"I'll run the same questions: who made it, what's the trick, what's true.\"","best":true},{"text":"\"Honestly, I'll probably just be lost, like everyone.\""}],"relearn":"The Decoder applies to anything; you carry the questions for life."},
  {"id":"dc-1317","cat":"grow-the-journey","type":"sort","persona":"any","source":"wise citizen or not","hook":"Sort: is this how a wise digital citizen acts, or not yet?","items":[{"id":"a","text":"Reads the machine and the message"},{"id":"b","text":"Believes whatever's trending"},{"id":"c","text":"Uses tech on purpose and stays kind"},{"id":"d","text":"Spreads shocking clips unchecked"},{"id":"e","text":"Checks the source before sharing"},{"id":"f","text":"Piles on strangers in the comments"}],"bins":[{"id":"wise","label":"Wise citizen","valence":"pos"},{"id":"not","label":"Not yet","valence":"neg"}],"key":{"a":"wise","b":"not","c":"wise","d":"not","e":"wise","f":"not"},"relearn":"A wise digital citizen decodes, uses tech on purpose, and stays kind; not believes-and-spreads."},
  {"id":"dc-1318","cat":"grow-the-journey","type":"sort","persona":"any","source":"carry or leave","hook":"Sort: carry this into adult life, or leave it behind?","items":[{"id":"a","text":"The pause before you react"},{"id":"b","text":"The reflex to share when shocked"},{"id":"c","text":"Verifying the source"},{"id":"d","text":"'Looks real, so it's real'"},{"id":"e","text":"Your digital-life charter"},{"id":"f","text":"'I'm too smart to be fooled'"}],"bins":[{"id":"carry","label":"Carry forward","valence":"pos"},{"id":"leave","label":"Leave behind","valence":"neg"}],"key":{"a":"carry","b":"leave","c":"carry","d":"leave","e":"carry","f":"leave"},"relearn":"Carry the pause, verifying, and your charter; leave the shock-share reflex and false confidence behind."},
  {"id":"dc-1319","cat":"grow-the-journey","type":"sort","persona":"any","source":"balance or extreme","hook":"Sort: is this balance, or an extreme to avoid?","items":[{"id":"a","text":"Choosing when to be online"},{"id":"b","text":"Quitting all screens to be 'safe'"},{"id":"c","text":"Curating a feed that lifts you"},{"id":"d","text":"Doomscrolling for hours"},{"id":"e","text":"Taking breaks and sleeping well"},{"id":"f","text":"Never logging off in case you miss out"}],"bins":[{"id":"balance","label":"Balance","valence":"pos"},{"id":"extreme","label":"Extreme to avoid","valence":"neg"}],"key":{"a":"balance","b":"extreme","c":"balance","d":"extreme","e":"balance","f":"extreme"},"relearn":"The aim is balance, not abstinence and not endless scrolling; use the good, guard against the rest."},
  {"id":"dc-1320","cat":"grow-the-journey","type":"sort","persona":"any","source":"critical or cynical","hook":"Sort: is this being critical, or tipping into cynical?","items":[{"id":"a","text":"Checking who made a claim"},{"id":"b","text":"Deciding everyone online is fake"},{"id":"c","text":"Staying open to the good online"},{"id":"d","text":"Trusting no one ever"},{"id":"e","text":"Questioning, then deciding fairly"},{"id":"f","text":"Sneering at anything sincere"}],"bins":[{"id":"critical","label":"Critical","valence":"pos"},{"id":"cynical","label":"Cynical","valence":"neg"}],"key":{"a":"critical","b":"cynical","c":"critical","d":"cynical","e":"critical","f":"cynical"},"relearn":"Critical, not cynical: question clearly while staying open to the good."},
  {"id":"dc-1321","cat":"grow-the-journey","type":"sort","persona":"any","source":"unlearn or relearn","hook":"Sort: is this a myth you unlearned, or a truth you relearned?","items":[{"id":"a","text":"Trending equals true"},{"id":"b","text":"Trending measures spread, not truth"},{"id":"c","text":"You can spot any fake by looking"},{"id":"d","text":"Verify the source, not the look"},{"id":"e","text":"I'm too smart to be manipulated"},{"id":"f","text":"Everyone is targeted"}],"bins":[{"id":"myth","label":"Myth unlearned","valence":"neg"},{"id":"truth","label":"Truth relearned","valence":"pos"}],"key":{"a":"myth","b":"truth","c":"myth","d":"truth","e":"myth","f":"truth"},"relearn":"For every myth you unlearned, you relearned the truth that replaces it."},
  {"id":"dc-1322","cat":"grow-the-journey","type":"sort","persona":"any","source":"decoder or passive","hook":"Sort: is this an active decoder, or a passive target?","items":[{"id":"a","text":"Asks 'who benefits?' before believing"},{"id":"b","text":"Forwards whatever feels urgent"},{"id":"c","text":"Pauses before reacting"},{"id":"d","text":"Reacts the instant something lands"},{"id":"e","text":"Verifies a viral claim first"},{"id":"f","text":"Believes it because a friend sent it"}],"bins":[{"id":"decoder","label":"Active decoder","valence":"pos"},{"id":"passive","label":"Passive target","valence":"neg"}],"key":{"a":"decoder","b":"passive","c":"decoder","d":"passive","e":"decoder","f":"passive"},"relearn":"Any Decoder question makes you an active decoder, not a passive target."},
  {"id":"dc-1323","cat":"grow-the-journey","type":"sort","persona":"any","source":"kind or cruel close","hook":"Sort: in a heated thread, is this the kind move or the cruel one?","items":[{"id":"a","text":"Disagree without tearing the person down"},{"id":"b","text":"Join the pile-on because they're wrong"},{"id":"c","text":"Question the idea, not the person"},{"id":"d","text":"Mock someone to win the thread"},{"id":"e","text":"Step back when it gets ugly"},{"id":"f","text":"Screenshot to humiliate them later"}],"bins":[{"id":"kind","label":"Kind move","valence":"pos"},{"id":"cruel","label":"Cruel move","valence":"neg"}],"key":{"a":"kind","b":"cruel","c":"kind","d":"cruel","e":"kind","f":"cruel"},"relearn":"Be both critical and kind: question the idea, never crush the person."},
  {"id":"dc-1324","cat":"grow-the-journey","type":"spot","persona":"any","source":"cynicism creep","relearn":"Critical, not cynical: question clearly while staying open to the good.","hook":"Spot the two lines where 'critical' has tipped into cynical.","scene":[{"id":"a","text":"\"I'll check who made this before I believe it.\"","trick":false},{"id":"b","text":"\"Everyone online is fake, so trust no one.\"","trick":true},{"id":"c","text":"\"I can question this and still enjoy the good stuff.\"","trick":false},{"id":"d","text":"\"It's all lies; no point looking for truth.\"","trick":true},{"id":"e","text":"\"I'll stay sceptical but stay kind.\"","trick":false}],"why":"'All fake' and 'no point looking' is cynicism, not the critical, open habit."},
  {"id":"dc-1325","cat":"grow-the-journey","type":"spot","persona":"any","source":"abstinence creep","relearn":"The aim is balance, not abstinence: use the good, guard against the rest.","hook":"Spot the two lines that swap balance for the 'just quit screens' trap.","scene":[{"id":"a","text":"\"I choose when I'm online and when I'm off.\"","trick":false},{"id":"b","text":"\"The only safe move is to delete everything.\"","trick":true},{"id":"c","text":"\"I curate my feed so it lifts me.\"","trick":false},{"id":"d","text":"\"Real wisdom is quitting the internet.\"","trick":true},{"id":"e","text":"\"I take breaks, then come back on purpose.\"","trick":false}],"why":"'Delete everything' and 'quit' are abstinence; the aim is balance."},
  {"id":"dc-1326","cat":"grow-the-journey","type":"spot","persona":"any","source":"shame creep","relearn":"The pull is by design, not a weakness; a slip is repair, not shame.","hook":"Spot the two lines that blame yourself instead of seeing the design, catch them.","scene":[{"id":"a","text":"\"The pull is by design, not my weakness.\"","trick":false},{"id":"b","text":"\"I scrolled too long, I'm just hopeless.\"","trick":true},{"id":"c","text":"\"If my mood dips, I'll adjust and reach out.\"","trick":false},{"id":"d","text":"\"I got fooled once, so I'm an idiot.\"","trick":true},{"id":"e","text":"\"A slip is repair, not shame.\"","trick":false}],"why":"'I'm hopeless' and 'I'm an idiot' are shame; the truth is it's by design, not your fault, and a slip is just repair."},
  {"id":"dc-1327","cat":"grow-the-journey","type":"spot","persona":"any","source":"finished-learning myth","relearn":"Decoding is lifelong; the tricks evolve, so you keep reading.","hook":"Spot the two lines that wrongly say the decoding is 'done', catch them.","scene":[{"id":"a","text":"\"I'll keep reading the feed as the tricks evolve.\"","trick":false},{"id":"b","text":"\"I finished the game, so I'm done decoding.\"","trick":true},{"id":"c","text":"\"Learning never stops, and that's good.\"","trick":false},{"id":"d","text":"\"I'm grown now, no need to question media.\"","trick":true},{"id":"e","text":"\"New apps just mean new things to decode.\"","trick":false}],"why":"'Done decoding' and 'no need to question' are the myth; decoding is lifelong."},
  {"id":"dc-1328","cat":"grow-the-journey","type":"spot","persona":"any","source":"believe-and-spread","relearn":"A wise citizen checks the source first, instead of believing-and-spreading.","hook":"Spot the two believe-and-spread reflexes a wise citizen would catch.","scene":[{"id":"a","text":"\"I'll check the source before I share.\"","trick":false},{"id":"b","text":"\"It's shocking, so I'll forward it now.\"","trick":true},{"id":"c","text":"\"Trending doesn't mean it's true.\"","trick":false},{"id":"d","text":"\"A friend sent it, so it must be real.\"","trick":true},{"id":"e","text":"\"I'll pause before I react.\"","trick":false}],"why":"'Forward it now' and 'a friend sent it, so it's real' are believe-and-spread; a wise citizen checks first."},
  {"id":"dc-1329","cat":"grow-the-journey","type":"spot","persona":"any","source":"charter vs winging it","relearn":"A few real charter principles beat winging it; that's what makes them stick.","hook":"Spot the two lines that ditch the charter for 'I'll just wing it', catch them.","scene":[{"id":"a","text":"\"I check before sharing, every time.\"","trick":false},{"id":"b","text":"\"Rules are pointless, I'll just go with the flow.\"","trick":true},{"id":"c","text":"\"I use my phone on purpose.\"","trick":false},{"id":"d","text":"\"No need to decide anything, I'll react in the moment.\"","trick":true},{"id":"e","text":"\"I stay kind even when I disagree.\"","trick":false}],"why":"'Go with the flow' and 'react in the moment' ditch the charter; principles make it stick."},
  {"id":"dc-1330","cat":"grow-the-journey","type":"spot","persona":"any","source":"too-smart trap","relearn":"Everyone is targeted; 'I'm too smart' is what manipulators count on.","hook":"Spot the two over-confident lines manipulators count on, the ones to catch.","scene":[{"id":"a","text":"\"Everyone is targeted, including me.\"","trick":false},{"id":"b","text":"\"I'm too smart to ever be manipulated.\"","trick":true},{"id":"c","text":"\"Knowing the tell is my real defence.\"","trick":false},{"id":"d","text":"\"Scams only fool gullible people, not me.\"","trick":true},{"id":"e","text":"\"I verify the source, not my gut.\"","trick":false}],"why":"'Too smart to be manipulated' and 'only fools gullible people' are exactly the over-confidence manipulators exploit."},
  {"id":"dc-1331","cat":"grow-the-journey","type":"spot","persona":"any","source":"trust-the-look trap","relearn":"Verify the source, not your eye; the deepfake arms race beats the eye.","hook":"Spot the two lines that trust the eye over the source, catch them.","scene":[{"id":"a","text":"\"I'll verify the source before I believe it.\"","trick":false},{"id":"b","text":"\"It looks completely real, so it must be.\"","trick":true},{"id":"c","text":"\"AI can fake a convincing video now.\"","trick":false},{"id":"d","text":"\"If I can't tell it's fake, it's real.\"","trick":true},{"id":"e","text":"\"The durable skill is checking, not looking.\"","trick":false}],"why":"'Looks real' and 'can't tell, so it's real' trust the eye; the arms race beats the eye, so verify the source."},
  {"id":"dc-1332","cat":"grow-the-journey","type":"reflect","persona":"any","source":"gratitude close","hook":"Lensy: before you go, is there a moment from this journey you're quietly glad you learned?","prompt":"What do you think?","options":["The pause","Naming the trick","Being kind"],"affirm":"Whatever stayed with you is yours to keep. You did the growing; I just walked beside you. Go well, decoder.","relearn":"What you learned is yours to keep; you did the growing."},
  {"id":"dc-1333","cat":"grow-the-journey","type":"reflect","persona":"any","source":"agency over paranoia","hook":"Lensy: the feed is engineered to use you. But you learned to read it and use it instead. Feel that power?","prompt":"What do you think?","options":["Yes","I read it now","I'm not the target"],"affirm":"Knowing the feed is designed lets you use it instead of being used. That's agency, not paranoia, and it's yours.","relearn":"Knowing the feed is designed lets you use it instead of being used."},
  {"id":"dc-1350","cat":"the-decoder","type":"branch","hook":"The Decoder. A 'free iPhone, claim now' link lands in your DMs.","options":[{"text":"Ask who benefits and check the source first","consequence":"You see the bait before it costs you.","outcome":"safe","best":true},{"text":"Tap it fast before the offer 'expires'","consequence":"Decode first: 'too good + hurry' is the tell, not a reason to rush."}],"debrief":"'Who benefits?' and a source check defuse a scam before the urgency does its job.","relearn":"Run the Decoder on 'too good to be true + urgency'; ask who benefits.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1351","cat":"the-decoder","type":"branch","hook":"The Decoder. A reel claims a home remedy 'cures' a serious illness.","options":[{"text":"Check the source, then verify with a doctor or trusted health service","consequence":"You judge the claim on evidence, not views.","outcome":"verified","best":true},{"text":"Trust it because the video has millions of views","consequence":"Trending isn't true; verify a health claim with a reliable source."}],"debrief":"A viral health claim earns belief only after the source and facts check out.","relearn":"Run the full Decoder on viral health claims; verify before believing.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1352","cat":"the-decoder","type":"branch","hook":"The Decoder. Your favourite influencer posts a political 'fact' you like.","options":[{"text":"Decode it anyway: who made it, why, is it verified?","consequence":"You like them and still check the claim.","outcome":"fair","best":true},{"text":"Accept it because you trust them","consequence":"Decode the content, not the messenger; trusted people share unchecked things too."}],"debrief":"The Decoder judges the claim itself, even when you like who shared it.","relearn":"Decode the content regardless of who shared it.","persona":"any","source":"source vs messenger"},
  {"id":"dc-1353","cat":"the-decoder","type":"branch","hook":"The Decoder. A clip 'proves' a celebrity said something shocking.","options":[{"text":"Verify the source before believing; a clip can be AI-made","consequence":"You don't let your eyes be the only judge.","outcome":"checked","best":true},{"text":"Believe it because the video looks real","consequence":"'Looks real' isn't proof now; verify the source, not the look."}],"debrief":"In the Decoder, a convincing clip is a reason to verify the source, not to trust it.","relearn":"Verify the source; 'looks real' is no longer proof.","persona":"Veer","source":"applying the decoder"},
  {"id":"dc-1354","cat":"the-decoder","type":"branch","hook":"The Decoder. An outrage post is built to make you furious and hit share.","options":[{"text":"Pause, ask who gains from your anger, then decide","consequence":"You see the design and choose on purpose.","outcome":"clear","best":true},{"text":"Share instantly while you're angry","consequence":"Engineered outrage wants the instant share; pause and decode first."}],"debrief":"A built-in pause is what stops engineered outrage from using you.","relearn":"Build in a short pause; decoding beats reacting in a hurry.","persona":"any","source":"the pause"},
  {"id":"dc-1355","cat":"the-decoder","type":"branch","hook":"The Decoder. A family group forwards a 'this is urgent, share with all' message.","options":[{"text":"Check it before forwarding, kindly tell them if it's false","consequence":"You stop a false forward without shaming anyone.","outcome":"repair","best":true},{"text":"Forward it on so you're not the one who held it back","consequence":"Verify before you forward; 'share with all' urgency is a tell to slow down."}],"debrief":"Verify-before-forward, applied even to family, keeps false messages from spreading.","relearn":"Verify before you forward, regardless of who sent it.","persona":"any","source":"verify before forward"},
  {"id":"dc-1356","cat":"the-decoder","type":"branch","hook":"The Decoder. You realise a post you shared yesterday was false.","options":[{"text":"Correct it openly and note the tell you missed","consequence":"You repair it and decode better next time.","outcome":"repair","best":true},{"text":"Quietly delete it and hope nobody noticed","consequence":"Correct it openly instead; repair beats hiding, and there's no shame in it."}],"debrief":"Decoding includes the repair: correct it openly and learn the tell.","relearn":"If you spread something false, correct it openly and learn the tell, no shame.","persona":"any","source":"repair"},
  {"id":"dc-1357","cat":"the-decoder","type":"branch","hook":"The Decoder. A checkout page has a pre-ticked 'add insurance ₹299' box.","options":[{"text":"Spot the dark pattern and untick what you didn't choose","consequence":"You catch the design trick before paying for it.","outcome":"caught","best":true},{"text":"Leave it ticked; it was already on so it must be needed","consequence":"A pre-ticked box is a dark pattern; the Decoder spots and unticks it."}],"debrief":"The Decoder names the technique, a pre-ticked box, and undoes it.","relearn":"Spot dark patterns like pre-ticked boxes; choose on purpose.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1358","cat":"the-decoder","type":"branch","hook":"The Decoder. A screenshot 'quote' from a leader is spreading fast.","options":[{"text":"Search whether they actually said it before reacting","consequence":"You check the claim at its source.","outcome":"verified","best":true},{"text":"React to it because everyone else already is","consequence":"A screenshot is easy to fake; verify the quote at the source first."}],"debrief":"The Decoder verifies a quote at the source before letting it move you.","relearn":"Verify a viral quote at its source before reacting or sharing.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1359","cat":"the-decoder","type":"branch","hook":"The Decoder. You only have five seconds and a claim feels true.","options":[{"text":"Take the five-second pause; 'feels true' isn't decoded","consequence":"A short pause is enough to not get fooled.","outcome":"habit","best":true},{"text":"Go with the feeling since you're in a hurry","consequence":"'Feels true' isn't checked; a few seconds of the Decoder beats being fooled."}],"debrief":"Even a few seconds of pause turns a gut reaction into a decoded one.","relearn":"Build in a short pause; decoding beats reacting in a hurry.","persona":"any","source":"the pause"},
  {"id":"dc-1360","cat":"the-decoder","type":"branch","hook":"The Decoder. A 'survey' offers a prize if you enter your bank OTP.","options":[{"text":"Stop: no real prize needs your OTP; report it via 1930","consequence":"You name the scam and route it to help.","outcome":"safe","best":true},{"text":"Enter it quickly so you don't miss the prize","consequence":"An OTP request is the scam tell; never share it, report scams via cybercrime 1930."}],"debrief":"The Decoder spots the OTP-bait scam and uses the real report route.","relearn":"No genuine prize needs your OTP; report scams: cybercrime 1930 / cybercrime.gov.in.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1361","cat":"the-decoder","type":"branch","hook":"The Decoder. A claim flatters exactly what you already believe.","options":[{"text":"Decode it harder; agreeing makes me less likely to check","consequence":"You catch your own bubble at work.","outcome":"aware","best":true},{"text":"Accept it; it matches what I already think","consequence":"The bubble feels true by design; decode claims you agree with too."}],"debrief":"The Decoder works hardest on the claims that flatter your existing view.","relearn":"Decode claims you agree with too; agreement isn't verification.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1362","cat":"the-decoder","type":"branch","hook":"The Decoder. A friend asks how you didn't fall for an obvious fake.","options":[{"text":"Teach them the Decoder: who, why, how, true, act","consequence":"The habit spreads and protects them too.","outcome":"shared","best":true},{"text":"Just say you got lucky","consequence":"It wasn't luck; the Decoder is a habit you can pass on."}],"debrief":"Passing the Decoder on turns one decoder into many.","relearn":"The Decoder is a learnable habit you can teach, not luck.","persona":"any","source":"passing it on"},
  {"id":"dc-1363","cat":"the-decoder","type":"branch","hook":"The Decoder. An app nags you with a fake red badge to open it.","options":[{"text":"Name the hook; the badge is engagement design, open on purpose","consequence":"You decide when to open, not the badge.","outcome":"control","best":true},{"text":"Open it right away because the badge says 1","consequence":"A nudge badge is attention-capture design; decode it and choose on purpose."}],"debrief":"The Decoder applies to your own apps: name the hook, then choose.","relearn":"Name the design hook and use the app on purpose, not on its cue.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1364","cat":"the-decoder","type":"branch","hook":"The Decoder. A 'doctor' account sells a supplement that 'fixes everything'.","options":[{"text":"Ask who benefits and check if the account is verified","consequence":"You see the sales motive behind the white coat.","outcome":"checked","best":true},{"text":"Buy it; a doctor wouldn't lie online","consequence":"Anyone can pose as a doctor online; ask who benefits and verify."}],"debrief":"'Who benefits?' cuts through a costume; the Decoder checks the account, not the look.","relearn":"Ask who benefits; a white-coat look online isn't proof.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1365","cat":"the-decoder","type":"branch","hook":"The Decoder. You've decoded a post and it checks out as true.","options":[{"text":"Decide how to act on it, calmly and on purpose","consequence":"You finish the Decoder with your own choice.","outcome":"decided","best":true},{"text":"Stop at 'it's true' and do nothing with it","consequence":"The last step is 'how will I act?'; decoding ends in a decision, not a shrug."}],"debrief":"The Decoder's final move is your own deliberate action.","relearn":"The Decoder ends with how you'll act, your decision, not just 'it's true'.","persona":"any","source":"the decoder"},
  {"id":"dc-1366","cat":"the-decoder","type":"branch","hook":"The Decoder. A new app demands access to your contacts and location.","options":[{"text":"Decode the ask; grant only what the app truly needs","consequence":"You protect your data by default.","outcome":"guarded","best":true},{"text":"Tap 'allow all' so it stops asking","consequence":"Decode the permission ask; grant only the data the app genuinely needs."}],"debrief":"The Decoder applies to permissions: question the ask, grant the minimum.","relearn":"Decode permission asks; grant only the data truly needed.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1367","cat":"the-decoder","type":"branch","hook":"The Decoder. You want to make decoding automatic, not a chore.","options":[{"text":"Run it on small posts daily until the pause is a reflex","consequence":"It becomes second nature.","outcome":"habit","best":true},{"text":"Save it only for 'important' posts","consequence":"Practising on small posts is what makes the pause automatic when it matters."}],"debrief":"Daily reps on ordinary posts turn the Decoder into a reflex for life.","relearn":"Practise the Decoder daily so the pause becomes automatic.","persona":"any","source":"the pause"},
  {"id":"dc-1368","cat":"the-decoder","type":"match","hook":"Match each post to the Decoder question it most needs.","pairs":[{"left":"'Miracle cure' reel","right":"Who benefits from this?"},{"left":"Shocking clip of a leader","right":"Is the source verified?"},{"left":"Pre-ticked add-on at checkout","right":"What's the technique?"},{"left":"A claim that flatters my side","right":"Am I in a bubble?"},{"left":"A post that makes me furious","right":"Should I pause first?"}],"relearn":"Each kind of post calls for a Decoder question: benefit, source, technique, bubble, pause.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1369","cat":"the-decoder","type":"match","hook":"Match each manipulation tell to the Decoder move that beats it.","pairs":[{"left":"Fake countdown timer","right":"Slow down and ignore the clock"},{"left":"'Too good to be true'","right":"Ask who benefits"},{"left":"Deepfake-style clip","right":"Verify the source"},{"left":"Endless us-vs-them slogans","right":"Name the propaganda tell"},{"left":"Pre-ticked box","right":"Untick what you didn't choose"}],"relearn":"Every tell has a counter-move: slow down, ask who benefits, verify, name it, untick.","persona":"Veer","source":"applying the decoder"},
  {"id":"dc-1370","cat":"the-decoder","type":"match","hook":"Match each Decoder step to what skipping it would cost.","pairs":[{"left":"Skip 'who & why'","right":"Miss the hidden motive"},{"left":"Skip the algorithm check","right":"Mistake your bubble for the world"},{"left":"Skip 'what's the manipulation'","right":"Fall for the technique"},{"left":"Skip 'what's true'","right":"Believe a convincing fake"},{"left":"Skip 'how will I act'","right":"React instead of decide"}],"relearn":"Skip any step and you miss a motive, a bubble, a trick, a fake, or a calm choice.","persona":"any","source":"the decoder"},
  {"id":"dc-1371","cat":"the-decoder","type":"match","hook":"Match each everyday moment to the Decoder habit it calls for.","pairs":[{"left":"A forwarded health 'fact'","right":"Verify before forwarding"},{"left":"A flattering claim about my team","right":"Decode it anyway"},{"left":"A friend you trust shares a fake","right":"Judge the content, not them"},{"left":"A five-second urge to share","right":"Take the pause"},{"left":"A post you shared that was false","right":"Correct it openly"}],"relearn":"The Decoder shows up daily: verify, decode anyway, judge content, pause, repair.","persona":"any","source":"the decoder"},
  {"id":"dc-1372","cat":"the-decoder","type":"match","hook":"Match the Decoder question to what makes you, not the feed.","pairs":[{"left":"Who made this & why?","right":"You read the intent"},{"left":"How was it served to me?","right":"You see the machine"},{"left":"What's the manipulation?","right":"You name the trick"},{"left":"What's actually true?","right":"You hold the facts"},{"left":"How will I act?","right":"You make the choice"}],"relearn":"Each Decoder question hands the choice back to you, not the feed.","persona":"any","source":"agency"},
  {"id":"dc-1373","cat":"the-decoder","type":"match","hook":"Match each 'too good to be true' tell to the real story behind it.","pairs":[{"left":"'You alone are chosen'","right":"It went to thousands"},{"left":"'Offer ends in 02:59'","right":"The timer just resets"},{"left":"'Guaranteed, zero risk'","right":"Nothing is guaranteed"},{"left":"'Send a small fee to claim'","right":"Real prizes never charge you"},{"left":"'Verified by experts'","right":"No expert is named"}],"relearn":"Scam flattery hides the real story: mass-sent, resetting timers, no proof, hidden fees.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1374","cat":"the-decoder","type":"match","hook":"Match each decoded reflex to the passive habit it replaces.","pairs":[{"left":"Pause then decide","right":"React on impulse"},{"left":"Check the source","right":"Trust the look"},{"left":"Ask who benefits","right":"Take it at face value"},{"left":"Verify before sharing","right":"Forward on a feeling"},{"left":"Use the app on purpose","right":"Follow every notification"}],"relearn":"Decoding swaps impulse, face-value trust and auto-forwarding for a deliberate habit.","persona":"any","source":"agency"},
  {"id":"dc-1375","cat":"the-decoder","type":"match","hook":"Match each thing the feed sells you to what the Decoder reveals.","pairs":[{"left":"'Trending now'","right":"Spread, not truth"},{"left":"'Just for you'","right":"Chosen to keep you scrolling"},{"left":"'Everyone's talking about it'","right":"Engineered, not organic"},{"left":"'Limited time'","right":"Manufactured urgency"},{"left":"'People like you also liked'","right":"A bubble, not the world"}],"relearn":"The Decoder reveals trending, 'for you' and 'limited time' as design, not truth.","persona":"any","source":"the decoder"},
  {"id":"dc-1376","cat":"the-decoder","type":"match","hook":"Match each Decoder habit to the lifelong payoff it gives.","pairs":[{"left":"Decode before believing","right":"Harder to fool, for life"},{"left":"Ask who benefits","right":"You see the motive"},{"left":"Pause before sharing","right":"You spread less false stuff"},{"left":"Verify the source","right":"You survive the fake arms race"},{"left":"Stay critical and kind","right":"You decode without cynicism"}],"relearn":"The Decoder's payoffs last for life: harder to fool, clearer, kinder, less fooled.","persona":"any","source":"agency"},
  {"id":"dc-1377","cat":"the-decoder","type":"spot","hook":"Spot the two lines a scam DM uses to rush you.","scene":[{"id":"a","text":"'Take your time, no pressure'","trick":false},{"id":"b","text":"'Pay now or lose it forever'","trick":true},{"id":"c","text":"'You can verify this independently'","trick":false},{"id":"d","text":"'Only 2 minutes left, claim fast'","trick":true},{"id":"e","text":"'Here's our official, traceable address'","trick":false}],"why":"'Pay now or lose it' and a fake countdown are urgency tricks; the others invite checking.","relearn":"Manufactured urgency is a scam tell; slow down and verify.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1378","cat":"the-decoder","type":"spot","hook":"Spot the two moves that skip the Decoder.","scene":[{"id":"a","text":"Asked who made it and why","trick":false},{"id":"b","text":"Shared because it made me angry","trick":true},{"id":"c","text":"Checked it against a reliable outlet","trick":false},{"id":"d","text":"Believed it because a friend sent it","trick":true},{"id":"e","text":"Paused before forwarding","trick":false}],"why":"Sharing on anger and believing 'a friend sent it' skip the Decoder; the rest are it.","relearn":"Decode the content regardless of who shared it or how it made you feel.","persona":"any","source":"the decoder"},
  {"id":"dc-1379","cat":"the-decoder","type":"spot","hook":"Spot the two dark patterns on this checkout page.","scene":[{"id":"a","text":"A clear total before you pay","trick":false},{"id":"b","text":"A pre-ticked 'add donation ₹49' box","trick":true},{"id":"c","text":"An easy, visible 'remove item' button","trick":false},{"id":"d","text":"A fake 'only 1 left, 3 viewing' badge","trick":true},{"id":"e","text":"A plainly stated refund policy","trick":false}],"why":"The pre-ticked box and the fake scarcity badge are dark patterns; the rest are honest design.","relearn":"Pre-ticked boxes and fake scarcity are dark patterns; spot and undo them.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1380","cat":"the-decoder","type":"spot","hook":"Spot the two tells that a 'news' clip might be fake.","scene":[{"id":"a","text":"Named source you can look up","trick":false},{"id":"b","text":"No source, just 'a friend sent this'","trick":true},{"id":"c","text":"Matches reports from several outlets","trick":false},{"id":"d","text":"Shocking, with 'share before it's deleted'","trick":true},{"id":"e","text":"A date and place you can verify","trick":false}],"why":"No source plus 'share before deleted' are fake-clip tells; the others let you verify.","relearn":"No source plus urgency are deepfake/fake tells; verify the source.","persona":"Veer","source":"applying the decoder"},
  {"id":"dc-1381","cat":"the-decoder","type":"spot","hook":"Spot the two lines that are propaganda tells, not facts.","scene":[{"id":"a","text":"Here are the numbers and where they're from","trick":false},{"id":"b","text":"'They are the enemy of all of us'","trick":true},{"id":"c","text":"Different sides are quoted fairly","trick":false},{"id":"d","text":"The same slogan, repeated ten times","trick":true},{"id":"e","text":"You're invited to check it yourself","trick":false}],"why":"'They are the enemy' and endless slogans are propaganda tells; facts and sources aren't.","relearn":"Us-vs-them framing and repeated slogans are propaganda tells, not truth.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1382","cat":"the-decoder","type":"spot","hook":"Spot the two signs a 'giveaway' account is a scam.","scene":[{"id":"a","text":"Links only to its official, named site","trick":false},{"id":"b","text":"Asks for your OTP to 'confirm'","trick":true},{"id":"c","text":"Never asks for passwords or codes","trick":false},{"id":"d","text":"A near-copy handle with an extra letter","trick":true},{"id":"e","text":"Has a long, consistent posting history","trick":false}],"why":"Asking for your OTP and a copycat handle are scam signs; the rest are normal and safe.","relearn":"OTP requests and copycat handles are scam signs; never share codes, report via 1930.","persona":"Arjun","source":"applying the decoder"},
  {"id":"dc-1383","cat":"the-decoder","type":"spot","hook":"Spot the two habits that keep you in a filter bubble.","scene":[{"id":"a","text":"Following a few accounts you disagree with","trick":false},{"id":"b","text":"Only watching what's served to you","trick":true},{"id":"c","text":"Reading past the first opinion you meet","trick":false},{"id":"d","text":"Blocking every view you don't like","trick":true},{"id":"e","text":"Searching out a topic on purpose","trick":false}],"why":"Only watching what's fed to you and blocking all other views harden the bubble; the rest open it.","relearn":"Deliberately seek other views; you can't weigh what you're never shown.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1384","cat":"the-decoder","type":"reflect","hook":"Lensy: the Decoder is five small questions you can run on anything. Ready to own it?","prompt":"What do you think?","options":["Yes","I've got this","For life"],"affirm":"Five small questions, run on anything, are yours to keep for life.","relearn":"'Decode anything' is one master habit you carry for life.","persona":"any","source":"master habit"},
  {"id":"dc-1385","cat":"the-decoder","type":"reflect","hook":"Lensy: when a post makes you angry fast, what will you do first?","prompt":"Pick one.","options":["Pause before sharing","Check who posted it","Ask what they want","Cool off, then decide"],"affirm":"A deliberate pause is the Decoder in action; the heat fades and the read stays.","relearn":"Pausing on a strong reaction is the Decoder working, not weakness.","persona":"any","source":"decoder / pause"},
  {"id":"dc-1386","cat":"the-decoder","type":"reflect","hook":"Lensy: think of the last thing that made you want to instantly share. Picture pausing first.","prompt":"How does the pause feel?","options":["Calmer","In control","Wiser"],"affirm":"A short pause turns a reaction into a decision, every time.","relearn":"Build in a short pause; decoding beats reacting in a hurry.","persona":"any","source":"the pause"},
  {"id":"dc-1387","cat":"the-decoder","type":"reflect","hook":"Lensy: 'who benefits?' is a question you can ask of almost anything.","prompt":"Where would you use it?","options":["A reel","An ad","A forward","A headline"],"affirm":"Asking who benefits works on a reel, an ad, a forward or a headline alike.","relearn":"Ask 'who benefits?' of anything; it's the Decoder's sharpest question.","persona":"any","source":"who benefits"},
  {"id":"dc-1388","cat":"the-decoder","type":"reflect","hook":"Lensy: even a friend you trust can pass on a fake without meaning to.","prompt":"What will you decode?","options":["The content","The claim","The source"],"affirm":"You can love who shared it and still decode the content itself.","relearn":"Decode the content, regardless of who shared it.","persona":"any","source":"source vs messenger"},
  {"id":"dc-1389","cat":"the-decoder","type":"reflect","hook":"Lensy: the Decoder doesn't make you cynical, it makes you clear.","prompt":"What do you keep?","options":["Curiosity","Kindness","An open mind"],"affirm":"You can stay curious, kind and open while still checking everything.","relearn":"Be critical and kind; decoding is clarity, not cynicism.","persona":"any","source":"critical not cynical"},
  {"id":"dc-1390","cat":"the-decoder","type":"reflect","hook":"Lensy: imagine teaching the Decoder to someone younger than you.","prompt":"What's the first thing you'd say?","options":["Who made it?","Why's it here?","Is it true?"],"affirm":"Whatever you'd start with, you've understood the Decoder well enough to pass it on.","relearn":"The Decoder is a habit you understand well enough to teach.","persona":"any","source":"passing it on"},
  {"id":"dc-1391","cat":"the-decoder","type":"reflect","hook":"Lensy: the information world will keep changing for your whole life.","prompt":"How does lifelong decoding sit with you?","options":["Exciting","Reassuring","I'm ready"],"affirm":"Decoding is a lifelong habit, and a changing world is a good reason to keep it sharp.","relearn":"Learning never stops; decoding is a habit for life.","persona":"any","source":"lifelong"},
  {"id":"dc-1392","cat":"the-decoder","type":"reflect","hook":"Lensy: with the Decoder, the feed works for you, not on you.","prompt":"What does that feel like?","options":["Powerful","Free","In charge"],"affirm":"The Decoder is what keeps the information world working for you, not on you.","relearn":"The Decoder keeps the information world working for you, not on you.","persona":"any","source":"agency"},
  {"id":"dc-1393","cat":"the-decoder","type":"reflect","hook":"Lensy: 'looks real' isn't proof anymore, and that's okay, you have a better tool.","prompt":"What do you trust instead?","options":["The source","Verification","Cross-checking"],"affirm":"Trusting the verified source, not your eye, is how you win the fakes arms race.","relearn":"Verify the source; 'looks real' is no longer proof.","persona":"any","source":"verify the source"},
  {"id":"dc-1394","cat":"the-decoder","type":"reflect","hook":"Lensy: noticing the bubble is the first step out of it.","prompt":"How will you widen your view?","options":["Follow other voices","Search on purpose","Read past page one"],"affirm":"Any of those breaks the bubble; you can't weigh views you're never shown.","relearn":"Deliberately seek other views to step out of the filter bubble.","persona":"any","source":"filter bubble"},
  {"id":"dc-1395","cat":"the-decoder","type":"reflect","hook":"Lensy: making a false-share right is a strength, not an embarrassment.","prompt":"What would you do?","options":["Correct it openly","Note the tell","Tell people kindly"],"affirm":"Correcting openly and learning the tell is the repair, and there's no shame in it.","relearn":"Correct a false share openly and learn the tell; no shame, just repair.","persona":"any","source":"repair"},
  {"id":"dc-1396","cat":"the-decoder","type":"reflect","hook":"Lensy: the Decoder is yours now, for any feed, any claim, any choice.","prompt":"How will you carry it?","options":["Every day","On the big stuff","As a reflex"],"affirm":"However you carry it, it's one habit that fits anything, for life.","relearn":"'Decode anything' is one habit you carry for life, for anything.","persona":"any","source":"master habit"},
  {"id":"dc-1397","cat":"the-decoder","type":"reflect","hook":"Lensy: you went from naming feelings as a kid to decoding the whole world.","prompt":"How does that growth feel?","options":["Proud","Grown","Ready for more"],"affirm":"From naming feelings to decoding the world is real growth, and it keeps going.","relearn":"You've grown from naming feelings to decoding the world.","persona":"any","source":"growth"},
  {"id":"dc-1398","cat":"the-decoder","type":"role-play","hook":"A friend is about to forward a scary 'breaking' clip to everyone.","setup":"Stop them gently. Say:","yourLine":[{"text":"\"Wait, let's check the source before we send it, fakes spread fastest.\"","best":true},{"text":"\"Just send it, it's probably fine.\""}],"relearn":"Ask to verify the source before forwarding a scary clip.","persona":"any","source":"verify before forward"},
  {"id":"dc-1399","cat":"the-decoder","type":"role-play","hook":"Your younger cousin asks how you tell what's real online.","setup":"Keep it simple. Say:","yourLine":[{"text":"\"I ask: who made it, why, and is it actually true, before I believe it.\"","best":true},{"text":"\"You just kind of know after a while.\""}],"relearn":"Teach the Decoder simply: who made it, why, and is it true?","persona":"any","source":"passing it on"},
  {"id":"dc-1400","cat":"the-decoder","type":"role-play","hook":"A relative shares a 'cure' and asks why you look unsure.","setup":"Be kind but clear. Say:","yourLine":[{"text":"\"I'd love to check it with a doctor before we trust it, can we?\"","best":true},{"text":"\"You're right, let's just believe it.\""}],"relearn":"Verify a health claim with a doctor before trusting it.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1401","cat":"the-decoder","type":"role-play","hook":"A friend is furious at an outrage post and wants you to pile on.","setup":"Slow it down. Say:","yourLine":[{"text":"\"Let's pause, who gains if we both get this angry and share?\"","best":true},{"text":"\"Yeah, let's blast them.\""}],"relearn":"Pause and ask who benefits from your anger before sharing.","persona":"any","source":"the pause"},
  {"id":"dc-1402","cat":"the-decoder","type":"role-play","hook":"A friend got an 'OTP to claim your prize' message and is about to reply.","setup":"Warn them fast. Say:","yourLine":[{"text":"\"Don't share the OTP, no real prize needs it, that's the scam.\"","best":true},{"text":"\"Go on, send it so you don't lose the prize.\""}],"relearn":"Never share an OTP; no genuine prize needs it.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1403","cat":"the-decoder","type":"role-play","hook":"You spread something yesterday that turned out false. A friend points it out.","setup":"Own it. Say:","yourLine":[{"text":"\"You're right, I'll post a correction, I missed the tell. Thanks.\"","best":true},{"text":"\"I'll just quietly delete it.\""}],"relearn":"Correct a false share openly and thank the person who flagged it.","persona":"any","source":"repair"},
  {"id":"dc-1404","cat":"the-decoder","type":"role-play","hook":"A friend says decoding everything sounds exhausting and cynical.","setup":"Reframe it. Say:","yourLine":[{"text":"\"It's not cynicism, it's just a five-second check, and it keeps me kind.\"","best":true},{"text":"\"Yeah, maybe it's not worth the effort.\""}],"relearn":"Decoding is a quick, kind check, not cynicism or hard work.","persona":"any","source":"critical not cynical"},
  {"id":"dc-1405","cat":"the-decoder","type":"sort","hook":"Sort each move: an active decoder, or a passive target?","items":[{"id":"a","text":"Checks the source"},{"id":"b","text":"Shares on a feeling"},{"id":"c","text":"Asks who benefits"},{"id":"d","text":"Believes what's trending"},{"id":"e","text":"Pauses before reacting"},{"id":"f","text":"Forwards without reading"}],"bins":[{"id":"active","label":"Active decoder","valence":"pos"},{"id":"passive","label":"Passive target","valence":"neg"}],"key":{"a":"active","b":"passive","c":"active","d":"passive","e":"active","f":"passive"},"relearn":"Checking, asking who benefits and pausing are active; feeling, trending and auto-forwarding are passive.","persona":"any","source":"agency"},
  {"id":"dc-1406","cat":"the-decoder","type":"sort","hook":"Sort each tell: a real reason to trust, or a manipulation tell?","items":[{"id":"a","text":"Named, checkable source"},{"id":"b","text":"'Offer ends in 60 seconds'"},{"id":"c","text":"Matches several outlets"},{"id":"d","text":"'Send a fee to claim'"},{"id":"e","text":"Invites you to verify"},{"id":"f","text":"'Everyone but you knows this'"}],"bins":[{"id":"trust","label":"Reason to trust","valence":"pos"},{"id":"tell","label":"Manipulation tell","valence":"neg"}],"key":{"a":"trust","b":"tell","c":"trust","d":"tell","e":"trust","f":"tell"},"relearn":"Named sources and cross-checks earn trust; countdowns, fees and FOMO lines are tells.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1407","cat":"the-decoder","type":"sort","hook":"Sort each line: real news signal, or fake-clip tell?","items":[{"id":"a","text":"Source you can look up"},{"id":"b","text":"'Share before it's deleted'"},{"id":"c","text":"Reported by many outlets"},{"id":"d","text":"No date, no place, no source"},{"id":"e","text":"A correction was posted later"},{"id":"f","text":"'Trust me, it's totally real'"}],"bins":[{"id":"signal","label":"Real signal","valence":"pos"},{"id":"fake","label":"Fake tell","valence":"neg"}],"key":{"a":"signal","b":"fake","c":"signal","d":"fake","e":"signal","f":"fake"},"relearn":"Checkable sources and corrections are signals; 'share before deleted' and 'trust me' are fake tells.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1408","cat":"the-decoder","type":"sort","hook":"Sort each design: honest, or a dark pattern?","items":[{"id":"a","text":"Clear price before you pay"},{"id":"b","text":"Pre-ticked add-on box"},{"id":"c","text":"Easy one-tap unsubscribe"},{"id":"d","text":"Fake 'only 1 left' badge"},{"id":"e","text":"Plain 'no' button, same size as 'yes'"},{"id":"f","text":"Countdown that resets on reload"}],"bins":[{"id":"honest","label":"Honest design","valence":"pos"},{"id":"dark","label":"Dark pattern","valence":"neg"}],"key":{"a":"honest","b":"dark","c":"honest","d":"dark","e":"honest","f":"dark"},"relearn":"Clear prices and easy exits are honest; pre-ticked boxes, fake scarcity and resetting timers are dark patterns.","persona":"any","source":"applying the decoder"},
  {"id":"dc-1409","cat":"the-decoder","type":"sort","hook":"Sort each habit: opens your view, or hardens the bubble?","items":[{"id":"a","text":"Following voices you disagree with"},{"id":"b","text":"Only watching what's served"},{"id":"c","text":"Searching a topic on purpose"},{"id":"d","text":"Blocking every other view"},{"id":"e","text":"Reading past the first opinion"},{"id":"f","text":"Sharing only what your side likes"}],"bins":[{"id":"open","label":"Opens your view","valence":"pos"},{"id":"bubble","label":"Hardens the bubble","valence":"neg"}],"key":{"a":"open","b":"bubble","c":"open","d":"bubble","e":"open","f":"bubble"},"relearn":"Following other voices and searching on purpose open your view; only-what's-served and blocking harden the bubble.","persona":"any","source":"filter bubble"},
  {"id":"dc-1410","cat":"the-decoder","type":"sort","hook":"Sort each response to a false thing you shared: repair, or hide?","items":[{"id":"a","text":"Post an open correction"},{"id":"b","text":"Quietly delete and say nothing"},{"id":"c","text":"Note the tell you missed"},{"id":"d","text":"Blame whoever sent it to you"},{"id":"e","text":"Tell the people you'd shared with"},{"id":"f","text":"Pretend it never happened"}],"bins":[{"id":"repair","label":"Repair","valence":"pos"},{"id":"hide","label":"Hide","valence":"neg"}],"key":{"a":"repair","b":"hide","c":"repair","d":"hide","e":"repair","f":"hide"},"relearn":"Correcting openly, learning the tell and telling people are repair; deleting, blaming and pretending are hiding.","persona":"any","source":"repair"},
  {"id":"dc-1411","cat":"the-decoder","type":"sort","hook":"Sort each thing: a Decoder question, or just a reaction?","items":[{"id":"a","text":"Who made this and why?"},{"id":"b","text":"This is outrageous!"},{"id":"c","text":"What's actually true here?"},{"id":"d","text":"I have to share this now"},{"id":"e","text":"How will I act on it?"},{"id":"f","text":"It feels true to me"}],"bins":[{"id":"q","label":"Decoder question","valence":"pos"},{"id":"react","label":"Just a reaction","valence":"neg"}],"key":{"a":"q","b":"react","c":"q","d":"react","e":"q","f":"react"},"relearn":"Asking who, what's true and how to act is decoding; outrage, urge-to-share and 'feels true' are reactions.","persona":"any","source":"the decoder"},
  {"id":"dc-1412","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"If everyone's sharing it, it must be true.\"","re":"Virality measures reach, not truth; check the source before you join in.","why":"Engineered outrage spreads faster than accuracy, so popularity isn't proof."},"relearn":"Going viral means it spread, not that it's true; verify before sharing.","persona":"Veer","source":"Veer's myth"},
  {"id":"dc-1413","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"The algorithm just shows me what I like.\"","re":"It shows what keeps you scrolling, which isn't the same as what's good for you.","why":"The feed optimises for watch-time and ads, not for your interests."},"relearn":"The feed serves what holds you, not what helps you; that's worth questioning.","persona":"Veer","source":"Veer's myth"},
  {"id":"dc-1414","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"If it's trending, it must be true.\"","re":"Trending measures spread, not accuracy; verify before believing.","why":"Virality tracks emotional or engineered spread, which isn't the same as truth."},"relearn":"Trending isn't true; verify before you believe.","persona":"any","source":"the machine"},
  {"id":"dc-1415","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"If a friend I trust shared it, I don't need to check.\"","re":"Decode the content; even trusted people pass on fakes unknowingly.","why":"The Decoder judges the claim, not the messenger, so a trusted source isn't a free pass."},"relearn":"Decode the content regardless of who shared it.","persona":"any","source":"source vs messenger"},
  {"id":"dc-1416","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"Decoding everything takes too long.\"","re":"A few seconds of pause is enough; it beats being fooled.","why":"The Decoder is a quick reflex, not a research project, once it's a habit."},"relearn":"Build in a short pause; a few seconds of decoding beats being fooled.","persona":"any","source":"the pause"},
  {"id":"dc-1417","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"Checking things just makes you cynical.\"","re":"Decoding is clarity; you can be critical and kind at once.","why":"Healthy scepticism removes the trick, not your trust in people; both can coexist."},"relearn":"Be critical and kind; decoding is clarity, not cynicism.","persona":"any","source":"critical not cynical"},
  {"id":"dc-1418","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"My feed shows me the whole picture.\"","re":"Your feed is a bubble; seek other views to see more.","why":"Algorithms curate for engagement, narrowing your view unless you widen it on purpose."},"relearn":"Your feed is a filter bubble; deliberately seek other views.","persona":"any","source":"filter bubble"},
  {"id":"dc-1419","cat":"the-decoder","type":"strike-rewrite","hook":"Unlearn, then rewrite.","myth":{"un":"\"If I shared something false, best to hide it.\"","re":"Correct it openly and learn the tell; repair beats hiding.","why":"Open repair stops the spread and there's no shame in it, unlike a quiet delete."},"relearn":"Correct a false share openly and learn the tell; no shame, just repair.","persona":"any","source":"repair"},
];

